var PLAYLIST = [{"ep":"bx1-01","n":"BX1-01","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-01/in1.mp3","sec":7.992,"t":"同学们好！这节课梳理人教版必修一第一章第一节——细胞是生命活动的基本单位。"},{"ep":"bx1-01","n":"BX1-01","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-01/in2.mp3","sec":7.416,"t":"高考常考细胞学说的建立过程和意义、归纳法，以及生命系统的结构层次。"},{"ep":"bx1-01","n":"BX1-01","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-01/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi1","src":"assets/audio/BX1-01/hi1.mp3","sec":11.064,"t":"考点一，细胞学说的建立过程。比利时的维萨里揭示了人体在器官水平的结构，法国的比夏指出器官由组织构成。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi2","src":"assets/audio/BX1-01/hi2.mp3","sec":9.12,"t":"1665年，英国的胡克观察软木薄片，看到许多“小室”，把它们命名为细胞。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi3","src":"assets/audio/BX1-01/hi3.mp3","sec":7.032,"t":"荷兰的列文虎克用自制显微镜观察到了细菌、红细胞和精子等活细胞。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi4","src":"assets/audio/BX1-01/hi4.mp3","sec":7.752,"t":"十九世纪三十年代，德国的施莱登和施旺分别研究植物和动物，建立了细胞学说。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi5","src":"assets/audio/BX1-01/hi5.mp3","sec":5.856,"t":"后来，德国的魏尔肖总结出：细胞通过分裂产生新细胞。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi6","src":"assets/audio/BX1-01/hi6.mp3","sec":8.4,"t":"易错：胡克看到的是死细胞，只是细胞的命名者；细胞学说的建立者是施莱登和施旺。"},{"ep":"bx1-01","n":"BX1-01","p":2,"a":"p2","id":"co1","src":"assets/audio/BX1-01/co1.mp3","sec":4.296,"t":"考点二，细胞学说的主要内容，一共三点。"},{"ep":"bx1-01","n":"BX1-01","p":2,"a":"p2","id":"co2","src":"assets/audio/BX1-01/co2.mp3","sec":8.424,"t":"第一，细胞是一个有机体，一切动植物都由细胞发育而来，并由细胞和细胞产物所构成。"},{"ep":"bx1-01","n":"BX1-01","p":2,"a":"p2","id":"co3","src":"assets/audio/BX1-01/co3.mp3","sec":9.072,"t":"第二，细胞是一个相对独立的单位，既有它自己的生命，又对与其他细胞共同组成的整体生命起作用。"},{"ep":"bx1-01","n":"BX1-01","p":2,"a":"p2","id":"co4","src":"assets/audio/BX1-01/co4.mp3","sec":7.944,"t":"第三，新细胞是由老细胞分裂产生的，这一点是在魏尔肖的观点基础上修正补充的。"},{"ep":"bx1-01","n":"BX1-01","p":2,"a":"p2","id":"co5","src":"assets/audio/BX1-01/co5.mp3","sec":9.576,"t":"易错：细胞学说说的是一切动植物，不是一切生物——病毒没有细胞，细菌等原核生物也不在其中。"},{"ep":"bx1-01","n":"BX1-01","p":3,"a":"p3","id":"me1","src":"assets/audio/BX1-01/me1.mp3","sec":8.28,"t":"考点三，细胞学说的意义。它揭示了动物和植物的统一性，从而阐明了生物界的统一性。"},{"ep":"bx1-01","n":"BX1-01","p":3,"a":"p3","id":"me2","src":"assets/audio/BX1-01/me2.mp3","sec":8.592,"t":"它使生物学研究由器官、组织水平进入细胞水平，并为后来进入分子水平打下基础。"},{"ep":"bx1-01","n":"BX1-01","p":3,"a":"p3","id":"me3","src":"assets/audio/BX1-01/me3.mp3","sec":8.376,"t":"它还为生物进化论的确立埋下了伏笔：既然都由细胞构成，生物之间就可能有共同的祖先。"},{"ep":"bx1-01","n":"BX1-01","p":3,"a":"p3","id":"me4","src":"assets/audio/BX1-01/me4.mp3","sec":9.456,"t":"考法：判断说法是否正确。易错：细胞学说没有揭示多样性，也没有揭示动植物细胞的区别。"},{"ep":"bx1-01","n":"BX1-01","p":4,"a":"p4","id":"id1","src":"assets/audio/BX1-01/id1.mp3","sec":8.592,"t":"考点四，科学方法——归纳法。归纳法是由一系列具体事实推出一般结论的思维方法。"},{"ep":"bx1-01","n":"BX1-01","p":4,"a":"p4","id":"id2","src":"assets/audio/BX1-01/id2.mp3","sec":6.864,"t":"完全归纳法，是考察了某类事物的全部对象后得出结论，结论是可信的。"},{"ep":"bx1-01","n":"BX1-01","p":4,"a":"p4","id":"id3","src":"assets/audio/BX1-01/id3.mp3","sec":8.424,"t":"不完全归纳法，只考察了部分对象就得出结论，结论可能有例外，但可以用来预测和判断。"},{"ep":"bx1-01","n":"BX1-01","p":4,"a":"p4","id":"id4","src":"assets/audio/BX1-01/id4.mp3","sec":8.592,"t":"施莱登和施旺只观察了部分动植物，就得出一切动植物都由细胞构成，用的是不完全归纳法。"},{"ep":"bx1-01","n":"BX1-01","p":4,"a":"p4","id":"id5","src":"assets/audio/BX1-01/id5.mp3","sec":10.464,"t":"解题方法：看是否考察了全部对象——没有穷尽的，就是不完全归纳法。科学研究中经常运用不完全归纳法。"},{"ep":"bx1-01","n":"BX1-01","p":5,"a":"p5","id":"li1","src":"assets/audio/BX1-01/li1.mp3","sec":10.704,"t":"考点五，生命活动离不开细胞。单细胞生物如草履虫，一个细胞就能完成运动、摄食、繁殖等全部生命活动。"},{"ep":"bx1-01","n":"BX1-01","p":5,"a":"p5","id":"li2","src":"assets/audio/BX1-01/li2.mp3","sec":7.92,"t":"多细胞生物依赖各种分化的细胞密切合作，比如缩手反射需要多种细胞协调配合。"},{"ep":"bx1-01","n":"BX1-01","p":5,"a":"p5","id":"li3","src":"assets/audio/BX1-01/li3.mp3","sec":5.592,"t":"病毒没有细胞结构，但它必须寄生在活细胞中才能增殖。"},{"ep":"bx1-01","n":"BX1-01","p":5,"a":"p5","id":"li4","src":"assets/audio/BX1-01/li4.mp3","sec":10.032,"t":"易错：病毒不能用普通培养基直接培养，要用活细胞培养；病毒是生物，但不属于生命系统的任何层次。"},{"ep":"bx1-01","n":"BX1-01","p":6,"a":"p6","id":"lv1","src":"assets/audio/BX1-01/lv1.mp3","sec":10.776,"t":"考点六，生命系统的结构层次：细胞、组织、器官、系统、个体、种群、群落、生态系统、生物圈。"},{"ep":"bx1-01","n":"BX1-01","p":6,"a":"p6","id":"lv2","src":"assets/audio/BX1-01/lv2.mp3","sec":6.84,"t":"细胞是基本的生命系统，是最基本的层次；生物圈是最大的生命系统。"},{"ep":"bx1-01","n":"BX1-01","p":6,"a":"p6","id":"lv3","src":"assets/audio/BX1-01/lv3.mp3","sec":7.608,"t":"植物没有“系统”这一层次；单细胞生物的一个细胞，既是细胞层次，又是个体层次。"},{"ep":"bx1-01","n":"BX1-01","p":6,"a":"p6","id":"lv4","src":"assets/audio/BX1-01/lv4.mp3","sec":8.544,"t":"一定区域内同种生物的所有个体是种群；所有生物是群落；再加上无机环境就是生态系统。"},{"ep":"bx1-01","n":"BX1-01","p":6,"a":"p6","id":"lv5","src":"assets/audio/BX1-01/lv5.mp3","sec":11.64,"t":"考法：判断实例属于哪个层次。解题方法：抓关键词——同种是种群，所有生物是群落；“池塘里所有的鱼”两者都不是。"},{"ep":"bx1-01","n":"BX1-01","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-01/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-01","n":"BX1-01","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-01/rv2.mp3","sec":9.264,"t":"判断一？错，细胞学说主要由施莱登和施旺建立。判断二？错，只揭示了统一性。"},{"ep":"bx1-01","n":"BX1-01","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-01/rv3.mp3","sec":6.744,"t":"判断三？对。判断四？错，他们用的是不完全归纳法。"},{"ep":"bx1-01","n":"BX1-01","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-01/rv4.mp3","sec":8.88,"t":"判断五？错，病毒必须寄生在活细胞中。判断六？对，植物没有系统层次。"},{"ep":"bx1-01","n":"BX1-01","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-01/rv5.mp3","sec":7.968,"t":"六个考点串成一条线：记准人名和年代，分清统一性与多样性。我们下期再见！"},{"ep":"bx1-02","n":"BX1-02","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-02/in1.mp3","sec":7.68,"t":"同学们好！这节课梳理人教版必修一第一章第二节——细胞的多样性和统一性。"},{"ep":"bx1-02","n":"BX1-02","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-02/in2.mp3","sec":7.44,"t":"高考常考高倍显微镜的使用和相关计算，以及原核细胞与真核细胞的比较。"},{"ep":"bx1-02","n":"BX1-02","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-02/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-02","n":"BX1-02","p":1,"a":"p1","id":"sc1","src":"assets/audio/BX1-02/sc1.mp3","sec":7.392,"t":"考点一，高倍显微镜的使用。第一步，先在低倍镜下找到要观察的物像。"},{"ep":"bx1-02","n":"BX1-02","p":1,"a":"p1","id":"sc2","src":"assets/audio/BX1-02/sc2.mp3","sec":6.912,"t":"第二步，把物像移到视野中央；第三步，转动转换器，换上高倍物镜。"},{"ep":"bx1-02","n":"BX1-02","p":1,"a":"p1","id":"sc3","src":"assets/audio/BX1-02/sc3.mp3","sec":7.992,"t":"第四步，视野变暗时调大光圈或换凹面镜，再转动细准焦螺旋，直到物像清晰。"},{"ep":"bx1-02","n":"BX1-02","p":1,"a":"p1","id":"sc4","src":"assets/audio/BX1-02/sc4.mp3","sec":7.248,"t":"易错：换高倍镜前不用升高镜筒，换高倍镜后不能再动粗准焦螺旋。"},{"ep":"bx1-02","n":"BX1-02","p":2,"a":"p2","id":"im1","src":"assets/audio/BX1-02/im1.mp3","sec":8.88,"t":"考点二，显微镜成像的特点。显微镜成的是放大的倒像，相当于把图像旋转180度。"},{"ep":"bx1-02","n":"BX1-02","p":2,"a":"p2","id":"im2","src":"assets/audio/BX1-02/im2.mp3","sec":8.736,"t":"所以物像在视野的左下方，实际物体在右上方；要把物像移到中央，装片要向左下方移动。"},{"ep":"bx1-02","n":"BX1-02","p":2,"a":"p2","id":"im3","src":"assets/audio/BX1-02/im3.mp3","sec":7.704,"t":"放大倍数等于目镜倍数乘物镜倍数，指的是物体长度或宽度的放大，不是面积。"},{"ep":"bx1-02","n":"BX1-02","p":2,"a":"p2","id":"im4","src":"assets/audio/BX1-02/im4.mp3","sec":7.728,"t":"解题方法：移装片记住“偏哪移哪”；判断实物形状时，把图像旋转180度。"},{"ep":"bx1-02","n":"BX1-02","p":3,"a":"p3","id":"ct1","src":"assets/audio/BX1-02/ct1.mp3","sec":6.936,"t":"考点三，放大倍数改变后视野中细胞数目的计算。分两种情况。"},{"ep":"bx1-02","n":"BX1-02","p":3,"a":"p3","id":"ct2","src":"assets/audio/BX1-02/ct2.mp3","sec":9.864,"t":"细胞排成一行：放大倍数变为原来的4倍，看到的细胞数变为原来的四分之一。比如8个变成2个。"},{"ep":"bx1-02","n":"BX1-02","p":3,"a":"p3","id":"ct3","src":"assets/audio/BX1-02/ct3.mp3","sec":10.8,"t":"细胞充满视野：长和宽都放大4倍，面积放大16倍，细胞数变为十六分之一。比如64个变成4个。"},{"ep":"bx1-02","n":"BX1-02","p":3,"a":"p3","id":"ct4","src":"assets/audio/BX1-02/ct4.mp3","sec":6.24,"t":"解题方法：放大n倍，一行的除以n，充满视野的除以n的平方。"},{"ep":"bx1-02","n":"BX1-02","p":4,"a":"p4","id":"pe1","src":"assets/audio/BX1-02/pe1.mp3","sec":8.664,"t":"考点四，原核细胞与真核细胞。两者最根本的区别：有无以核膜为界限的细胞核。"},{"ep":"bx1-02","n":"BX1-02","p":4,"a":"p4","id":"pe2","src":"assets/audio/BX1-02/pe2.mp3","sec":8.976,"t":"原核细胞没有成形的细胞核，DNA集中在拟核区域，是裸露的环状DNA，不形成染色体。"},{"ep":"bx1-02","n":"BX1-02","p":4,"a":"p4","id":"pe3","src":"assets/audio/BX1-02/pe3.mp3","sec":8.592,"t":"原核细胞只有核糖体一种细胞器；真核细胞有线粒体、叶绿体、内质网等多种细胞器。"},{"ep":"bx1-02","n":"BX1-02","p":4,"a":"p4","id":"pe4","src":"assets/audio/BX1-02/pe4.mp3","sec":9.288,"t":"易错：有无细胞壁不是区别——细菌也有细胞壁，但成分是肽聚糖，植物细胞壁是纤维素和果胶。"},{"ep":"bx1-02","n":"BX1-02","p":5,"a":"p5","id":"pk1","src":"assets/audio/BX1-02/pk1.mp3","sec":9.48,"t":"考点五，常见的原核生物。第一类是细菌：球菌、杆菌、螺旋菌，比如大肠杆菌、乳酸菌。"},{"ep":"bx1-02","n":"BX1-02","p":5,"a":"p5","id":"pk2","src":"assets/audio/BX1-02/pk2.mp3","sec":7.056,"t":"第二类是蓝细菌：色球蓝细菌、颤蓝细菌、念珠蓝细菌，还有发菜。"},{"ep":"bx1-02","n":"BX1-02","p":5,"a":"p5","id":"pk3","src":"assets/audio/BX1-02/pk3.mp3","sec":7.464,"t":"蓝细菌没有叶绿体，但含有藻蓝素和叶绿素，能进行光合作用，是自养生物。"},{"ep":"bx1-02","n":"BX1-02","p":5,"a":"p5","id":"pk4","src":"assets/audio/BX1-02/pk4.mp3","sec":7.152,"t":"还有支原体，它没有细胞壁，课本说它可能是最小、最简单的单细胞生物。"},{"ep":"bx1-02","n":"BX1-02","p":5,"a":"p5","id":"pk5","src":"assets/audio/BX1-02/pk5.mp3","sec":10.224,"t":"易错：能光合作用的不一定有叶绿体，蓝细菌就是例子；水体富营养化时的“水华”，就有蓝细菌大量繁殖。"},{"ep":"bx1-02","n":"BX1-02","p":6,"a":"p6","id":"un1","src":"assets/audio/BX1-02/un1.mp3","sec":6.816,"t":"考点六，原核细胞与真核细胞的统一性。它们都有细胞膜和细胞质。"},{"ep":"bx1-02","n":"BX1-02","p":6,"a":"p6","id":"un2","src":"assets/audio/BX1-02/un2.mp3","sec":4.464,"t":"都有核糖体这种细胞器，用来合成蛋白质。"},{"ep":"bx1-02","n":"BX1-02","p":6,"a":"p6","id":"un3","src":"assets/audio/BX1-02/un3.mp3","sec":7.992,"t":"遗传物质都是DNA。这体现了细胞的统一性，也说明生物之间存在亲缘关系。"},{"ep":"bx1-02","n":"BX1-02","p":6,"a":"p6","id":"un4","src":"assets/audio/BX1-02/un4.mp3","sec":10.296,"t":"考法：问原核细胞和真核细胞的共同点。解题方法：记住四个“都有”——膜、质、核糖体、DNA。"},{"ep":"bx1-02","n":"BX1-02","p":7,"a":"p7","id":"cf1","src":"assets/audio/BX1-02/cf1.mp3","sec":10.176,"t":"考点七，易混生物辨析。名字带“菌”的不一定是细菌：酵母菌、霉菌和蘑菇都是真菌，属于真核生物。"},{"ep":"bx1-02","n":"BX1-02","p":7,"a":"p7","id":"cf2","src":"assets/audio/BX1-02/cf2.mp3","sec":7.896,"t":"名字里带杆、球、弧、螺旋的菌，以及乳酸菌，才是细菌，属于原核生物。"},{"ep":"bx1-02","n":"BX1-02","p":7,"a":"p7","id":"cf3","src":"assets/audio/BX1-02/cf3.mp3","sec":7.608,"t":"衣藻、水绵、黑藻这些绿藻和植物是真核生物，而蓝细菌是原核生物。"},{"ep":"bx1-02","n":"BX1-02","p":7,"a":"p7","id":"cf4","src":"assets/audio/BX1-02/cf4.mp3","sec":5.4,"t":"病毒没有细胞结构，既不是原核生物，也不是真核生物。"},{"ep":"bx1-02","n":"BX1-02","p":7,"a":"p7","id":"cf5","src":"assets/audio/BX1-02/cf5.mp3","sec":8.904,"t":"解题方法：先排除病毒，再看有没有成形的细胞核；记住常见的几种真菌和蓝细菌就够用了。"},{"ep":"bx1-02","n":"BX1-02","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-02/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-02","n":"BX1-02","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-02/rv2.mp3","sec":9.552,"t":"判断一？错，应调光圈或反光镜，只能用细准焦螺旋。判断二？对，偏哪移哪。"},{"ep":"bx1-02","n":"BX1-02","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-02/rv3.mp3","sec":10.392,"t":"判断三？错，根本区别是有无以核膜为界限的细胞核。判断四？错，蓝细菌能光合作用。"},{"ep":"bx1-02","n":"BX1-02","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-02/rv4.mp3","sec":6.504,"t":"判断五？对。判断六？错，酵母菌是真核生物。"},{"ep":"bx1-02","n":"BX1-02","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-02/rv5.mp3","sec":6.576,"t":"七个考点串成一条线：先看有没有成形的细胞核。我们下期再见！"},{"ep":"bx1-03","n":"BX1-03","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-03/in1.mp3","sec":7.8,"t":"同学们好！这节课梳理人教版必修一第二章第一节——细胞中的元素和化合物。"},{"ep":"bx1-03","n":"BX1-03","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-03/in2.mp3","sec":7.08,"t":"高考常考元素的种类和含量，以及还原糖、脂肪和蛋白质的检测实验。"},{"ep":"bx1-03","n":"BX1-03","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-03/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-03","n":"BX1-03","p":1,"a":"p1","id":"un1","src":"assets/audio/BX1-03/un1.mp3","sec":9.744,"t":"考点一，生物界与非生物界的统一性和差异性。组成细胞的化学元素，在无机自然界中都能找到。"},{"ep":"bx1-03","n":"BX1-03","p":1,"a":"p1","id":"un2","src":"assets/audio/BX1-03/un2.mp3","sec":6.456,"t":"没有一种元素是细胞所特有的，这体现了生物界与非生物界的统一性。"},{"ep":"bx1-03","n":"BX1-03","p":1,"a":"p1","id":"un3","src":"assets/audio/BX1-03/un3.mp3","sec":7.032,"t":"但细胞中各种元素的相对含量与无机自然界大不相同，这体现了差异性。"},{"ep":"bx1-03","n":"BX1-03","p":1,"a":"p1","id":"un4","src":"assets/audio/BX1-03/un4.mp3","sec":5.784,"t":"解题方法：看元素种类说统一性，看元素含量说差异性。"},{"ep":"bx1-03","n":"BX1-03","p":2,"a":"p2","id":"ma1","src":"assets/audio/BX1-03/ma1.mp3","sec":9.504,"t":"考点二，大量元素和微量元素。大量元素有C、H、O、N、P、S、K、Ca、Mg。"},{"ep":"bx1-03","n":"BX1-03","p":2,"a":"p2","id":"ma2","src":"assets/audio/BX1-03/ma2.mp3","sec":7.248,"t":"微量元素有Fe、Mn、Zn、Cu、B、Mo，含量很少，但同样必不可少。"},{"ep":"bx1-03","n":"BX1-03","p":2,"a":"p2","id":"ma3","src":"assets/audio/BX1-03/ma3.mp3","sec":7.224,"t":"微量元素可以用口诀记：“铁猛碰新木桶”——铁、锰、硼、锌、钼、铜。"},{"ep":"bx1-03","n":"BX1-03","p":2,"a":"p2","id":"ma4","src":"assets/audio/BX1-03/ma4.mp3","sec":9.816,"t":"易错：大量、微量是按含量分的，不是按作用大小；Mg、Ca是大量元素，常被混进微量元素里。"},{"ep":"bx1-03","n":"BX1-03","p":3,"a":"p3","id":"cb1","src":"assets/audio/BX1-03/cb1.mp3","sec":9.024,"t":"考点三，碳是核心元素。生物大分子以碳链为基本骨架，所以说碳是生命的核心元素。"},{"ep":"bx1-03","n":"BX1-03","p":3,"a":"p3","id":"cb2","src":"assets/audio/BX1-03/cb2.mp3","sec":5.568,"t":"细胞鲜重中，含量最多的元素是O，因为细胞里水最多。"},{"ep":"bx1-03","n":"BX1-03","p":3,"a":"p3","id":"cb3","src":"assets/audio/BX1-03/cb3.mp3","sec":8.208,"t":"人体细胞干重中，含量最多的元素是C；不过课本表里玉米细胞干重中O略多于C。"},{"ep":"bx1-03","n":"BX1-03","p":3,"a":"p3","id":"cb4","src":"assets/audio/BX1-03/cb4.mp3","sec":8.136,"t":"鲜重中从多到少是O、C、H、N；人体细胞干重中是C、O、N、H。"},{"ep":"bx1-03","n":"BX1-03","p":3,"a":"p3","id":"cb5","src":"assets/audio/BX1-03/cb5.mp3","sec":10.128,"t":"考法：给柱形图判断是鲜重还是干重。解题方法：O远多于C是鲜重；C排第一，一般是干重。"},{"ep":"bx1-03","n":"BX1-03","p":4,"a":"p4","id":"cp1","src":"assets/audio/BX1-03/cp1.mp3","sec":10.896,"t":"考点四，细胞中的化合物。分为无机化合物——水和无机盐，和有机化合物——糖类、脂质、蛋白质和核酸。"},{"ep":"bx1-03","n":"BX1-03","p":4,"a":"p4","id":"cp2","src":"assets/audio/BX1-03/cp2.mp3","sec":3.504,"t":"细胞中含量最多的化合物是水。"},{"ep":"bx1-03","n":"BX1-03","p":4,"a":"p4","id":"cp3","src":"assets/audio/BX1-03/cp3.mp3","sec":7.392,"t":"含量最多的有机化合物是蛋白质；占细胞干重最多的化合物，也是蛋白质。"},{"ep":"bx1-03","n":"BX1-03","p":4,"a":"p4","id":"cp4","src":"assets/audio/BX1-03/cp4.mp3","sec":8.328,"t":"易错：问“化合物”答水，问“有机物”答蛋白质；问“元素”，还要先分清鲜重还是干重。"},{"ep":"bx1-03","n":"BX1-03","p":5,"a":"p5","id":"su1","src":"assets/audio/BX1-03/su1.mp3","sec":10.176,"t":"考点五，检测还原糖。葡萄糖、果糖、麦芽糖等还原糖，与斐林试剂发生作用，生成砖红色沉淀。"},{"ep":"bx1-03","n":"BX1-03","p":5,"a":"p5","id":"su2","src":"assets/audio/BX1-03/su2.mp3","sec":7.608,"t":"斐林试剂由甲液NaOH和乙液CuSO4等量混匀而成，要现配现用。"},{"ep":"bx1-03","n":"BX1-03","p":5,"a":"p5","id":"su3","src":"assets/audio/BX1-03/su3.mp3","sec":6.984,"t":"加入后要50～65℃水浴加热约2分钟，才会出现砖红色沉淀。"},{"ep":"bx1-03","n":"BX1-03","p":5,"a":"p5","id":"su4","src":"assets/audio/BX1-03/su4.mp3","sec":10.8,"t":"材料要选含还原糖多、颜色浅的，如苹果、梨；甘蔗、甜菜主要含蔗糖，西瓜汁颜色太深，都不合适。"},{"ep":"bx1-03","n":"BX1-03","p":5,"a":"p5","id":"su5","src":"assets/audio/BX1-03/su5.mp3","sec":6.864,"t":"易错：蔗糖和淀粉不是还原糖；不水浴加热就看不到砖红色沉淀。"},{"ep":"bx1-03","n":"BX1-03","p":6,"a":"p6","id":"ft1","src":"assets/audio/BX1-03/ft1.mp3","sec":6.048,"t":"考点六，检测脂肪。脂肪被苏丹Ⅲ染液染成橘黄色。"},{"ep":"bx1-03","n":"BX1-03","p":6,"a":"p6","id":"ft2","src":"assets/audio/BX1-03/ft2.mp3","sec":6.192,"t":"材料用花生种子的子叶，切成薄片，染色后制成临时装片。"},{"ep":"bx1-03","n":"BX1-03","p":6,"a":"p6","id":"ft3","src":"assets/audio/BX1-03/ft3.mp3","sec":5.04,"t":"染色后用体积分数为50%的酒精洗去浮色。"},{"ep":"bx1-03","n":"BX1-03","p":6,"a":"p6","id":"ft4","src":"assets/audio/BX1-03/ft4.mp3","sec":5.064,"t":"在显微镜下，可以看到被染成橘黄色的脂肪颗粒。"},{"ep":"bx1-03","n":"BX1-03","p":6,"a":"p6","id":"ft5","src":"assets/audio/BX1-03/ft5.mp3","sec":9.432,"t":"易错：这里酒精的作用是洗去浮色；观察切片中的脂肪颗粒才要用显微镜，检测组织样液不用。"},{"ep":"bx1-03","n":"BX1-03","p":7,"a":"p7","id":"pr1","src":"assets/audio/BX1-03/pr1.mp3","sec":7.632,"t":"考点七，检测蛋白质。蛋白质与双缩脲试剂发生作用，产生紫色反应。"},{"ep":"bx1-03","n":"BX1-03","p":7,"a":"p7","id":"pr2","src":"assets/audio/BX1-03/pr2.mp3","sec":8.304,"t":"使用时先加A液NaOH 1 mL，摇匀；再加B液CuSO4 4滴，摇匀。"},{"ep":"bx1-03","n":"BX1-03","p":7,"a":"p7","id":"pr3","src":"assets/audio/BX1-03/pr3.mp3","sec":6.984,"t":"双缩脲试剂不需要加热，和斐林试剂的“等量混匀、水浴加热”正好不同。"},{"ep":"bx1-03","n":"BX1-03","p":7,"a":"p7","id":"pr4","src":"assets/audio/BX1-03/pr4.mp3","sec":10.08,"t":"两者CuSO4的浓度也不同：斐林试剂乙液是0.05 g/mL，双缩脲试剂B液是0.01 g/mL。"},{"ep":"bx1-03","n":"BX1-03","p":7,"a":"p7","id":"pr5","src":"assets/audio/BX1-03/pr5.mp3","sec":6.744,"t":"解题方法：斐林试剂“混合、加热”，双缩脲试剂“分开加、不加热”。"},{"ep":"bx1-03","n":"BX1-03","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-03/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-03","n":"BX1-03","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-03/rv2.mp3","sec":8.736,"t":"判断一？错，没有一种元素是细胞特有的。判断二？错，Mg是大量元素。"},{"ep":"bx1-03","n":"BX1-03","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-03/rv3.mp3","sec":6.192,"t":"判断三？错，鲜重中O最多。判断四？对。"},{"ep":"bx1-03","n":"BX1-03","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-03/rv4.mp3","sec":8.664,"t":"判断五？错，蔗糖不是还原糖。判断六？错，要先加A液，再加B液。"},{"ep":"bx1-03","n":"BX1-03","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-03/rv5.mp3","sec":9.096,"t":"七个考点串成一条线：元素看种类和含量，检测记准试剂、条件和颜色。我们下期再见！"},{"ep":"bx1-04","n":"BX1-04","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-04/in1.mp3","sec":7.056,"t":"同学们好！这节课梳理人教版必修一第二章第二节——细胞中的无机物。"},{"ep":"bx1-04","n":"BX1-04","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-04/in2.mp3","sec":7.224,"t":"高考常考自由水与结合水、无机盐的功能，以及验证必需元素的实验设计。"},{"ep":"bx1-04","n":"BX1-04","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-04/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-04","n":"BX1-04","p":1,"a":"p1","id":"wc1","src":"assets/audio/BX1-04/wc1.mp3","sec":10.056,"t":"考点一，水的含量特点。水是细胞中含量最多的化合物，一般占细胞鲜重的70%～90%。"},{"ep":"bx1-04","n":"BX1-04","p":1,"a":"p1","id":"wc2","src":"assets/audio/BX1-04/wc2.mp3","sec":8.376,"t":"不同生物含水量不同：一般水生生物多于陆生生物，水母的含水量可达97%。"},{"ep":"bx1-04","n":"BX1-04","p":1,"a":"p1","id":"wc3","src":"assets/audio/BX1-04/wc3.mp3","sec":7.992,"t":"同一生物的不同时期、不同器官也不同：幼儿多于成年人，代谢旺盛的器官含水量高。"},{"ep":"bx1-04","n":"BX1-04","p":1,"a":"p1","id":"wc4","src":"assets/audio/BX1-04/wc4.mp3","sec":9.312,"t":"考法：比较不同生物、不同器官含水量的高低。解题方法：一般代谢越旺盛，含水量越高。"},{"ep":"bx1-04","n":"BX1-04","p":2,"a":"p2","id":"sv1","src":"assets/audio/BX1-04/sv1.mp3","sec":9.744,"t":"考点二，水为什么是良好的溶剂。水分子是极性分子，带电荷的分子或离子都容易与水结合。"},{"ep":"bx1-04","n":"BX1-04","p":2,"a":"p2","id":"sv2","src":"assets/audio/BX1-04/sv2.mp3","sec":9.672,"t":"水分子之间会形成氢键，氢键不断断裂又不断形成，使水在常温下呈液体状态，具有流动性。"},{"ep":"bx1-04","n":"BX1-04","p":2,"a":"p2","id":"sv3","src":"assets/audio/BX1-04/sv3.mp3","sec":7.752,"t":"氢键还使水具有较高的比热容，水的温度不容易改变，有利于维持生命系统的稳定。"},{"ep":"bx1-04","n":"BX1-04","p":2,"a":"p2","id":"sv4","src":"assets/audio/BX1-04/sv4.mp3","sec":8.856,"t":"易错：水是良好溶剂，靠的是极性；水的比热容高、能流动，靠的是氢键，不要张冠李戴。"},{"ep":"bx1-04","n":"BX1-04","p":3,"a":"p3","id":"fw1","src":"assets/audio/BX1-04/fw1.mp3","sec":9.552,"t":"考点三，自由水与结合水。细胞中绝大部分的水以游离的形式存在，可以自由流动，叫作自由水。"},{"ep":"bx1-04","n":"BX1-04","p":3,"a":"p3","id":"fw2","src":"assets/audio/BX1-04/fw2.mp3","sec":8.352,"t":"自由水是细胞内良好的溶剂，参与许多生物化学反应，还能运送营养物质和代谢废物。"},{"ep":"bx1-04","n":"BX1-04","p":3,"a":"p3","id":"fw3","src":"assets/audio/BX1-04/fw3.mp3","sec":7.848,"t":"一部分水与细胞内的其他物质相结合，叫作结合水，是细胞结构的重要组成部分。"},{"ep":"bx1-04","n":"BX1-04","p":3,"a":"p3","id":"fw4","src":"assets/audio/BX1-04/fw4.mp3","sec":4.92,"t":"在一定条件下，自由水和结合水可以相互转化。"},{"ep":"bx1-04","n":"BX1-04","p":3,"a":"p3","id":"fw5","src":"assets/audio/BX1-04/fw5.mp3","sec":10.128,"t":"易错：只有自由水能作溶剂、参与反应和运输；结合水失去了流动性和溶解性，是细胞结构的组成成分。"},{"ep":"bx1-04","n":"BX1-04","p":4,"a":"p4","id":"rt1","src":"assets/audio/BX1-04/rt1.mp3","sec":6.96,"t":"考点四，自由水与结合水的比值。比值越高，细胞代谢越旺盛。"},{"ep":"bx1-04","n":"BX1-04","p":4,"a":"p4","id":"rt2","src":"assets/audio/BX1-04/rt2.mp3","sec":5.64,"t":"比值越低，代谢越慢，但抗寒、抗旱等抗逆性越强。"},{"ep":"bx1-04","n":"BX1-04","p":4,"a":"p4","id":"rt3","src":"assets/audio/BX1-04/rt3.mp3","sec":7.08,"t":"比如冬季来临，冬小麦细胞中结合水的比例逐渐升高，抗寒能力增强。"},{"ep":"bx1-04","n":"BX1-04","p":4,"a":"p4","id":"rt4","src":"assets/audio/BX1-04/rt4.mp3","sec":9.912,"t":"种子晒干时失去的主要是自由水，代谢减弱，便于储存；种子烘烤时失去结合水，就失去活性了。"},{"ep":"bx1-04","n":"BX1-04","p":4,"a":"p4","id":"rt5","src":"assets/audio/BX1-04/rt5.mp3","sec":10.824,"t":"考法：结合种子萌发、储存和越冬考比值的变化。解题方法：代谢旺盛看自由水，抗逆性强看结合水。"},{"ep":"bx1-04","n":"BX1-04","p":5,"a":"p5","id":"sa1","src":"assets/audio/BX1-04/sa1.mp3","sec":7.776,"t":"考点五，无机盐的存在形式和功能。细胞中大多数无机盐以离子的形式存在。"},{"ep":"bx1-04","n":"BX1-04","p":5,"a":"p5","id":"sa2","src":"assets/audio/BX1-04/sa2.mp3","sec":9.096,"t":"有些无机盐是复杂化合物的重要组成成分：Mg是叶绿素的组成成分，Fe是血红素的组成成分。"},{"ep":"bx1-04","n":"BX1-04","p":5,"a":"p5","id":"sa3","src":"assets/audio/BX1-04/sa3.mp3","sec":7.08,"t":"I是合成甲状腺激素的原料；P是磷脂、核酸、ATP等的组成元素。"},{"ep":"bx1-04","n":"BX1-04","p":5,"a":"p5","id":"sa4","src":"assets/audio/BX1-04/sa4.mp3","sec":12.312,"t":"考法：缺Mg叶片发黄，缺Fe会贫血，缺I易患地方性甲状腺肿。解题方法：先说它组成了哪种化合物，再推缺乏的后果。"},{"ep":"bx1-04","n":"BX1-04","p":6,"a":"p6","id":"sb1","src":"assets/audio/BX1-04/sb1.mp3","sec":9.648,"t":"考点六，无机盐对维持生命活动的作用。哺乳动物血液中Ca2+含量太低，会出现抽搐等症状。"},{"ep":"bx1-04","n":"BX1-04","p":6,"a":"p6","id":"sb2","src":"assets/audio/BX1-04/sb2.mp3","sec":8.568,"t":"人体内Na+缺乏，会引起神经、肌肉细胞的兴奋性降低，最终引发肌肉酸痛、无力等。"},{"ep":"bx1-04","n":"BX1-04","p":6,"a":"p6","id":"sb3","src":"assets/audio/BX1-04/sb3.mp3","sec":9.72,"t":"无机盐还能维持细胞的酸碱平衡和渗透压，比如生理盐水是质量分数为0.9%的NaCl溶液。"},{"ep":"bx1-04","n":"BX1-04","p":6,"a":"p6","id":"sb4","src":"assets/audio/BX1-04/sb4.mp3","sec":8.232,"t":"易错：无机盐不能为细胞提供能量；大量出汗后，要补充的是淡盐水，而不只是水。"},{"ep":"bx1-04","n":"BX1-04","p":7,"a":"p7","id":"ds1","src":"assets/audio/BX1-04/ds1.mp3","sec":10.824,"t":"考点七，验证某种无机盐是植物生长所必需的。以镁为例：完全培养液为对照组，缺镁培养液为实验组。"},{"ep":"bx1-04","n":"BX1-04","p":7,"a":"p7","id":"ds2","src":"assets/audio/BX1-04/ds2.mp3","sec":6.984,"t":"把长势相同的幼苗分别放入两组中培养，结果缺镁组的幼苗叶片发黄。"},{"ep":"bx1-04","n":"BX1-04","p":7,"a":"p7","id":"ds3","src":"assets/audio/BX1-04/ds3.mp3","sec":8.424,"t":"还要做二次对照：向缺镁组中补充镁，症状消失、恢复正常，才能说明镁是必需的。"},{"ep":"bx1-04","n":"BX1-04","p":7,"a":"p7","id":"ds4","src":"assets/audio/BX1-04/ds4.mp3","sec":10.728,"t":"解题方法：自变量是有无这种无机盐；对照组用完全培养液，不能用土壤；再用“缺素—补素”前后对照增强说服力。"},{"ep":"bx1-04","n":"BX1-04","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-04/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-04","n":"BX1-04","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-04/rv2.mp3","sec":10.56,"t":"判断一？错，自由水才是良好溶剂。判断二？错，比值越高，代谢越旺盛，抗逆性越弱。"},{"ep":"bx1-04","n":"BX1-04","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-04/rv3.mp3","sec":4.656,"t":"判断三？对。判断四？对。"},{"ep":"bx1-04","n":"BX1-04","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-04/rv4.mp3","sec":8.856,"t":"判断五？错，无机盐不能提供能量。判断六？错，对照组要用完全培养液。"},{"ep":"bx1-04","n":"BX1-04","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-04/rv5.mp3","sec":9.408,"t":"七个考点串成一条线：代谢看自由水，抗逆看结合水，无机盐看组成和功能。我们下期再见！"},{"ep":"bx1-05","n":"BX1-05","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-05/in1.mp3","sec":7.728,"t":"同学们好！这节课梳理人教版必修一第二章第三节——细胞中的糖类和脂质。"},{"ep":"bx1-05","n":"BX1-05","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-05/in2.mp3","sec":5.904,"t":"高考常考糖类的种类、分布和功能，以及脂肪与糖类的比较。"},{"ep":"bx1-05","n":"BX1-05","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-05/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-05","n":"BX1-05","p":1,"a":"p1","id":"sg1","src":"assets/audio/BX1-05/sg1.mp3","sec":7.752,"t":"考点一，糖类的元素组成与功能。糖类一般由C、H、O三种元素构成。"},{"ep":"bx1-05","n":"BX1-05","p":1,"a":"p1","id":"sg2","src":"assets/audio/BX1-05/sg2.mp3","sec":9.792,"t":"糖类是细胞的重要能源物质，其中葡萄糖是细胞生命活动所需要的主要能源物质，常被称为“生命的燃料”。"},{"ep":"bx1-05","n":"BX1-05","p":1,"a":"p1","id":"sg3","src":"assets/audio/BX1-05/sg3.mp3","sec":6.216,"t":"糖类还能构成细胞结构，比如纤维素是植物细胞壁的主要成分。"},{"ep":"bx1-05","n":"BX1-05","p":1,"a":"p1","id":"sg4","src":"assets/audio/BX1-05/sg4.mp3","sec":9.552,"t":"易错：糖类不都是能源物质——纤维素、核糖、脱氧核糖都不为细胞供能；几丁质还含有N。"},{"ep":"bx1-05","n":"BX1-05","p":2,"a":"p2","id":"mo1","src":"assets/audio/BX1-05/mo1.mp3","sec":6.408,"t":"考点二，单糖。单糖是不能水解的糖，可以被细胞直接吸收。"},{"ep":"bx1-05","n":"BX1-05","p":2,"a":"p2","id":"mo2","src":"assets/audio/BX1-05/mo2.mp3","sec":6.504,"t":"六碳糖有葡萄糖、果糖、半乳糖；五碳糖有核糖和脱氧核糖。"},{"ep":"bx1-05","n":"BX1-05","p":2,"a":"p2","id":"mo3","src":"assets/audio/BX1-05/mo3.mp3","sec":8.904,"t":"核糖是RNA的组成成分，脱氧核糖是DNA的组成成分；葡萄糖是动植物细胞共有的单糖。"},{"ep":"bx1-05","n":"BX1-05","p":2,"a":"p2","id":"mo4","src":"assets/audio/BX1-05/mo4.mp3","sec":8.64,"t":"考法：判断动植物细胞共有的糖。解题方法：共有的是葡萄糖、核糖、脱氧核糖。"},{"ep":"bx1-05","n":"BX1-05","p":3,"a":"p3","id":"di1","src":"assets/audio/BX1-05/di1.mp3","sec":8.64,"t":"考点三，二糖。二糖由两分子单糖脱水缩合而成，必须水解成单糖才能被吸收。"},{"ep":"bx1-05","n":"BX1-05","p":3,"a":"p3","id":"di2","src":"assets/audio/BX1-05/di2.mp3","sec":8.904,"t":"植物细胞中的二糖：蔗糖水解成一分子葡萄糖和一分子果糖；麦芽糖水解成两分子葡萄糖。"},{"ep":"bx1-05","n":"BX1-05","p":3,"a":"p3","id":"di3","src":"assets/audio/BX1-05/di3.mp3","sec":9.12,"t":"动物细胞中的二糖：乳糖，水解成一分子葡萄糖和一分子半乳糖，人和动物乳汁中含量丰富。"},{"ep":"bx1-05","n":"BX1-05","p":3,"a":"p3","id":"di4","src":"assets/audio/BX1-05/di4.mp3","sec":8.4,"t":"易错：蔗糖不是还原糖，麦芽糖和乳糖是还原糖；二糖的水解产物都含有葡萄糖。"},{"ep":"bx1-05","n":"BX1-05","p":4,"a":"p4","id":"po1","src":"assets/audio/BX1-05/po1.mp3","sec":10.848,"t":"考点四，多糖。淀粉是植物细胞中的储能物质，糖原是人和动物细胞中的储能物质，主要分布在肝脏和肌肉中。"},{"ep":"bx1-05","n":"BX1-05","p":4,"a":"p4","id":"po2","src":"assets/audio/BX1-05/po2.mp3","sec":10.32,"t":"纤维素是植物细胞壁的主要成分，很难被人体消化；一些科学家把纤维素等其他糖类称为人类的“第七类营养素”。"},{"ep":"bx1-05","n":"BX1-05","p":4,"a":"p4","id":"po3","src":"assets/audio/BX1-05/po3.mp3","sec":8.304,"t":"淀粉、糖原、纤维素的基本单位都是葡萄糖，但葡萄糖的连接方式不同，所以性质不同。"},{"ep":"bx1-05","n":"BX1-05","p":4,"a":"p4","id":"po4","src":"assets/audio/BX1-05/po4.mp3","sec":8.712,"t":"几丁质广泛存在于甲壳类动物和昆虫的外骨骼中，能与重金属离子结合，可用于废水处理。"},{"ep":"bx1-05","n":"BX1-05","p":4,"a":"p4","id":"po5","src":"assets/audio/BX1-05/po5.mp3","sec":8.856,"t":"易错：肝糖原能分解补充血糖，肌糖原不能直接分解成葡萄糖；纤维素不是储能物质。"},{"ep":"bx1-05","n":"BX1-05","p":5,"a":"p5","id":"lp1","src":"assets/audio/BX1-05/lp1.mp3","sec":11.376,"t":"考点五，脂质的种类与功能。脂质主要含C、H、O，有的还含有N和P；通常不溶于水，而溶于脂溶性有机溶剂。"},{"ep":"bx1-05","n":"BX1-05","p":5,"a":"p5","id":"lp2","src":"assets/audio/BX1-05/lp2.mp3","sec":6.168,"t":"脂肪是细胞内良好的储能物质，还有保温、缓冲和减压的作用。"},{"ep":"bx1-05","n":"BX1-05","p":5,"a":"p5","id":"lp3","src":"assets/audio/BX1-05/lp3.mp3","sec":4.896,"t":"磷脂是构成细胞膜和多种细胞器膜的重要成分。"},{"ep":"bx1-05","n":"BX1-05","p":5,"a":"p5","id":"lp4","src":"assets/audio/BX1-05/lp4.mp3","sec":11.856,"t":"固醇包括胆固醇、性激素和维生素D：胆固醇构成动物细胞膜，还参与血液中脂质的运输；维生素D促进钙和磷的吸收。"},{"ep":"bx1-05","n":"BX1-05","p":5,"a":"p5","id":"lp5","src":"assets/audio/BX1-05/lp5.mp3","sec":8.208,"t":"易错：性激素是固醇，不是蛋白质；所有细胞都含磷脂，因为所有细胞都有细胞膜。"},{"ep":"bx1-05","n":"BX1-05","p":6,"a":"p6","id":"fa1","src":"assets/audio/BX1-05/fa1.mp3","sec":9.456,"t":"考点六，脂肪的组成。脂肪是由三分子脂肪酸与一分子甘油发生反应形成的酯，叫三酰甘油。"},{"ep":"bx1-05","n":"BX1-05","p":6,"a":"p6","id":"fa2","src":"assets/audio/BX1-05/fa2.mp3","sec":6.216,"t":"植物脂肪大多含不饱和脂肪酸，熔点较低，室温时呈液态。"},{"ep":"bx1-05","n":"BX1-05","p":6,"a":"p6","id":"fa3","src":"assets/audio/BX1-05/fa3.mp3","sec":6.12,"t":"大多数动物脂肪含饱和脂肪酸，熔点较高，室温时呈固态。"},{"ep":"bx1-05","n":"BX1-05","p":6,"a":"p6","id":"fa4","src":"assets/audio/BX1-05/fa4.mp3","sec":7.008,"t":"易错：脂肪只含C、H、O，不含N、P；含N、P的是磷脂。"},{"ep":"bx1-05","n":"BX1-05","p":7,"a":"p7","id":"cm1","src":"assets/audio/BX1-05/cm1.mp3","sec":9.648,"t":"考点七，糖类与脂肪的比较。两者都由C、H、O组成，但脂肪中H的含量高，O的含量低。"},{"ep":"bx1-05","n":"BX1-05","p":7,"a":"p7","id":"cm2","src":"assets/audio/BX1-05/cm2.mp3","sec":7.752,"t":"所以等质量的脂肪氧化分解时，消耗的氧气多，释放的能量多，产生的水也多。"},{"ep":"bx1-05","n":"BX1-05","p":7,"a":"p7","id":"cm3","src":"assets/audio/BX1-05/cm3.mp3","sec":5.976,"t":"因此，脂肪是良好的储能物质；而糖类是主要的能源物质。"},{"ep":"bx1-05","n":"BX1-05","p":7,"a":"p7","id":"cm4","src":"assets/audio/BX1-05/cm4.mp3","sec":10.344,"t":"考法：油料种子萌发时耗氧多，或比较呼吸熵。解题方法：抓住“脂肪含H多、含O少”这一条往下推。"},{"ep":"bx1-05","n":"BX1-05","p":8,"a":"p8","id":"cv1","src":"assets/audio/BX1-05/cv1.mp3","sec":10.344,"t":"考点八，糖类和脂质的相互转化。血液中的葡萄糖除供细胞利用外，多余的部分可以合成糖原储存起来。"},{"ep":"bx1-05","n":"BX1-05","p":8,"a":"p8","id":"cv2","src":"assets/audio/BX1-05/cv2.mp3","sec":9.312,"t":"如果葡萄糖还有富余，就可以转变成脂肪和某些氨基酸；糖类供应充足时，可以大量转化为脂肪。"},{"ep":"bx1-05","n":"BX1-05","p":8,"a":"p8","id":"cv3","src":"assets/audio/BX1-05/cv3.mp3","sec":7.584,"t":"而脂肪一般只在糖类供能不足时，才会分解供能，而且不能大量转化为糖类。"},{"ep":"bx1-05","n":"BX1-05","p":8,"a":"p8","id":"cv4","src":"assets/audio/BX1-05/cv4.mp3","sec":10.68,"t":"考法：解释“吃糖多也会发胖”。解题方法：记住转化是不对称的——糖能大量变脂肪，脂肪不能大量变糖。"},{"ep":"bx1-05","n":"BX1-05","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-05/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-05","n":"BX1-05","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-05/rv2.mp3","sec":9.456,"t":"判断一？错，纤维素、核糖等不供能。判断二？错，蔗糖水解为葡萄糖和果糖。"},{"ep":"bx1-05","n":"BX1-05","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-05/rv3.mp3","sec":4.656,"t":"判断三？对。判断四？对。"},{"ep":"bx1-05","n":"BX1-05","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-05/rv4.mp3","sec":9.096,"t":"判断五？错，脂肪释放能量更多。判断六？错，脂肪不能大量转化为糖类。"},{"ep":"bx1-05","n":"BX1-05","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-05/rv5.mp3","sec":6.528,"t":"八个考点串成一条线：分清种类、分布和功能。我们下期再见！"},{"ep":"bx1-06","n":"BX1-06","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-06/in1.mp3","sec":8.544,"t":"同学们好！这节课梳理人教版必修一第二章第四节——蛋白质是生命活动的主要承担者。"},{"ep":"bx1-06","n":"BX1-06","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-06/in2.mp3","sec":7.104,"t":"高考常考氨基酸的结构通式、脱水缩合的相关计算，以及蛋白质的变性。"},{"ep":"bx1-06","n":"BX1-06","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-06/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-06","n":"BX1-06","p":1,"a":"p1","id":"fn1","src":"assets/audio/BX1-06/fn1.mp3","sec":9.048,"t":"考点一，蛋白质的功能。一切生命活动都离不开蛋白质，蛋白质是生命活动的主要承担者。"},{"ep":"bx1-06","n":"BX1-06","p":1,"a":"p1","id":"fn2","src":"assets/audio/BX1-06/fn2.mp3","sec":8.688,"t":"结构蛋白：构成细胞和生物体，如羽毛、肌肉、头发；催化：绝大多数酶是蛋白质。"},{"ep":"bx1-06","n":"BX1-06","p":1,"a":"p1","id":"fn3","src":"assets/audio/BX1-06/fn3.mp3","sec":7.128,"t":"运输：血红蛋白运输氧气；信息传递和调节：如胰岛素调节血糖。"},{"ep":"bx1-06","n":"BX1-06","p":1,"a":"p1","id":"fn4","src":"assets/audio/BX1-06/fn4.mp3","sec":5.832,"t":"免疫：抗体可以帮助人体抵御病菌和病毒等抗原的侵害。"},{"ep":"bx1-06","n":"BX1-06","p":1,"a":"p1","id":"fn5","src":"assets/audio/BX1-06/fn5.mp3","sec":7.896,"t":"易错：激素不都是蛋白质，性激素是固醇；酶也不都是蛋白质，少数是RNA。"},{"ep":"bx1-06","n":"BX1-06","p":2,"a":"p2","id":"aa1","src":"assets/audio/BX1-06/aa1.mp3","sec":7.296,"t":"考点二，氨基酸的结构。每种氨基酸分子至少都含有一个氨基和一个羧基。"},{"ep":"bx1-06","n":"BX1-06","p":2,"a":"p2","id":"aa2","src":"assets/audio/BX1-06/aa2.mp3","sec":10.056,"t":"并且都有一个氨基和一个羧基连接在同一个碳原子上，这个碳原子还连着一个氢原子和一个侧链基团，叫R基。"},{"ep":"bx1-06","n":"BX1-06","p":2,"a":"p2","id":"aa3","src":"assets/audio/BX1-06/aa3.mp3","sec":4.2,"t":"各种氨基酸之间的区别，在于R基的不同。"},{"ep":"bx1-06","n":"BX1-06","p":2,"a":"p2","id":"aa4","src":"assets/audio/BX1-06/aa4.mp3","sec":8.4,"t":"解题方法：判断是不是组成蛋白质的氨基酸，看同一个碳上，是否既有氨基又有羧基。"},{"ep":"bx1-06","n":"BX1-06","p":3,"a":"p3","id":"kd1","src":"assets/audio/BX1-06/kd1.mp3","sec":4.872,"t":"考点三，组成人体蛋白质的氨基酸有21种。"},{"ep":"bx1-06","n":"BX1-06","p":3,"a":"p3","id":"kd2","src":"assets/audio/BX1-06/kd2.mp3","sec":7.296,"t":"其中8种是人体细胞不能合成的，必须从外界环境中获取，叫必需氨基酸。"},{"ep":"bx1-06","n":"BX1-06","p":3,"a":"p3","id":"kd3","src":"assets/audio/BX1-06/kd3.mp3","sec":4.896,"t":"另外13种人体细胞能够合成，叫非必需氨基酸。"},{"ep":"bx1-06","n":"BX1-06","p":3,"a":"p3","id":"kd4","src":"assets/audio/BX1-06/kd4.mp3","sec":12.48,"t":"必需氨基酸可以用口诀记：“甲携来一本亮色书”——甲硫氨酸、缬氨酸、赖氨酸、异亮氨酸、苯丙氨酸、亮氨酸、色氨酸、苏氨酸。"},{"ep":"bx1-06","n":"BX1-06","p":3,"a":"p3","id":"kd5","src":"assets/audio/BX1-06/kd5.mp3","sec":10.656,"t":"考法：评价食物的营养价值。解题方法：看必需氨基酸的种类和含量，比如玉米等谷类蛋白质缺少赖氨酸。"},{"ep":"bx1-06","n":"BX1-06","p":4,"a":"p4","id":"dh1","src":"assets/audio/BX1-06/dh1.mp3","sec":9.048,"t":"考点四，脱水缩合。一个氨基酸的羧基和另一个氨基酸的氨基相连接，同时脱去一分子水。"},{"ep":"bx1-06","n":"BX1-06","p":4,"a":"p4","id":"dh2","src":"assets/audio/BX1-06/dh2.mp3","sec":10.728,"t":"连接两个氨基酸的化学键叫肽键。两个氨基酸形成二肽，多个氨基酸形成多肽，多肽通常呈链状，叫肽链。"},{"ep":"bx1-06","n":"BX1-06","p":4,"a":"p4","id":"dh3","src":"assets/audio/BX1-06/dh3.mp3","sec":8.448,"t":"易错：脱去的水中，H来自氨基和羧基，O来自羧基；脱水缩合的场所是核糖体。"},{"ep":"bx1-06","n":"BX1-06","p":5,"a":"p5","id":"ca1","src":"assets/audio/BX1-06/ca1.mp3","sec":11.232,"t":"考点五，肽键数和相对分子质量的计算。n个氨基酸形成m条肽链：肽键数 = 脱去的水分子数 = n − m。"},{"ep":"bx1-06","n":"BX1-06","p":5,"a":"p5","id":"ca2","src":"assets/audio/BX1-06/ca2.mp3","sec":4.896,"t":"如果形成的是环状肽，肽键数就等于氨基酸数n。"},{"ep":"bx1-06","n":"BX1-06","p":5,"a":"p5","id":"ca3","src":"assets/audio/BX1-06/ca3.mp3","sec":8.784,"t":"蛋白质的相对分子质量 = 氨基酸数 × 平均相对分子质量 − 脱去水分子数 × 18。"},{"ep":"bx1-06","n":"BX1-06","p":5,"a":"p5","id":"ca4","src":"assets/audio/BX1-06/ca4.mp3","sec":11.496,"t":"例：100个氨基酸形成2条肽链，平均相对分子质量是128，那么蛋白质的相对分子质量是11036。"},{"ep":"bx1-06","n":"BX1-06","p":5,"a":"p5","id":"ca5","src":"assets/audio/BX1-06/ca5.mp3","sec":8.808,"t":"易错：减的是脱去的水分子数98，不是100；如果有二硫键，每形成一个还要再减去2。"},{"ep":"bx1-06","n":"BX1-06","p":6,"a":"p6","id":"cb1","src":"assets/audio/BX1-06/cb1.mp3","sec":10.08,"t":"考点六，游离的氨基、羧基和原子数的计算。每条肽链的两端，各有一个游离的氨基和一个游离的羧基。"},{"ep":"bx1-06","n":"BX1-06","p":6,"a":"p6","id":"cb2","src":"assets/audio/BX1-06/cb2.mp3","sec":9.216,"t":"所以m条肽链，至少含有m个游离的氨基和m个游离的羧基；R基中的氨基和羧基要另外加上。"},{"ep":"bx1-06","n":"BX1-06","p":6,"a":"p6","id":"cb3","src":"assets/audio/BX1-06/cb3.mp3","sec":5.976,"t":"N原子数 = 肽键数 + 肽链数 + R基中的N原子数。"},{"ep":"bx1-06","n":"BX1-06","p":6,"a":"p6","id":"cb4","src":"assets/audio/BX1-06/cb4.mp3","sec":6.408,"t":"O原子数 = 肽键数 + 2 × 肽链数 + R基中的O原子数。"},{"ep":"bx1-06","n":"BX1-06","p":6,"a":"p6","id":"cb5","src":"assets/audio/BX1-06/cb5.mp3","sec":9.432,"t":"解题方法：数“肽键 + 链端 + R基”——每个肽键含1个N、1个O，每条链的末端多1个N、2个O。"},{"ep":"bx1-06","n":"BX1-06","p":7,"a":"p7","id":"dv1","src":"assets/audio/BX1-06/dv1.mp3","sec":10.176,"t":"考点七，蛋白质结构多样性的原因。从氨基酸看：种类不同、数目成百上千、排列顺序千变万化。"},{"ep":"bx1-06","n":"BX1-06","p":7,"a":"p7","id":"dv2","src":"assets/audio/BX1-06/dv2.mp3","sec":6.984,"t":"从肽链看：肽链的盘曲、折叠方式及其形成的空间结构千差万别。"},{"ep":"bx1-06","n":"BX1-06","p":7,"a":"p7","id":"dv3","src":"assets/audio/BX1-06/dv3.mp3","sec":5.952,"t":"结构的多样性决定了功能的多样性，体现了结构与功能相适应。"},{"ep":"bx1-06","n":"BX1-06","p":7,"a":"p7","id":"dv4","src":"assets/audio/BX1-06/dv4.mp3","sec":8.616,"t":"易错：氨基酸之间脱水缩合的方式都相同，肽键的结构也都一样，它们不是多样性的原因。"},{"ep":"bx1-06","n":"BX1-06","p":8,"a":"p8","id":"dn1","src":"assets/audio/BX1-06/dn1.mp3","sec":11.4,"t":"考点八，蛋白质的变性。在高温、过酸、过碱或重金属盐等作用下，蛋白质的空间结构被破坏，失去生物活性。"},{"ep":"bx1-06","n":"BX1-06","p":8,"a":"p8","id":"dn2","src":"assets/audio/BX1-06/dn2.mp3","sec":7.992,"t":"变性时肽键没有断裂，所以变性后的蛋白质仍能与双缩脲试剂发生紫色反应。"},{"ep":"bx1-06","n":"BX1-06","p":8,"a":"p8","id":"dn3","src":"assets/audio/BX1-06/dn3.mp3","sec":9.408,"t":"吃熟鸡蛋、熟肉容易消化，是因为高温使蛋白质的空间结构变得伸展、松散，容易被蛋白酶水解。"},{"ep":"bx1-06","n":"BX1-06","p":8,"a":"p8","id":"dn4","src":"assets/audio/BX1-06/dn4.mp3","sec":8.784,"t":"易错：变性一般不可逆；而盐析是加盐使蛋白质析出，空间结构没有改变，是可逆的。"},{"ep":"bx1-06","n":"BX1-06","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-06/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-06","n":"BX1-06","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-06/rv2.mp3","sec":8.784,"t":"判断一？错，性激素是固醇。判断二？错，是至少含有一个氨基和一个羧基。"},{"ep":"bx1-06","n":"BX1-06","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-06/rv3.mp3","sec":4.656,"t":"判断三？对。判断四？对。"},{"ep":"bx1-06","n":"BX1-06","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-06/rv4.mp3","sec":9.528,"t":"判断五？错，肽键没有断裂，仍能变紫。判断六？错，脱水缩合的方式都相同。"},{"ep":"bx1-06","n":"BX1-06","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-06/rv5.mp3","sec":6.264,"t":"八个考点串成一条线：脱一个水，成一个肽键。我们下期再见！"},{"ep":"bx1-07","n":"BX1-07","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-07/in1.mp3","sec":8.016,"t":"同学们好！这节课梳理人教版必修一第二章第五节——核酸是遗传信息的携带者。"},{"ep":"bx1-07","n":"BX1-07","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-07/in2.mp3","sec":9.0,"t":"高考常考DNA与RNA的比较、不同生物所含碱基和核苷酸的种类，以及生物大分子的单体。"},{"ep":"bx1-07","n":"BX1-07","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-07/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-07","n":"BX1-07","p":1,"a":"p1","id":"kn1","src":"assets/audio/BX1-07/kn1.mp3","sec":9.84,"t":"考点一，核酸的种类和分布。核酸包括两大类：脱氧核糖核酸，DNA，和核糖核酸，RNA。"},{"ep":"bx1-07","n":"BX1-07","p":1,"a":"p1","id":"kn2","src":"assets/audio/BX1-07/kn2.mp3","sec":7.68,"t":"真核细胞的DNA主要分布在细胞核中，线粒体、叶绿体内也含有少量的DNA。"},{"ep":"bx1-07","n":"BX1-07","p":1,"a":"p1","id":"kn3","src":"assets/audio/BX1-07/kn3.mp3","sec":3.12,"t":"RNA主要分布在细胞质中。"},{"ep":"bx1-07","n":"BX1-07","p":1,"a":"p1","id":"kn4","src":"assets/audio/BX1-07/kn4.mp3","sec":7.224,"t":"易错：是“主要”分布，不是“只”分布；原核细胞没有细胞核，DNA在拟核中。"},{"ep":"bx1-07","n":"BX1-07","p":2,"a":"p2","id":"nt1","src":"assets/audio/BX1-07/nt1.mp3","sec":5.736,"t":"考点二，核苷酸的组成。核酸的基本单位是核苷酸。"},{"ep":"bx1-07","n":"BX1-07","p":2,"a":"p2","id":"nt2","src":"assets/audio/BX1-07/nt2.mp3","sec":6.744,"t":"一分子核苷酸由一分子磷酸、一分子五碳糖和一分子含氮碱基组成。"},{"ep":"bx1-07","n":"BX1-07","p":2,"a":"p2","id":"nt3","src":"assets/audio/BX1-07/nt3.mp3","sec":10.896,"t":"核苷酸连接成长链构成核酸：DNA通常由两条脱氧核苷酸链构成，RNA通常由一条核糖核苷酸链构成。"},{"ep":"bx1-07","n":"BX1-07","p":2,"a":"p2","id":"nt4","src":"assets/audio/BX1-07/nt4.mp3","sec":7.896,"t":"易错：核酸初步水解得到核苷酸，彻底水解得到磷酸、五碳糖和含氮碱基。"},{"ep":"bx1-07","n":"BX1-07","p":3,"a":"p3","id":"cm1","src":"assets/audio/BX1-07/cm1.mp3","sec":10.704,"t":"考点三，DNA与RNA的比较。基本单位：DNA是脱氧核苷酸，RNA是核糖核苷酸，各有4种。"},{"ep":"bx1-07","n":"BX1-07","p":3,"a":"p3","id":"cm2","src":"assets/audio/BX1-07/cm2.mp3","sec":4.992,"t":"五碳糖：DNA含脱氧核糖，RNA含核糖。"},{"ep":"bx1-07","n":"BX1-07","p":3,"a":"p3","id":"cm3","src":"assets/audio/BX1-07/cm3.mp3","sec":8.64,"t":"碱基：两者都有A、G、C；DNA特有T，胸腺嘧啶；RNA特有U，尿嘧啶。"},{"ep":"bx1-07","n":"BX1-07","p":3,"a":"p3","id":"cm4","src":"assets/audio/BX1-07/cm4.mp3","sec":7.056,"t":"解题方法：区分DNA和RNA，看五碳糖，或者看含T还是含U。"},{"ep":"bx1-07","n":"BX1-07","p":4,"a":"p4","id":"ct1","src":"assets/audio/BX1-07/ct1.mp3","sec":8.28,"t":"考点四，不同生物的碱基和核苷酸种类。细胞生物同时含有DNA和RNA。"},{"ep":"bx1-07","n":"BX1-07","p":4,"a":"p4","id":"ct2","src":"assets/audio/BX1-07/ct2.mp3","sec":5.712,"t":"所以细胞生物有5种碱基、8种核苷酸、2种五碳糖。"},{"ep":"bx1-07","n":"BX1-07","p":4,"a":"p4","id":"ct3","src":"assets/audio/BX1-07/ct3.mp3","sec":7.584,"t":"病毒只含有一种核酸，DNA或RNA，所以只有4种碱基、4种核苷酸。"},{"ep":"bx1-07","n":"BX1-07","p":4,"a":"p4","id":"ct4","src":"assets/audio/BX1-07/ct4.mp3","sec":10.08,"t":"易错：碱基5种、核苷酸却有8种，因为A、G、C各对应两种核苷酸，T和U只各对应一种。"},{"ep":"bx1-07","n":"BX1-07","p":5,"a":"p5","id":"gm1","src":"assets/audio/BX1-07/gm1.mp3","sec":8.232,"t":"考点五，生物的遗传物质。细胞生物，无论真核还是原核，遗传物质都是DNA。"},{"ep":"bx1-07","n":"BX1-07","p":5,"a":"p5","id":"gm2","src":"assets/audio/BX1-07/gm2.mp3","sec":10.512,"t":"病毒的遗传物质是DNA或RNA：噬菌体是DNA；HIV、烟草花叶病毒、新冠病毒是RNA。"},{"ep":"bx1-07","n":"BX1-07","p":5,"a":"p5","id":"gm3","src":"assets/audio/BX1-07/gm3.mp3","sec":7.608,"t":"易错：“细胞质中的遗传物质是RNA”是错的，细胞生物的遗传物质只有DNA。"},{"ep":"bx1-07","n":"BX1-07","p":6,"a":"p6","id":"fc1","src":"assets/audio/BX1-07/fc1.mp3","sec":11.568,"t":"考点六，核酸的功能。核酸是细胞内携带遗传信息的物质，在遗传、变异和蛋白质的生物合成中有极其重要的作用。"},{"ep":"bx1-07","n":"BX1-07","p":6,"a":"p6","id":"fc2","src":"assets/audio/BX1-07/fc2.mp3","sec":8.352,"t":"遗传信息储存在核苷酸的排列顺序中；对DNA来说，就是脱氧核苷酸的排列顺序。"},{"ep":"bx1-07","n":"BX1-07","p":6,"a":"p6","id":"fc3","src":"assets/audio/BX1-07/fc3.mp3","sec":8.952,"t":"核苷酸虽然只有4种，但数量多、排列顺序千变万化，所以DNA能储存大量的遗传信息。"},{"ep":"bx1-07","n":"BX1-07","p":6,"a":"p6","id":"fc4","src":"assets/audio/BX1-07/fc4.mp3","sec":10.032,"t":"考法：DNA指纹用于刑侦和亲子鉴定。解题方法：原理是不同个体DNA的脱氧核苷酸序列不同。"},{"ep":"bx1-07","n":"BX1-07","p":7,"a":"p7","id":"mm1","src":"assets/audio/BX1-07/mm1.mp3","sec":10.992,"t":"考点七，生物大分子以碳链为骨架。多糖、蛋白质、核酸都是生物大分子，由许多单体连接成多聚体。"},{"ep":"bx1-07","n":"BX1-07","p":7,"a":"p7","id":"mm2","src":"assets/audio/BX1-07/mm2.mp3","sec":6.504,"t":"多糖的单体是单糖，蛋白质的单体是氨基酸，核酸的单体是核苷酸。"},{"ep":"bx1-07","n":"BX1-07","p":7,"a":"p7","id":"mm3","src":"assets/audio/BX1-07/mm3.mp3","sec":8.424,"t":"每个单体都以若干个相连的碳原子构成的碳链为基本骨架，所以说“碳是生命的核心元素”。"},{"ep":"bx1-07","n":"BX1-07","p":7,"a":"p7","id":"mm4","src":"assets/audio/BX1-07/mm4.mp3","sec":8.4,"t":"易错：脂肪不是生物大分子，没有单体；淀粉、糖原、纤维素的单体都是葡萄糖。"},{"ep":"bx1-07","n":"BX1-07","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-07/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-07","n":"BX1-07","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-07/rv2.mp3","sec":8.256,"t":"判断一？错，DNA主要分布在细胞核。判断二？错，五碳糖也不同。"},{"ep":"bx1-07","n":"BX1-07","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-07/rv3.mp3","sec":7.512,"t":"判断三？对。判断四？错，细胞生物的遗传物质都是DNA。"},{"ep":"bx1-07","n":"BX1-07","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-07/rv4.mp3","sec":8.112,"t":"判断五？错，彻底水解得到磷酸、五碳糖和碱基。判断六？对。"},{"ep":"bx1-07","n":"BX1-07","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-07/rv5.mp3","sec":8.376,"t":"七个考点串成一条线：看五碳糖和碱基，分清DNA和RNA。我们下期再见！"},{"ep":"bx1-08","n":"BX1-08","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-08/in1.mp3","sec":7.608,"t":"同学们好！这节课梳理人教版必修一第三章第一节——细胞膜的结构和功能。"},{"ep":"bx1-08","n":"BX1-08","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-08/in2.mp3","sec":6.84,"t":"高考常考细胞膜的三大功能、膜结构的探索历程，以及流动镶嵌模型。"},{"ep":"bx1-08","n":"BX1-08","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-08/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-08","n":"BX1-08","p":1,"a":"p1","id":"fn1","src":"assets/audio/BX1-08/fn1.mp3","sec":9.192,"t":"考点一，细胞膜的功能。第一，将细胞与外界环境分隔开，保障细胞内部环境的相对稳定。"},{"ep":"bx1-08","n":"BX1-08","p":1,"a":"p1","id":"fn2","src":"assets/audio/BX1-08/fn2.mp3","sec":8.352,"t":"第二，控制物质进出细胞；但这种控制作用是相对的，有些病毒、病菌也能侵入细胞。"},{"ep":"bx1-08","n":"BX1-08","p":1,"a":"p1","id":"fn3","src":"assets/audio/BX1-08/fn3.mp3","sec":3.48,"t":"第三，进行细胞间的信息交流。"},{"ep":"bx1-08","n":"BX1-08","p":1,"a":"p1","id":"fn4","src":"assets/audio/BX1-08/fn4.mp3","sec":10.128,"t":"考法：用台盼蓝染色鉴别死活细胞，死细胞被染色，活细胞不着色，体现了细胞膜控制物质进出的功能。"},{"ep":"bx1-08","n":"BX1-08","p":2,"a":"p2","id":"sg1","src":"assets/audio/BX1-08/sg1.mp3","sec":11.976,"t":"考点二，细胞间信息交流的三种方式。第一，通过化学物质传递：如激素随血液到达全身，与靶细胞膜表面的受体结合。"},{"ep":"bx1-08","n":"BX1-08","p":2,"a":"p2","id":"sg2","src":"assets/audio/BX1-08/sg2.mp3","sec":7.68,"t":"第二，相邻两个细胞的细胞膜直接接触：如精子和卵细胞之间的识别和结合。"},{"ep":"bx1-08","n":"BX1-08","p":2,"a":"p2","id":"sg3","src":"assets/audio/BX1-08/sg3.mp3","sec":7.008,"t":"第三，相邻两个细胞之间形成通道：如高等植物细胞之间的胞间连丝。"},{"ep":"bx1-08","n":"BX1-08","p":2,"a":"p2","id":"sg4","src":"assets/audio/BX1-08/sg4.mp3","sec":8.544,"t":"易错：信息交流不一定需要膜上的受体，胞间连丝就不需要；有些激素的受体在细胞内。"},{"ep":"bx1-08","n":"BX1-08","p":3,"a":"p3","id":"co1","src":"assets/audio/BX1-08/co1.mp3","sec":11.904,"t":"考点三，对细胞膜成分的探索。欧文顿发现，溶于脂质的物质更容易穿过细胞膜，推测细胞膜的主要组成成分中有脂质。"},{"ep":"bx1-08","n":"BX1-08","p":3,"a":"p3","id":"co2","src":"assets/audio/BX1-08/co2.mp3","sec":4.344,"t":"进一步分析得知，膜中的脂质主要是磷脂。"},{"ep":"bx1-08","n":"BX1-08","p":3,"a":"p3","id":"co3","src":"assets/audio/BX1-08/co3.mp3","sec":11.232,"t":"科学家从人的红细胞中提取脂质，铺成单分子层，面积恰为红细胞表面积的2倍，推断磷脂分子排列为连续的两层。"},{"ep":"bx1-08","n":"BX1-08","p":3,"a":"p3","id":"co4","src":"assets/audio/BX1-08/co4.mp3","sec":7.728,"t":"人们又发现细胞的表面张力明显低于油—水界面，推测细胞膜中还附有蛋白质。"},{"ep":"bx1-08","n":"BX1-08","p":3,"a":"p3","id":"co5","src":"assets/audio/BX1-08/co5.mp3","sec":11.256,"t":"考法：为什么用哺乳动物成熟的红细胞制备细胞膜？解题方法：它没有细胞核和众多的细胞器，得到的膜比较纯净。"},{"ep":"bx1-08","n":"BX1-08","p":4,"a":"p4","id":"st1","src":"assets/audio/BX1-08/st1.mp3","sec":9.792,"t":"考点四，对细胞膜结构的探索。罗伯特森在电镜下看到细胞膜呈清晰的暗—亮—暗三层结构。"},{"ep":"bx1-08","n":"BX1-08","p":4,"a":"p4","id":"st2","src":"assets/audio/BX1-08/st2.mp3","sec":11.568,"t":"他提出细胞膜由蛋白质—脂质—蛋白质三层构成，是静态的统一结构；但这无法解释细胞的生长、变形虫的运动等现象。"},{"ep":"bx1-08","n":"BX1-08","p":4,"a":"p4","id":"st3","src":"assets/audio/BX1-08/st3.mp3","sec":9.456,"t":"1970年，科学家用荧光染料分别标记小鼠细胞和人细胞表面的蛋白质，再让两种细胞融合。"},{"ep":"bx1-08","n":"BX1-08","p":4,"a":"p4","id":"st4","src":"assets/audio/BX1-08/st4.mp3","sec":12.0,"t":"刚融合时，一半发红色荧光，一半发绿色荧光；37℃下经过40分钟，两种颜色均匀分布，说明细胞膜具有流动性。"},{"ep":"bx1-08","n":"BX1-08","p":4,"a":"p4","id":"st5","src":"assets/audio/BX1-08/st5.mp3","sec":8.616,"t":"易错：人鼠细胞融合实验证明膜蛋白可以运动，用的是荧光标记法，不是同位素标记法。"},{"ep":"bx1-08","n":"BX1-08","p":5,"a":"p5","id":"md1","src":"assets/audio/BX1-08/md1.mp3","sec":8.112,"t":"考点五，流动镶嵌模型。1972年，辛格和尼科尔森提出了流动镶嵌模型。"},{"ep":"bx1-08","n":"BX1-08","p":5,"a":"p5","id":"md2","src":"assets/audio/BX1-08/md2.mp3","sec":6.648,"t":"磷脂双分子层是膜的基本支架，磷脂分子的头部亲水，尾部疏水。"},{"ep":"bx1-08","n":"BX1-08","p":5,"a":"p5","id":"md3","src":"assets/audio/BX1-08/md3.mp3","sec":9.312,"t":"蛋白质分子有的镶在磷脂双分子层表面，有的部分或全部嵌入其中，有的贯穿整个磷脂双分子层。"},{"ep":"bx1-08","n":"BX1-08","p":5,"a":"p5","id":"md4","src":"assets/audio/BX1-08/md4.mp3","sec":6.096,"t":"磷脂分子可以侧向自由移动，大多数蛋白质分子也能运动。"},{"ep":"bx1-08","n":"BX1-08","p":5,"a":"p5","id":"md5","src":"assets/audio/BX1-08/md5.mp3","sec":10.944,"t":"易错：是大多数蛋白质能运动，不是全部；膜的功能主要由蛋白质承担，功能越复杂，蛋白质的种类和数量越多。"},{"ep":"bx1-08","n":"BX1-08","p":6,"a":"p6","id":"gl1","src":"assets/audio/BX1-08/gl1.mp3","sec":12.36,"t":"考点六，糖被。细胞膜外表面的糖类分子，与蛋白质结合形成糖蛋白，与脂质结合形成糖脂，这些糖类分子叫作糖被。"},{"ep":"bx1-08","n":"BX1-08","p":6,"a":"p6","id":"gl2","src":"assets/audio/BX1-08/gl2.mp3","sec":6.144,"t":"糖被与细胞表面的识别、细胞间的信息传递等功能有密切关系。"},{"ep":"bx1-08","n":"BX1-08","p":6,"a":"p6","id":"gl3","src":"assets/audio/BX1-08/gl3.mp3","sec":8.424,"t":"解题方法：糖被只分布在细胞膜的外侧，有糖被的一侧是细胞外，可以用来判断膜的内外。"},{"ep":"bx1-08","n":"BX1-08","p":7,"a":"p7","id":"pp1","src":"assets/audio/BX1-08/pp1.mp3","sec":7.488,"t":"考点七，结构特点和功能特性。细胞膜的结构特点是具有一定的流动性。"},{"ep":"bx1-08","n":"BX1-08","p":7,"a":"p7","id":"pp2","src":"assets/audio/BX1-08/pp2.mp3","sec":6.792,"t":"实例有变形虫的变形运动、胞吞和胞吐、细胞融合、质壁分离等。"},{"ep":"bx1-08","n":"BX1-08","p":7,"a":"p7","id":"pp3","src":"assets/audio/BX1-08/pp3.mp3","sec":7.056,"t":"细胞膜的功能特性是选择透过性，这与膜上转运蛋白的种类和数量有关。"},{"ep":"bx1-08","n":"BX1-08","p":7,"a":"p7","id":"pp4","src":"assets/audio/BX1-08/pp4.mp3","sec":9.408,"t":"易错：流动性是结构特点，选择透过性是功能特性，别颠倒；流动性是选择透过性的基础。"},{"ep":"bx1-08","n":"BX1-08","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-08/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-08","n":"BX1-08","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-08/rv2.mp3","sec":8.256,"t":"判断一？错，控制作用是相对的。判断二？错，胞间连丝不需要受体。"},{"ep":"bx1-08","n":"BX1-08","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-08/rv3.mp3","sec":6.408,"t":"判断三？对。判断四？错，用的是荧光标记法。"},{"ep":"bx1-08","n":"BX1-08","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-08/rv4.mp3","sec":8.544,"t":"判断五？错，糖被只在外侧。判断六？错，功能特性是选择透过性。"},{"ep":"bx1-08","n":"BX1-08","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-08/rv5.mp3","sec":8.544,"t":"七个考点串成一条线：结构决定功能，流动性是选择透过性的基础。我们下期再见！"},{"ep":"bx1-09","n":"BX1-09","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-09/in1.mp3","sec":10.464,"t":"同学们好！这节课梳理人教版必修一第三章第二节——细胞器之间的分工合作的上半部分：细胞器之间的分工。"},{"ep":"bx1-09","n":"BX1-09","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-09/in2.mp3","sec":7.176,"t":"高考常考各种细胞器的结构和功能，以及按膜、成分和分布给细胞器归类。"},{"ep":"bx1-09","n":"BX1-09","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-09/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-09","n":"BX1-09","p":1,"a":"p1","id":"cf1","src":"assets/audio/BX1-09/cf1.mp3","sec":10.704,"t":"考点一，分离细胞器的方法——差速离心法。先破坏细胞膜，形成由各种细胞器和细胞中其他物质组成的匀浆。"},{"ep":"bx1-09","n":"BX1-09","p":1,"a":"p1","id":"cf2","src":"assets/audio/BX1-09/cf2.mp3","sec":7.248,"t":"再用逐渐提高离心速率的方法分离不同大小的颗粒：颗粒越大，越先沉降。"},{"ep":"bx1-09","n":"BX1-09","p":1,"a":"p1","id":"cf3","src":"assets/audio/BX1-09/cf3.mp3","sec":8.832,"t":"易错：差速离心是逐渐提高转速；要和证明DNA半保留复制用的密度梯度离心区分开。"},{"ep":"bx1-09","n":"BX1-09","p":2,"a":"p2","id":"mt1","src":"assets/audio/BX1-09/mt1.mp3","sec":8.136,"t":"考点二，线粒体。线粒体是细胞进行有氧呼吸的主要场所，是细胞的“动力车间”。"},{"ep":"bx1-09","n":"BX1-09","p":2,"a":"p2","id":"mt2","src":"assets/audio/BX1-09/mt2.mp3","sec":7.392,"t":"线粒体具有双层膜，内膜的某些部位向内腔折叠形成嵴，增大了膜面积。"},{"ep":"bx1-09","n":"BX1-09","p":2,"a":"p2","id":"mt3","src":"assets/audio/BX1-09/mt3.mp3","sec":6.912,"t":"线粒体中含有少量的DNA和RNA，能合成一部分自身需要的蛋白质。"},{"ep":"bx1-09","n":"BX1-09","p":2,"a":"p2","id":"mt4","src":"assets/audio/BX1-09/mt4.mp3","sec":11.256,"t":"考法：代谢旺盛的细胞，如心肌细胞，线粒体多。易错：线粒体不能直接分解葡萄糖，进入线粒体的是丙酮酸。"},{"ep":"bx1-09","n":"BX1-09","p":3,"a":"p3","id":"cl1","src":"assets/audio/BX1-09/cl1.mp3","sec":9.048,"t":"考点三，叶绿体。叶绿体是光合作用的场所，是植物细胞的“养料制造车间”和“能量转换站”。"},{"ep":"bx1-09","n":"BX1-09","p":3,"a":"p3","id":"cl2","src":"assets/audio/BX1-09/cl2.mp3","sec":7.944,"t":"叶绿体也有双层膜，内部有许多基粒，每个基粒由一个个圆饼状的类囊体堆叠而成。"},{"ep":"bx1-09","n":"BX1-09","p":3,"a":"p3","id":"cl3","src":"assets/audio/BX1-09/cl3.mp3","sec":7.416,"t":"类囊体的薄膜上分布着光合色素；叶绿体中也含有少量的DNA和RNA。"},{"ep":"bx1-09","n":"BX1-09","p":3,"a":"p3","id":"cl4","src":"assets/audio/BX1-09/cl4.mp3","sec":9.288,"t":"易错：植物细胞不一定都有叶绿体，如根尖细胞；能光合作用的也不一定有叶绿体，如蓝细菌。"},{"ep":"bx1-09","n":"BX1-09","p":4,"a":"p4","id":"er1","src":"assets/audio/BX1-09/er1.mp3","sec":11.64,"t":"考点四，内质网和高尔基体。内质网是由膜连接而成的网状结构，是蛋白质等大分子的合成、加工场所和运输通道。"},{"ep":"bx1-09","n":"BX1-09","p":4,"a":"p4","id":"er2","src":"assets/audio/BX1-09/er2.mp3","sec":6.504,"t":"粗面内质网上附着有核糖体；光面内质网是脂质合成的场所。"},{"ep":"bx1-09","n":"BX1-09","p":4,"a":"p4","id":"er3","src":"assets/audio/BX1-09/er3.mp3","sec":7.968,"t":"高尔基体主要对来自内质网的蛋白质进行加工、分类和包装，是“车间”及“发送站”。"},{"ep":"bx1-09","n":"BX1-09","p":4,"a":"p4","id":"er4","src":"assets/audio/BX1-09/er4.mp3","sec":8.592,"t":"易错：高尔基体在植物细胞中与细胞壁的形成有关，在动物细胞中与分泌物的形成有关。"},{"ep":"bx1-09","n":"BX1-09","p":5,"a":"p5","id":"ly1","src":"assets/audio/BX1-09/ly1.mp3","sec":7.776,"t":"考点五，溶酶体和液泡。溶酶体内部含有多种水解酶，是细胞的“消化车间”。"},{"ep":"bx1-09","n":"BX1-09","p":5,"a":"p5","id":"ly2","src":"assets/audio/BX1-09/ly2.mp3","sec":6.888,"t":"它能分解衰老、损伤的细胞器，吞噬并杀死侵入细胞的病毒或细菌。"},{"ep":"bx1-09","n":"BX1-09","p":5,"a":"p5","id":"ly3","src":"assets/audio/BX1-09/ly3.mp3","sec":12.216,"t":"液泡主要存在于植物细胞中，内有细胞液，含糖类、无机盐、色素和蛋白质等，可以调节细胞内的环境，使植物细胞保持坚挺。"},{"ep":"bx1-09","n":"BX1-09","p":5,"a":"p5","id":"ly4","src":"assets/audio/BX1-09/ly4.mp3","sec":8.424,"t":"易错：溶酶体的水解酶是在核糖体上合成的；花瓣、果实的颜色来自液泡中的色素。"},{"ep":"bx1-09","n":"BX1-09","p":6,"a":"p6","id":"nm1","src":"assets/audio/BX1-09/nm1.mp3","sec":11.664,"t":"考点六，核糖体、中心体和细胞骨架。核糖体是“生产蛋白质的机器”，有的附着在内质网上，有的游离在细胞质中。"},{"ep":"bx1-09","n":"BX1-09","p":6,"a":"p6","id":"nm2","src":"assets/audio/BX1-09/nm2.mp3","sec":9.864,"t":"中心体见于动物和某些低等植物细胞，由两个互相垂直的中心粒及周围物质组成，与细胞的有丝分裂有关。"},{"ep":"bx1-09","n":"BX1-09","p":6,"a":"p6","id":"nm3","src":"assets/audio/BX1-09/nm3.mp3","sec":8.664,"t":"细胞骨架是由蛋白质纤维组成的网架结构，维持细胞的形态，锚定并支撑着许多细胞器。"},{"ep":"bx1-09","n":"BX1-09","p":6,"a":"p6","id":"nm4","src":"assets/audio/BX1-09/nm4.mp3","sec":7.56,"t":"易错：细胞骨架的成分是蛋白质，不是纤维素；高等植物细胞没有中心体。"},{"ep":"bx1-09","n":"BX1-09","p":7,"a":"p7","id":"sm1","src":"assets/audio/BX1-09/sm1.mp3","sec":10.2,"t":"考点七，细胞器的归纳。双层膜：线粒体、叶绿体；无膜：核糖体、中心体；其余是单层膜。"},{"ep":"bx1-09","n":"BX1-09","p":7,"a":"p7","id":"sm2","src":"assets/audio/BX1-09/sm2.mp3","sec":7.152,"t":"含核酸的：线粒体、叶绿体含DNA和RNA，核糖体只含RNA。"},{"ep":"bx1-09","n":"BX1-09","p":7,"a":"p7","id":"sm3","src":"assets/audio/BX1-09/sm3.mp3","sec":13.896,"t":"含色素的：叶绿体和液泡。叶绿体存在于绿色植物能进行光合作用的细胞中，液泡主要存在于植物细胞中；中心体见于动物和某些低等植物细胞。"},{"ep":"bx1-09","n":"BX1-09","p":7,"a":"p7","id":"sm4","src":"assets/audio/BX1-09/sm4.mp3","sec":9.408,"t":"解题方法：按膜层数、含核酸、含色素、分布四个维度列表记忆，题目问哪个维度就查哪一列。"},{"ep":"bx1-09","n":"BX1-09","p":8,"a":"p8","id":"ob1","src":"assets/audio/BX1-09/ob1.mp3","sec":11.04,"t":"考点八，用高倍显微镜观察叶绿体和细胞质的流动。常用藓类的叶或黑藻的叶，叶片薄，可以直接制成装片。"},{"ep":"bx1-09","n":"BX1-09","p":8,"a":"p8","id":"ob2","src":"assets/audio/BX1-09/ob2.mp3","sec":9.288,"t":"用菠菜叶时，要撕取稍带些叶肉的下表皮，因为靠近下表皮的叶肉细胞中，叶绿体大而数目少。"},{"ep":"bx1-09","n":"BX1-09","p":8,"a":"p8","id":"ob3","src":"assets/audio/BX1-09/ob3.mp3","sec":7.776,"t":"观察细胞质的流动，以叶绿体的运动作为标志；临时装片要随时保持有水的状态。"},{"ep":"bx1-09","n":"BX1-09","p":8,"a":"p8","id":"ob4","src":"assets/audio/BX1-09/ob4.mp3","sec":7.68,"t":"易错：视野中细胞质环流的方向与实际方向相同；观察叶绿体不需要染色。"},{"ep":"bx1-09","n":"BX1-09","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-09/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-09","n":"BX1-09","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-09/rv2.mp3","sec":8.52,"t":"判断一？错，是逐渐提高转速。判断二？错，进入线粒体的是丙酮酸。"},{"ep":"bx1-09","n":"BX1-09","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-09/rv3.mp3","sec":9.048,"t":"判断三？错，根尖细胞就没有叶绿体。判断四？错，水解酶在核糖体上合成。"},{"ep":"bx1-09","n":"BX1-09","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-09/rv4.mp3","sec":6.048,"t":"判断五？对。判断六？对，环流方向不变。"},{"ep":"bx1-09","n":"BX1-09","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-09/rv5.mp3","sec":9.504,"t":"八个考点串成一条线：膜层数、核酸、色素、分布，四个维度归纳细胞器。我们下期再见！"},{"ep":"bx1-10","n":"BX1-10","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-10/in1.mp3","sec":10.368,"t":"同学们好！这节课梳理人教版必修一第三章第二节的下半部分——细胞器之间的协调配合和细胞的生物膜系统。"},{"ep":"bx1-10","n":"BX1-10","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-10/in2.mp3","sec":7.8,"t":"高考常考分泌蛋白的合成和运输途径，以及放射性出现的顺序和膜面积的变化。"},{"ep":"bx1-10","n":"BX1-10","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-10/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-10","n":"BX1-10","p":1,"a":"p1","id":"se1","src":"assets/audio/BX1-10/se1.mp3","sec":8.784,"t":"考点一，分泌蛋白。在细胞内合成后，分泌到细胞外起作用的蛋白质，叫作分泌蛋白。"},{"ep":"bx1-10","n":"BX1-10","p":1,"a":"p1","id":"se2","src":"assets/audio/BX1-10/se2.mp3","sec":5.28,"t":"常见的有消化酶、抗体和一部分激素，比如胰岛素。"},{"ep":"bx1-10","n":"BX1-10","p":1,"a":"p1","id":"se3","src":"assets/audio/BX1-10/se3.mp3","sec":8.568,"t":"易错：血红蛋白、呼吸酶在细胞内起作用，不是分泌蛋白；性激素是固醇，也不是。"},{"ep":"bx1-10","n":"BX1-10","p":2,"a":"p2","id":"lb1","src":"assets/audio/BX1-10/lb1.mp3","sec":9.264,"t":"考点二，研究方法——同位素标记法。科学家向豚鼠的胰腺腺泡细胞中注射3H标记的亮氨酸。"},{"ep":"bx1-10","n":"BX1-10","p":2,"a":"p2","id":"lb2","src":"assets/audio/BX1-10/lb2.mp3","sec":7.152,"t":"然后追踪放射性依次出现的位置，就知道了分泌蛋白合成和运输的途径。"},{"ep":"bx1-10","n":"BX1-10","p":2,"a":"p2","id":"lb3","src":"assets/audio/BX1-10/lb3.mp3","sec":10.656,"t":"易错：标记的是亮氨酸——蛋白质的原料；如果标记胸腺嘧啶或尿嘧啶，追踪的就是DNA或RNA的合成了。"},{"ep":"bx1-10","n":"BX1-10","p":3,"a":"p3","id":"ro1","src":"assets/audio/BX1-10/ro1.mp3","sec":11.832,"t":"考点三，分泌蛋白的合成和运输。先在游离的核糖体上合成一段肽链，再与核糖体一起转移到粗面内质网上继续合成。"},{"ep":"bx1-10","n":"BX1-10","p":3,"a":"p3","id":"ro2","src":"assets/audio/BX1-10/ro2.mp3","sec":9.168,"t":"肽链在内质网腔内加工、折叠，形成有一定空间结构的蛋白质，再由囊泡包裹着运到高尔基体。"},{"ep":"bx1-10","n":"BX1-10","p":3,"a":"p3","id":"ro3","src":"assets/audio/BX1-10/ro3.mp3","sec":9.672,"t":"高尔基体对蛋白质做进一步的修饰加工，再由囊泡运到细胞膜，与细胞膜融合，把蛋白质分泌到细胞外。"},{"ep":"bx1-10","n":"BX1-10","p":3,"a":"p3","id":"ro4","src":"assets/audio/BX1-10/ro4.mp3","sec":3.912,"t":"整个过程需要的能量，主要来自线粒体。"},{"ep":"bx1-10","n":"BX1-10","p":3,"a":"p3","id":"ro5","src":"assets/audio/BX1-10/ro5.mp3","sec":8.064,"t":"解题方法：记住路线——核糖体 → 内质网 → 高尔基体 → 细胞膜，线粒体全程供能。"},{"ep":"bx1-10","n":"BX1-10","p":4,"a":"p4","id":"cv1","src":"assets/audio/BX1-10/cv1.mp3","sec":12.24,"t":"考点四，放射性和膜面积的变化。放射性依次出现在附着有核糖体的内质网、高尔基体、靠近细胞膜的囊泡，最后到细胞外。"},{"ep":"bx1-10","n":"BX1-10","p":4,"a":"p4","id":"cv2","src":"assets/audio/BX1-10/cv2.mp3","sec":7.776,"t":"膜面积：内质网膜减少，高尔基体膜先增加后减少、基本不变，细胞膜增加。"},{"ep":"bx1-10","n":"BX1-10","p":4,"a":"p4","id":"cv3","src":"assets/audio/BX1-10/cv3.mp3","sec":8.208,"t":"解题方法：看柱形图，减少的是内质网，前后不变的是高尔基体，增加的是细胞膜。"},{"ep":"bx1-10","n":"BX1-10","p":5,"a":"p5","id":"sy1","src":"assets/audio/BX1-10/sy1.mp3","sec":9.456,"t":"考点五，细胞的生物膜系统。细胞膜、核膜和细胞器膜等结构，共同构成细胞的生物膜系统。"},{"ep":"bx1-10","n":"BX1-10","p":5,"a":"p5","id":"sy2","src":"assets/audio/BX1-10/sy2.mp3","sec":6.456,"t":"这些生物膜的组成成分和结构很相似，在结构和功能上紧密联系。"},{"ep":"bx1-10","n":"BX1-10","p":5,"a":"p5","id":"sy3","src":"assets/audio/BX1-10/sy3.mp3","sec":9.312,"t":"功能一，使细胞具有相对稳定的内部环境，在物质运输、能量转化和信息传递中起决定性作用。"},{"ep":"bx1-10","n":"BX1-10","p":5,"a":"p5","id":"sy4","src":"assets/audio/BX1-10/sy4.mp3","sec":11.4,"t":"功能二，广阔的膜面积为多种酶提供了附着位点；功能三，把细胞器分隔开，使多种化学反应同时进行而互不干扰。"},{"ep":"bx1-10","n":"BX1-10","p":5,"a":"p5","id":"sy5","src":"assets/audio/BX1-10/sy5.mp3","sec":8.88,"t":"易错：生物膜系统指细胞内的膜，小肠黏膜不属于；原核细胞只有细胞膜，没有生物膜系统。"},{"ep":"bx1-10","n":"BX1-10","p":6,"a":"p6","id":"tp1","src":"assets/audio/BX1-10/tp1.mp3","sec":7.008,"t":"考点六，易错辨析。分泌蛋白通过胞吐出细胞，穿过的膜是0层。"},{"ep":"bx1-10","n":"BX1-10","p":6,"a":"p6","id":"tp2","src":"assets/audio/BX1-10/tp2.mp3","sec":7.632,"t":"囊泡与膜融合，体现了生物膜的流动性，也说明不同生物膜之间可以相互转化。"},{"ep":"bx1-10","n":"BX1-10","p":6,"a":"p6","id":"tp3","src":"assets/audio/BX1-10/tp3.mp3","sec":7.704,"t":"内质网膜可以直接与核膜、细胞膜相连；与高尔基体膜则通过囊泡间接联系。"},{"ep":"bx1-10","n":"BX1-10","p":6,"a":"p6","id":"tp4","src":"assets/audio/BX1-10/tp4.mp3","sec":6.912,"t":"解题方法：问“穿过几层膜”，凡是囊泡运输、胞吞和胞吐，都答0层。"},{"ep":"bx1-10","n":"BX1-10","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-10/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-10","n":"BX1-10","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-10/rv2.mp3","sec":6.48,"t":"判断一？错，它们在细胞内起作用。判断二？对。"},{"ep":"bx1-10","n":"BX1-10","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-10/rv3.mp3","sec":9.6,"t":"判断三？错，先在游离的核糖体上合成。判断四？错，高尔基体膜面积基本不变。"},{"ep":"bx1-10","n":"BX1-10","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-10/rv4.mp3","sec":7.008,"t":"判断五？错，生物膜系统指细胞内的膜。判断六？对。"},{"ep":"bx1-10","n":"BX1-10","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-10/rv5.mp3","sec":9.264,"t":"六个考点串成一条线：核糖体、内质网、高尔基体、细胞膜，线粒体供能。我们下期再见！"},{"ep":"bx1-11","n":"BX1-11","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-11/in1.mp3","sec":7.68,"t":"同学们好！这节课梳理人教版必修一第三章第三节——细胞核的结构和功能。"},{"ep":"bx1-11","n":"BX1-11","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-11/in2.mp3","sec":6.936,"t":"高考常考探究细胞核功能的实验、细胞核的结构，以及三类模型的判断。"},{"ep":"bx1-11","n":"BX1-11","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-11/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-11","n":"BX1-11","p":1,"a":"p1","id":"fn1","src":"assets/audio/BX1-11/fn1.mp3","sec":8.016,"t":"考点一，细胞核的功能。细胞核是遗传信息库，是细胞代谢和遗传的控制中心。"},{"ep":"bx1-11","n":"BX1-11","p":1,"a":"p1","id":"fn2","src":"assets/audio/BX1-11/fn2.mp3","sec":6.288,"t":"原因是DNA主要存在于细胞核中，DNA上储存着遗传信息。"},{"ep":"bx1-11","n":"BX1-11","p":1,"a":"p1","id":"fn3","src":"assets/audio/BX1-11/fn3.mp3","sec":8.664,"t":"易错：细胞核是代谢的控制中心，不是代谢的中心；细胞代谢的主要场所是细胞质基质。"},{"ep":"bx1-11","n":"BX1-11","p":2,"a":"p2","id":"am1","src":"assets/audio/BX1-11/am1.mp3","sec":12.552,"t":"考点二，美西螈核移植实验。把黑色美西螈胚胎细胞的细胞核，移植到白色美西螈的去核卵细胞中，发育成的美西螈全是黑色的。"},{"ep":"bx1-11","n":"BX1-11","p":2,"a":"p2","id":"am2","src":"assets/audio/BX1-11/am2.mp3","sec":4.776,"t":"说明美西螈皮肤颜色的遗传是由细胞核控制的。"},{"ep":"bx1-11","n":"BX1-11","p":2,"a":"p2","id":"am3","src":"assets/audio/BX1-11/am3.mp3","sec":10.176,"t":"蝾螈受精卵横缢实验：有核的一半能分裂，无核的一半停止分裂；挤入一个细胞核后，无核的一半也开始分裂。"},{"ep":"bx1-11","n":"BX1-11","p":2,"a":"p2","id":"am4","src":"assets/audio/BX1-11/am4.mp3","sec":3.984,"t":"说明细胞核控制着细胞的分裂、分化。"},{"ep":"bx1-11","n":"BX1-11","p":2,"a":"p2","id":"am5","src":"assets/audio/BX1-11/am5.mp3","sec":5.832,"t":"解题方法：看后代性状和谁的细胞核一致，就由谁控制。"},{"ep":"bx1-11","n":"BX1-11","p":3,"a":"p3","id":"ag1","src":"assets/audio/BX1-11/ag1.mp3","sec":12.288,"t":"考点三，变形虫切割实验：有核的一半能摄食、对刺激有反应、生长和分裂，无核的一半不能，说明细胞核控制着细胞的生命活动。"},{"ep":"bx1-11","n":"BX1-11","p":3,"a":"p3","id":"ag2","src":"assets/audio/BX1-11/ag2.mp3","sec":8.28,"t":"伞藻嫁接实验：把菊花形帽伞藻的柄嫁接到伞形帽伞藻的假根上，长出的是伞形帽。"},{"ep":"bx1-11","n":"BX1-11","p":3,"a":"p3","id":"ag3","src":"assets/audio/BX1-11/ag3.mp3","sec":8.4,"t":"但细胞核在假根中，嫁接不能排除假根中细胞质的影响，所以还要做伞藻核移植实验。"},{"ep":"bx1-11","n":"BX1-11","p":3,"a":"p3","id":"ag4","src":"assets/audio/BX1-11/ag4.mp3","sec":8.04,"t":"解题方法：嫁接只能说明伞帽形状与假根有关，核移植才能说明与细胞核有关。"},{"ep":"bx1-11","n":"BX1-11","p":4,"a":"p4","id":"st1","src":"assets/audio/BX1-11/st1.mp3","sec":7.272,"t":"考点四，细胞核的结构。核膜是双层膜，把核内物质与细胞质分开。"},{"ep":"bx1-11","n":"BX1-11","p":4,"a":"p4","id":"st2","src":"assets/audio/BX1-11/st2.mp3","sec":4.944,"t":"核孔实现核质之间频繁的物质交换和信息交流。"},{"ep":"bx1-11","n":"BX1-11","p":4,"a":"p4","id":"st3","src":"assets/audio/BX1-11/st3.mp3","sec":4.992,"t":"核仁与某种RNA的合成以及核糖体的形成有关。"},{"ep":"bx1-11","n":"BX1-11","p":4,"a":"p4","id":"st4","src":"assets/audio/BX1-11/st4.mp3","sec":6.384,"t":"染色质主要由DNA和蛋白质组成，DNA是遗传信息的载体。"},{"ep":"bx1-11","n":"BX1-11","p":4,"a":"p4","id":"st5","src":"assets/audio/BX1-11/st5.mp3","sec":9.264,"t":"易错：核孔具有选择性，DNA不能通过核孔出细胞核；代谢旺盛的细胞，核孔多、核仁大。"},{"ep":"bx1-11","n":"BX1-11","p":5,"a":"p5","id":"ch1","src":"assets/audio/BX1-11/ch1.mp3","sec":8.424,"t":"考点五，染色质与染色体。染色质是细胞核中容易被碱性染料染成深色的物质。"},{"ep":"bx1-11","n":"BX1-11","p":5,"a":"p5","id":"ch2","src":"assets/audio/BX1-11/ch2.mp3","sec":11.952,"t":"细胞分裂时，细丝状的染色质高度螺旋化、缩短变粗，成为圆柱状或杆状的染色体；分裂结束时，又解螺旋成为染色质。"},{"ep":"bx1-11","n":"BX1-11","p":5,"a":"p5","id":"ch3","src":"assets/audio/BX1-11/ch3.mp3","sec":8.712,"t":"解题方法：染色质和染色体是同一种物质在细胞不同时期的两种存在状态，成分相同。"},{"ep":"bx1-11","n":"BX1-11","p":6,"a":"p6","id":"md1","src":"assets/audio/BX1-11/md1.mp3","sec":8.52,"t":"考点六，科学方法——建构模型。模型是对认识对象所作的一种简化的概括性描述。"},{"ep":"bx1-11","n":"BX1-11","p":6,"a":"p6","id":"md2","src":"assets/audio/BX1-11/md2.mp3","sec":10.872,"t":"物理模型以实物或图画形式直观表达认识对象的特征，比如真核细胞的三维结构模型、DNA双螺旋结构模型。"},{"ep":"bx1-11","n":"BX1-11","p":6,"a":"p6","id":"md3","src":"assets/audio/BX1-11/md3.mp3","sec":11.304,"t":"概念模型用文字、箭头等表示概念之间的关系，如概念图；数学模型用公式、曲线等表示，如种群增长曲线。"},{"ep":"bx1-11","n":"BX1-11","p":6,"a":"p6","id":"md4","src":"assets/audio/BX1-11/md4.mp3","sec":9.168,"t":"易错：照片不是模型，电镜照片是实物的真实记录；画出的细胞结构模式图才是物理模型。"},{"ep":"bx1-11","n":"BX1-11","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-11/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-11","n":"BX1-11","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-11/rv2.mp3","sec":5.784,"t":"判断一？错，是控制中心。判断二？对。"},{"ep":"bx1-11","n":"BX1-11","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-11/rv3.mp3","sec":7.968,"t":"判断三？错，还要做核移植实验。判断四？错，核孔具有选择性。"},{"ep":"bx1-11","n":"BX1-11","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-11/rv4.mp3","sec":7.44,"t":"判断五？错，是同一种物质。判断六？错，照片不是模型。"},{"ep":"bx1-11","n":"BX1-11","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-11/rv5.mp3","sec":8.736,"t":"六个考点串成一条线：细胞核是遗传信息库，是代谢和遗传的控制中心。我们下期再见！"},{"ep":"bx1-12","n":"BX1-12","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-12/in1.mp3","sec":6.552,"t":"同学们好！这节课梳理人教版必修一第四章第一节——被动运输。"},{"ep":"bx1-12","n":"BX1-12","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-12/in2.mp3","sec":8.52,"t":"高考常考渗透装置的分析、质壁分离及复原实验，以及自由扩散和协助扩散的比较。"},{"ep":"bx1-12","n":"BX1-12","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-12/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-12","n":"BX1-12","p":1,"a":"p1","id":"os1","src":"assets/audio/BX1-12/os1.mp3","sec":11.208,"t":"考点一，渗透作用。水分子等溶剂分子透过半透膜，从低浓度溶液一侧向高浓度溶液一侧扩散，叫作渗透作用。"},{"ep":"bx1-12","n":"BX1-12","p":1,"a":"p1","id":"os2","src":"assets/audio/BX1-12/os2.mp3","sec":7.968,"t":"发生渗透作用有两个条件：一是要有半透膜，二是半透膜两侧的溶液具有浓度差。"},{"ep":"bx1-12","n":"BX1-12","p":1,"a":"p1","id":"os3","src":"assets/audio/BX1-12/os3.mp3","sec":10.656,"t":"易错：这里的浓度是物质的量浓度；质量分数相同的葡萄糖溶液和蔗糖溶液，葡萄糖溶液的物质的量浓度更大。"},{"ep":"bx1-12","n":"BX1-12","p":2,"a":"p2","id":"dv1","src":"assets/audio/BX1-12/dv1.mp3","sec":9.288,"t":"考点二，渗透装置的分析。漏斗内装蔗糖溶液，烧杯中是清水，漏斗口封着一层半透膜。"},{"ep":"bx1-12","n":"BX1-12","p":2,"a":"p2","id":"dv2","src":"assets/audio/BX1-12/dv2.mp3","sec":6.096,"t":"单位时间内进入漏斗的水分子多于出来的，漏斗内液面上升。"},{"ep":"bx1-12","n":"BX1-12","p":2,"a":"p2","id":"dv3","src":"assets/audio/BX1-12/dv3.mp3","sec":9.744,"t":"液面上升到一定高度后停止：此时液柱的压力与浓度差的作用相互平衡，水分子进出达到动态平衡。"},{"ep":"bx1-12","n":"BX1-12","p":2,"a":"p2","id":"dv4","src":"assets/audio/BX1-12/dv4.mp3","sec":10.416,"t":"易错：平衡时漏斗内外浓度并不相等，漏斗内仍高于烧杯；水分子仍在双向移动，只是进出速率相等。"},{"ep":"bx1-12","n":"BX1-12","p":3,"a":"p3","id":"an1","src":"assets/audio/BX1-12/an1.mp3","sec":7.416,"t":"考点三，动物细胞的吸水和失水。动物细胞的细胞膜相当于一层半透膜。"},{"ep":"bx1-12","n":"BX1-12","p":3,"a":"p3","id":"an2","src":"assets/audio/BX1-12/an2.mp3","sec":10.728,"t":"外界溶液浓度低于细胞质浓度时，细胞吸水膨胀，甚至涨破；外界浓度高于细胞质浓度时，细胞失水皱缩。"},{"ep":"bx1-12","n":"BX1-12","p":3,"a":"p3","id":"an3","src":"assets/audio/BX1-12/an3.mp3","sec":8.544,"t":"两者浓度相同时，水分子进出平衡，细胞形态不变，所以静脉输液要用生理盐水。"},{"ep":"bx1-12","n":"BX1-12","p":3,"a":"p3","id":"an4","src":"assets/audio/BX1-12/an4.mp3","sec":9.792,"t":"考法：红细胞放入不同浓度溶液中的形态变化。解题方法：水往浓处流，先比较细胞内外的浓度。"},{"ep":"bx1-12","n":"BX1-12","p":4,"a":"p4","id":"pp1","src":"assets/audio/BX1-12/pp1.mp3","sec":8.352,"t":"考点四，原生质层。成熟的植物细胞有中央大液泡，液泡内的液体叫细胞液。"},{"ep":"bx1-12","n":"BX1-12","p":4,"a":"p4","id":"pp2","src":"assets/audio/BX1-12/pp2.mp3","sec":7.848,"t":"细胞膜和液泡膜，以及两层膜之间的细胞质，称为原生质层，相当于一层半透膜。"},{"ep":"bx1-12","n":"BX1-12","p":4,"a":"p4","id":"pp3","src":"assets/audio/BX1-12/pp3.mp3","sec":5.04,"t":"细胞壁是全透性的，而且伸缩性比原生质层小。"},{"ep":"bx1-12","n":"BX1-12","p":4,"a":"p4","id":"pp4","src":"assets/audio/BX1-12/pp4.mp3","sec":9.72,"t":"易错：原生质层不包括细胞液，也不能把细胞壁算进去；起半透膜作用的是原生质层，不是细胞壁。"},{"ep":"bx1-12","n":"BX1-12","p":5,"a":"p5","id":"pl1","src":"assets/audio/BX1-12/pl1.mp3","sec":9.624,"t":"考点五，探究植物细胞的吸水和失水。常用紫色洋葱鳞片叶的外表皮，液泡有颜色，便于观察。"},{"ep":"bx1-12","n":"BX1-12","p":5,"a":"p5","id":"pl2","src":"assets/audio/BX1-12/pl2.mp3","sec":10.248,"t":"滴加0.3 g/mL的蔗糖溶液，原生质层与细胞壁逐渐分离，出现质壁分离，液泡变小、颜色变深。"},{"ep":"bx1-12","n":"BX1-12","p":5,"a":"p5","id":"pl3","src":"assets/audio/BX1-12/pl3.mp3","sec":5.304,"t":"再滴加清水，液泡逐渐变大，出现质壁分离复原。"},{"ep":"bx1-12","n":"BX1-12","p":5,"a":"p5","id":"pl4","src":"assets/audio/BX1-12/pl4.mp3","sec":5.424,"t":"整个实验用低倍镜观察三次，形成前后自身对照。"},{"ep":"bx1-12","n":"BX1-12","p":5,"a":"p5","id":"pl5","src":"assets/audio/BX1-12/pl5.mp3","sec":9.816,"t":"解题方法：质壁分离的内因是原生质层的伸缩性大于细胞壁，外因是外界溶液浓度大于细胞液浓度。"},{"ep":"bx1-12","n":"BX1-12","p":6,"a":"p6","id":"ap1","src":"assets/audio/BX1-12/ap1.mp3","sec":10.296,"t":"考点六，质壁分离的应用。可以判断细胞的死活，死细胞不发生质壁分离；还可以估测细胞液浓度的范围。"},{"ep":"bx1-12","n":"BX1-12","p":6,"a":"p6","id":"ap2","src":"assets/audio/BX1-12/ap2.mp3","sec":7.2,"t":"把细胞放入一定浓度的KNO3溶液中，先发生质壁分离，随后会自动复原。"},{"ep":"bx1-12","n":"BX1-12","p":6,"a":"p6","id":"ap3","src":"assets/audio/BX1-12/ap3.mp3","sec":11.952,"t":"因为K+和NO3-可以被细胞主动吸收，细胞液浓度升高，细胞又吸水；尿素、甘油、乙二醇溶液中也会自动复原。"},{"ep":"bx1-12","n":"BX1-12","p":6,"a":"p6","id":"ap4","src":"assets/audio/BX1-12/ap4.mp3","sec":10.176,"t":"易错：外界溶液浓度过高，细胞失水过多而死亡，就不能复原；动物细胞没有细胞壁，不会发生质壁分离。"},{"ep":"bx1-12","n":"BX1-12","p":7,"a":"p7","id":"df1","src":"assets/audio/BX1-12/df1.mp3","sec":11.496,"t":"考点七，被动运输。物质以扩散方式进出细胞，不需要消耗细胞内化学反应释放的能量，包括自由扩散和协助扩散。"},{"ep":"bx1-12","n":"BX1-12","p":7,"a":"p7","id":"df2","src":"assets/audio/BX1-12/df2.mp3","sec":8.616,"t":"自由扩散：通过简单的扩散作用进出细胞，如O2、CO2、甘油、乙醇、苯等。"},{"ep":"bx1-12","n":"BX1-12","p":7,"a":"p7","id":"df3","src":"assets/audio/BX1-12/df3.mp3","sec":9.96,"t":"协助扩散：借助膜上的转运蛋白进出细胞，如葡萄糖进入红细胞，水分子更多地借助水通道蛋白进出。"},{"ep":"bx1-12","n":"BX1-12","p":7,"a":"p7","id":"df4","src":"assets/audio/BX1-12/df4.mp3","sec":7.104,"t":"解题方法：两者都顺浓度梯度、不耗能，区别在于是否需要转运蛋白。"},{"ep":"bx1-12","n":"BX1-12","p":8,"a":"p8","id":"pt1","src":"assets/audio/BX1-12/pt1.mp3","sec":5.304,"t":"考点八，转运蛋白分为载体蛋白和通道蛋白两类。"},{"ep":"bx1-12","n":"BX1-12","p":8,"a":"p8","id":"pt2","src":"assets/audio/BX1-12/pt2.mp3","sec":9.504,"t":"载体蛋白只容许与自身结合部位相适应的分子或离子通过，每次转运时都会发生自身构象的改变。"},{"ep":"bx1-12","n":"BX1-12","p":8,"a":"p8","id":"pt3","src":"assets/audio/BX1-12/pt3.mp3","sec":10.176,"t":"通道蛋白只容许大小、形状和电荷相适宜的分子或离子通过，分子或离子通过时不需要与通道蛋白结合。"},{"ep":"bx1-12","n":"BX1-12","p":8,"a":"p8","id":"pt4","src":"assets/audio/BX1-12/pt4.mp3","sec":9.792,"t":"易错：协助扩散的速率除了受浓度差影响，还受转运蛋白数量的限制，所以曲线最后会趋于平缓。"},{"ep":"bx1-12","n":"BX1-12","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-12/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-12","n":"BX1-12","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-12/rv2.mp3","sec":10.128,"t":"判断一？错，漏斗内浓度仍然更高。判断二？错，原生质层是两层膜及其间的细胞质。"},{"ep":"bx1-12","n":"BX1-12","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-12/rv3.mp3","sec":6.48,"t":"判断三？对。判断四？错，动物细胞没有细胞壁。"},{"ep":"bx1-12","n":"BX1-12","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-12/rv4.mp3","sec":7.176,"t":"判断五？错，是协助扩散。判断六？错，不需要结合。"},{"ep":"bx1-12","n":"BX1-12","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-12/rv5.mp3","sec":8.568,"t":"八个考点串成一条线：水往浓处流，被动运输顺浓度梯度、不耗能。我们下期再见！"},{"ep":"bx1-13","n":"BX1-13","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-13/in1.mp3","sec":7.968,"t":"同学们好！这节课梳理人教版必修一第四章第二节——主动运输与胞吞、胞吐。"},{"ep":"bx1-13","n":"BX1-13","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-13/in2.mp3","sec":7.848,"t":"高考常考三种跨膜运输方式的比较、影响运输速率的曲线，以及运输方式的判断。"},{"ep":"bx1-13","n":"BX1-13","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-13/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-13","n":"BX1-13","p":1,"a":"p1","id":"ac1","src":"assets/audio/BX1-13/ac1.mp3","sec":11.52,"t":"考点一，主动运输。物质逆浓度梯度进行跨膜运输，需要载体蛋白的协助，同时还要消耗细胞内化学反应释放的能量。"},{"ep":"bx1-13","n":"BX1-13","p":1,"a":"p1","id":"ac2","src":"assets/audio/BX1-13/ac2.mp3","sec":9.144,"t":"载体蛋白与离子或分子结合后，在能量的推动下空间结构发生变化，把物质转运到膜的另一侧。"},{"ep":"bx1-13","n":"BX1-13","p":1,"a":"p1","id":"ac3","src":"assets/audio/BX1-13/ac3.mp3","sec":7.368,"t":"易错：主动运输用的是载体蛋白，不是通道蛋白；能量主要来自细胞呼吸。"},{"ep":"bx1-13","n":"BX1-13","p":2,"a":"p2","id":"mn1","src":"assets/audio/BX1-13/mn1.mp3","sec":11.76,"t":"考点二，主动运输的意义。它保证细胞按照生命活动的需要，主动选择吸收所需要的营养物质，排出代谢废物和有害物质。"},{"ep":"bx1-13","n":"BX1-13","p":2,"a":"p2","id":"mn2","src":"assets/audio/BX1-13/mn2.mp3","sec":12.312,"t":"实例：小肠上皮细胞吸收葡萄糖、氨基酸；植物根细胞吸收矿质离子；轮藻细胞中K+浓度比周围水环境高63倍。"},{"ep":"bx1-13","n":"BX1-13","p":2,"a":"p2","id":"mn3","src":"assets/audio/BX1-13/mn3.mp3","sec":12.744,"t":"考法：用呼吸抑制剂处理后，某物质吸收速率下降，说明是主动运输。解题方法：受能量影响的，只有主动运输和胞吞、胞吐。"},{"ep":"bx1-13","n":"BX1-13","p":3,"a":"p3","id":"cm1","src":"assets/audio/BX1-13/cm1.mp3","sec":8.976,"t":"考点三，三种跨膜运输方式的比较。自由扩散：顺浓度梯度，不需要转运蛋白，不耗能。"},{"ep":"bx1-13","n":"BX1-13","p":3,"a":"p3","id":"cm2","src":"assets/audio/BX1-13/cm2.mp3","sec":5.136,"t":"协助扩散：顺浓度梯度，需要转运蛋白，不耗能。"},{"ep":"bx1-13","n":"BX1-13","p":3,"a":"p3","id":"cm3","src":"assets/audio/BX1-13/cm3.mp3","sec":5.232,"t":"主动运输：逆浓度梯度，需要载体蛋白，消耗能量。"},{"ep":"bx1-13","n":"BX1-13","p":3,"a":"p3","id":"cm4","src":"assets/audio/BX1-13/cm4.mp3","sec":6.72,"t":"解题方法：三问——方向如何？要不要转运蛋白？耗不耗能？"},{"ep":"bx1-13","n":"BX1-13","p":4,"a":"p4","id":"cc1","src":"assets/audio/BX1-13/cc1.mp3","sec":9.912,"t":"考点四，物质浓度对运输速率的影响。自由扩散的速率与浓度差成正比，曲线是一条过原点的直线。"},{"ep":"bx1-13","n":"BX1-13","p":4,"a":"p4","id":"cc2","src":"assets/audio/BX1-13/cc2.mp3","sec":9.024,"t":"协助扩散和主动运输的速率先随浓度增大而增大，后来受转运蛋白数量的限制，不再增加。"},{"ep":"bx1-13","n":"BX1-13","p":4,"a":"p4","id":"cc3","src":"assets/audio/BX1-13/cc3.mp3","sec":10.224,"t":"解题方法：直线是自由扩散；出现平台的，限制因素是转运蛋白的数量，主动运输还可能受能量限制。"},{"ep":"bx1-13","n":"BX1-13","p":5,"a":"p5","id":"ox1","src":"assets/audio/BX1-13/ox1.mp3","sec":10.536,"t":"考点五，O2浓度对运输速率的影响。自由扩散和协助扩散不耗能，速率与O2浓度无关，是一条水平线。"},{"ep":"bx1-13","n":"BX1-13","p":5,"a":"p5","id":"ox2","src":"assets/audio/BX1-13/ox2.mp3","sec":8.736,"t":"主动运输消耗能量：O2浓度为0时，无氧呼吸也能提供能量，所以曲线不从原点开始。"},{"ep":"bx1-13","n":"BX1-13","p":5,"a":"p5","id":"ox3","src":"assets/audio/BX1-13/ox3.mp3","sec":6.984,"t":"O2浓度增大，速率增大；最后受载体蛋白数量的限制，趋于平稳。"},{"ep":"bx1-13","n":"BX1-13","p":5,"a":"p5","id":"ox4","src":"assets/audio/BX1-13/ox4.mp3","sec":8.016,"t":"易错：哺乳动物成熟红细胞只进行无氧呼吸，它的主动运输速率与O2浓度无关。"},{"ep":"bx1-13","n":"BX1-13","p":6,"a":"p6","id":"en1","src":"assets/audio/BX1-13/en1.mp3","sec":6.888,"t":"考点六，胞吞和胞吐。大分子物质进出细胞，靠的是胞吞和胞吐。"},{"ep":"bx1-13","n":"BX1-13","p":6,"a":"p6","id":"en2","src":"assets/audio/BX1-13/en2.mp3","sec":10.968,"t":"胞吞时，大分子先与膜上的蛋白质结合，细胞膜内陷形成小囊，包围着大分子，再分离下来形成囊泡进入细胞。"},{"ep":"bx1-13","n":"BX1-13","p":6,"a":"p6","id":"en3","src":"assets/audio/BX1-13/en3.mp3","sec":8.424,"t":"胞吐时，囊泡移到细胞膜处，与细胞膜融合，把大分子排出细胞，比如分泌蛋白的分泌。"},{"ep":"bx1-13","n":"BX1-13","p":6,"a":"p6","id":"en4","src":"assets/audio/BX1-13/en4.mp3","sec":7.944,"t":"易错：胞吞、胞吐需要消耗能量，也需要膜上蛋白质的参与，依赖于膜的流动性。"},{"ep":"bx1-13","n":"BX1-13","p":7,"a":"p7","id":"jd1","src":"assets/audio/BX1-13/jd1.mp3","sec":8.208,"t":"考点七，判断物质运输方式。一看分子大小：大分子、颗粒物走胞吞、胞吐。"},{"ep":"bx1-13","n":"BX1-13","p":7,"a":"p7","id":"jd2","src":"assets/audio/BX1-13/jd2.mp3","sec":5.112,"t":"二看浓度梯度：逆浓度梯度运输的，是主动运输。"},{"ep":"bx1-13","n":"BX1-13","p":7,"a":"p7","id":"jd3","src":"assets/audio/BX1-13/jd3.mp3","sec":8.808,"t":"三看转运蛋白和能量：要蛋白不耗能是协助扩散，都需要是主动运输，都不需要是自由扩散。"},{"ep":"bx1-13","n":"BX1-13","p":7,"a":"p7","id":"jd4","src":"assets/audio/BX1-13/jd4.mp3","sec":10.416,"t":"易错：同一种物质可能有不同的运输方式，葡萄糖进入红细胞是协助扩散，进入小肠上皮细胞是主动运输。"},{"ep":"bx1-13","n":"BX1-13","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-13/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-13","n":"BX1-13","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-13/rv2.mp3","sec":6.6,"t":"判断一？错，主动运输用载体蛋白。判断二？对。"},{"ep":"bx1-13","n":"BX1-13","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-13/rv3.mp3","sec":7.968,"t":"判断三？错，与浓度差成正比。判断四？错，无氧呼吸也能供能。"},{"ep":"bx1-13","n":"BX1-13","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-13/rv4.mp3","sec":6.84,"t":"判断五？错，胞吞、胞吐消耗能量。判断六？对。"},{"ep":"bx1-13","n":"BX1-13","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-13/rv5.mp3","sec":7.656,"t":"七个考点串成一条线：方向、蛋白、能量，三问定方式。我们下期再见！"},{"ep":"bx1-14","n":"BX1-14","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-14/in1.mp3","sec":7.896,"t":"同学们好！这节课梳理人教版必修一第五章第一节的上半部分——酶的作用和本质。"},{"ep":"bx1-14","n":"BX1-14","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-14/in2.mp3","sec":6.792,"t":"高考常考比较过氧化氢分解的实验、变量的判断，以及活化能示意图。"},{"ep":"bx1-14","n":"BX1-14","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-14/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-14","n":"BX1-14","p":1,"a":"p1","id":"mb1","src":"assets/audio/BX1-14/mb1.mp3","sec":8.376,"t":"考点一，细胞代谢。细胞中每时每刻都进行着许多化学反应，统称为细胞代谢。"},{"ep":"bx1-14","n":"BX1-14","p":1,"a":"p1","id":"mb2","src":"assets/audio/BX1-14/mb2.mp3","sec":7.512,"t":"细胞代谢离不开酶的催化，酶使细胞代谢能在温和条件下快速有序地进行。"},{"ep":"bx1-14","n":"BX1-14","p":1,"a":"p1","id":"mb3","src":"assets/audio/BX1-14/mb3.mp3","sec":8.712,"t":"易错：细胞代谢的主要场所是细胞质基质，细胞代谢的控制中心是细胞核，两者别混。"},{"ep":"bx1-14","n":"BX1-14","p":2,"a":"p2","id":"hp1","src":"assets/audio/BX1-14/hp1.mp3","sec":16.32,"t":"考点二，比较过氧化氢在不同条件下的分解。四支试管各加2 mL H2O2溶液：1号常温，2号90℃水浴，3号滴加FeCl3溶液，4号滴加肝脏研磨液。"},{"ep":"bx1-14","n":"BX1-14","p":2,"a":"p2","id":"hp2","src":"assets/audio/BX1-14/hp2.mp3","sec":10.896,"t":"结果：4号产生气泡最多、最快，带火星的卫生香复燃最猛烈；3号次之，2号也有气泡，1号几乎没有。"},{"ep":"bx1-14","n":"BX1-14","p":2,"a":"p2","id":"hp3","src":"assets/audio/BX1-14/hp3.mp3","sec":8.04,"t":"说明加热、Fe3+和过氧化氢酶都能加快H2O2分解，而酶的催化效率更高。"},{"ep":"bx1-14","n":"BX1-14","p":2,"a":"p2","id":"hp4","src":"assets/audio/BX1-14/hp4.mp3","sec":9.84,"t":"易错：肝脏要新鲜，久置的肝脏中过氧化氢酶会因微生物作用而被破坏；研磨是为了让酶充分释放。"},{"ep":"bx1-14","n":"BX1-14","p":3,"a":"p3","id":"vb1","src":"assets/audio/BX1-14/vb1.mp3","sec":9.096,"t":"考点三，变量与对照实验。实验中人为改变的变量叫自变量，比如温度、催化剂的种类。"},{"ep":"bx1-14","n":"BX1-14","p":3,"a":"p3","id":"vb2","src":"assets/audio/BX1-14/vb2.mp3","sec":9.816,"t":"随自变量变化而变化的叫因变量，比如H2O2的分解速率，用气泡多少、卫生香复燃程度来检测。"},{"ep":"bx1-14","n":"BX1-14","p":3,"a":"p3","id":"vb3","src":"assets/audio/BX1-14/vb3.mp3","sec":9.312,"t":"其他对实验结果有影响的可变因素叫无关变量，比如H2O2的浓度和用量，各组要相同且适宜。"},{"ep":"bx1-14","n":"BX1-14","p":3,"a":"p3","id":"vb4","src":"assets/audio/BX1-14/vb4.mp3","sec":7.632,"t":"除自变量外，其他因素都保持不变的实验叫对照实验，包括对照组和实验组。"},{"ep":"bx1-14","n":"BX1-14","p":3,"a":"p3","id":"vb5","src":"assets/audio/BX1-14/vb5.mp3","sec":9.24,"t":"解题方法：看题目“探究甲对乙的影响”——甲是自变量，乙是因变量；本实验的1号试管是对照组。"},{"ep":"bx1-14","n":"BX1-14","p":4,"a":"p4","id":"av1","src":"assets/audio/BX1-14/av1.mp3","sec":9.912,"t":"考点四，酶的作用原理。分子从常态转变为容易发生化学反应的活跃状态所需要的能量，叫活化能。"},{"ep":"bx1-14","n":"BX1-14","p":4,"a":"p4","id":"av2","src":"assets/audio/BX1-14/av2.mp3","sec":7.224,"t":"加热是为反应提供能量；而酶和无机催化剂都是降低化学反应的活化能。"},{"ep":"bx1-14","n":"BX1-14","p":4,"a":"p4","id":"av3","src":"assets/audio/BX1-14/av3.mp3","sec":7.056,"t":"同无机催化剂相比，酶降低活化能的作用更显著，所以催化效率更高。"},{"ep":"bx1-14","n":"BX1-14","p":4,"a":"p4","id":"av4","src":"assets/audio/BX1-14/av4.mp3","sec":7.104,"t":"易错：酶不为反应提供能量，也不改变反应的平衡点，只是加快反应速率。"},{"ep":"bx1-14","n":"BX1-14","p":5,"a":"p5","id":"dg1","src":"assets/audio/BX1-14/dg1.mp3","sec":9.216,"t":"考点五，活化能示意图。纵轴是能量，曲线最高点与反应物所处能量之差，就是活化能。"},{"ep":"bx1-14","n":"BX1-14","p":5,"a":"p5","id":"dg2","src":"assets/audio/BX1-14/dg2.mp3","sec":6.912,"t":"没有催化剂时活化能最大；无机催化剂降低一部分；酶降低得更多。"},{"ep":"bx1-14","n":"BX1-14","p":5,"a":"p5","id":"dg3","src":"assets/audio/BX1-14/dg3.mp3","sec":10.008,"t":"解题方法：酶降低的活化能 = 无催化剂时的活化能 − 有酶时的活化能，也就是两条曲线最高点之差。"},{"ep":"bx1-14","n":"BX1-14","p":6,"a":"p6","id":"hs1","src":"assets/audio/BX1-14/hs1.mp3","sec":14.976,"t":"考点六，关于酶本质的探索。巴斯德认为发酵与活细胞有关；李比希认为引起发酵的是酵母菌细胞中的某些物质，但只有在细胞死亡并裂解后才能发挥作用。"},{"ep":"bx1-14","n":"BX1-14","p":6,"a":"p6","id":"hs2","src":"assets/audio/BX1-14/hs2.mp3","sec":10.416,"t":"毕希纳把酵母菌细胞研磨、过滤得到提取液，提取液也能使糖液变成酒，他把其中引起发酵的物质称为酿酶。"},{"ep":"bx1-14","n":"BX1-14","p":6,"a":"p6","id":"hs3","src":"assets/audio/BX1-14/hs3.mp3","sec":6.36,"t":"萨姆纳从刀豆种子中提取到脲酶结晶，并证明脲酶是蛋白质。"},{"ep":"bx1-14","n":"BX1-14","p":6,"a":"p6","id":"hs4","src":"assets/audio/BX1-14/hs4.mp3","sec":7.368,"t":"20世纪80年代，切赫和奥尔特曼发现少数RNA也具有生物催化功能。"},{"ep":"bx1-14","n":"BX1-14","p":6,"a":"p6","id":"hs5","src":"assets/audio/BX1-14/hs5.mp3","sec":11.568,"t":"考法：判断各位科学家的结论。易错：毕希纳证明了酿酶离开活细胞也能起作用，证明酶是蛋白质的是萨姆纳。"},{"ep":"bx1-14","n":"BX1-14","p":7,"a":"p7","id":"cn1","src":"assets/audio/BX1-14/cn1.mp3","sec":10.68,"t":"考点七，酶的概念。酶是活细胞产生的、具有催化作用的有机物，其中绝大多数是蛋白质，少数是RNA。"},{"ep":"bx1-14","n":"BX1-14","p":7,"a":"p7","id":"cn2","src":"assets/audio/BX1-14/cn2.mp3","sec":4.728,"t":"所以酶的基本单位是氨基酸或核糖核苷酸。"},{"ep":"bx1-14","n":"BX1-14","p":7,"a":"p7","id":"cn3","src":"assets/audio/BX1-14/cn3.mp3","sec":9.84,"t":"易错：酶在细胞内外都能起作用，比如消化酶在消化道中起作用；酶只有催化作用，没有调节作用。"},{"ep":"bx1-14","n":"BX1-14","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-14/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-14","n":"BX1-14","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-14/rv2.mp3","sec":7.992,"t":"判断一？错，酶是降低活化能。判断二？错，加热是提供能量。"},{"ep":"bx1-14","n":"BX1-14","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-14/rv3.mp3","sec":4.656,"t":"判断三？对。判断四？对。"},{"ep":"bx1-14","n":"BX1-14","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-14/rv4.mp3","sec":9.12,"t":"判断五？错，酶在细胞内外都能起作用。判断六？错，少数酶是RNA。"},{"ep":"bx1-14","n":"BX1-14","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-14/rv5.mp3","sec":6.72,"t":"七个考点串成一条线：酶不供能，只降低活化能。我们下期再见！"},{"ep":"bx1-15","n":"BX1-15","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-15/in1.mp3","sec":7.344,"t":"同学们好！这节课梳理人教版必修一第五章第一节的下半部分——酶的特性。"},{"ep":"bx1-15","n":"BX1-15","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-15/in2.mp3","sec":8.736,"t":"高考常考酶特性的实验设计、温度和pH的影响曲线，以及实验材料和检测试剂的选择。"},{"ep":"bx1-15","n":"BX1-15","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-15/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-15","n":"BX1-15","p":1,"a":"p1","id":"ef1","src":"assets/audio/BX1-15/ef1.mp3","sec":8.424,"t":"考点一，高效性。酶的催化效率大约是无机催化剂的107～1013倍。"},{"ep":"bx1-15","n":"BX1-15","p":1,"a":"p1","id":"ef2","src":"assets/audio/BX1-15/ef2.mp3","sec":7.392,"t":"证明高效性，要用酶和无机催化剂作对照，比如过氧化氢酶和FeCl3。"},{"ep":"bx1-15","n":"BX1-15","p":1,"a":"p1","id":"ef3","src":"assets/audio/BX1-15/ef3.mp3","sec":8.928,"t":"易错：酶与无机催化剂比较才体现高效性；酶与不加催化剂比较，只能说明酶有催化作用。"},{"ep":"bx1-15","n":"BX1-15","p":2,"a":"p2","id":"sp1","src":"assets/audio/BX1-15/sp1.mp3","sec":6.312,"t":"考点二，专一性。每一种酶只能催化一种或一类化学反应。"},{"ep":"bx1-15","n":"BX1-15","p":2,"a":"p2","id":"sp2","src":"assets/audio/BX1-15/sp2.mp3","sec":10.128,"t":"实验：用淀粉酶分别作用于淀粉和蔗糖，再用斐林试剂检测——淀粉组出现砖红色沉淀，蔗糖组没有。"},{"ep":"bx1-15","n":"BX1-15","p":2,"a":"p2","id":"sp3","src":"assets/audio/BX1-15/sp3.mp3","sec":7.176,"t":"易错：这个实验不能用碘液检测，因为碘液无法检测蔗糖是否被水解。"},{"ep":"bx1-15","n":"BX1-15","p":2,"a":"p2","id":"sp4","src":"assets/audio/BX1-15/sp4.mp3","sec":7.776,"t":"解题方法：验证专一性，可以同一种酶、不同底物，也可以同一种底物、不同的酶。"},{"ep":"bx1-15","n":"BX1-15","p":3,"a":"p3","id":"md1","src":"assets/audio/BX1-15/md1.mp3","sec":9.744,"t":"考点三，酶的作用条件较温和。酶需要适宜的温度和pH，在最适温度和最适pH下活性最高。"},{"ep":"bx1-15","n":"BX1-15","p":3,"a":"p3","id":"md2","src":"assets/audio/BX1-15/md2.mp3","sec":7.152,"t":"过酸、过碱或温度过高，会使酶的空间结构遭到破坏，使酶永久失活。"},{"ep":"bx1-15","n":"BX1-15","p":3,"a":"p3","id":"md3","src":"assets/audio/BX1-15/md3.mp3","sec":7.008,"t":"低温只是抑制酶的活性，酶的空间结构稳定，温度适宜时活性可以恢复。"},{"ep":"bx1-15","n":"BX1-15","p":3,"a":"p3","id":"md4","src":"assets/audio/BX1-15/md4.mp3","sec":6.744,"t":"考法：酶适宜在低温下保存。易错：低温不会使酶变性失活。"},{"ep":"bx1-15","n":"BX1-15","p":4,"a":"p4","id":"tm1","src":"assets/audio/BX1-15/tm1.mp3","sec":10.776,"t":"考点四，温度对酶活性的影响。在一定范围内，随温度升高，酶活性增强；超过最适温度后，酶活性降低。"},{"ep":"bx1-15","n":"BX1-15","p":4,"a":"p4","id":"tm2","src":"assets/audio/BX1-15/tm2.mp3","sec":7.488,"t":"低温时酶活性很低，但没有失活；温度过高，酶会变性失活，曲线降到零。"},{"ep":"bx1-15","n":"BX1-15","p":4,"a":"p4","id":"tm3","src":"assets/audio/BX1-15/tm3.mp3","sec":11.952,"t":"解题方法：同一活性对应两个温度时，高温一侧的酶已部分失活，降回最适温度，活性也不能恢复到最高；低温一侧可以恢复。"},{"ep":"bx1-15","n":"BX1-15","p":5,"a":"p5","id":"ph1","src":"assets/audio/BX1-15/ph1.mp3","sec":9.528,"t":"考点五，pH对酶活性的影响。每种酶都有最适pH，偏离最适pH，酶活性都会降低。"},{"ep":"bx1-15","n":"BX1-15","p":5,"a":"p5","id":"ph2","src":"assets/audio/BX1-15/ph2.mp3","sec":6.144,"t":"过酸、过碱都会使酶变性失活，所以曲线两端都降到零。"},{"ep":"bx1-15","n":"BX1-15","p":5,"a":"p5","id":"ph3","src":"assets/audio/BX1-15/ph3.mp3","sec":11.016,"t":"不同的酶最适pH不同：胃蛋白酶的最适pH约为1.5，动物体内的酶最适pH大多在6.5～8.0之间。"},{"ep":"bx1-15","n":"BX1-15","p":5,"a":"p5","id":"ph4","src":"assets/audio/BX1-15/ph4.mp3","sec":8.664,"t":"易错：pH从过碱调回最适，酶活性不能恢复；改变温度不影响酶的最适pH。"},{"ep":"bx1-15","n":"BX1-15","p":6,"a":"p6","id":"te1","src":"assets/audio/BX1-15/te1.mp3","sec":8.448,"t":"考点六，探究温度对酶活性的影响。常用淀粉和淀粉酶，用碘液检测淀粉的剩余量。"},{"ep":"bx1-15","n":"BX1-15","p":6,"a":"p6","id":"te2","src":"assets/audio/BX1-15/te2.mp3","sec":8.496,"t":"要先把酶和底物分别保温到相应温度，再混合，保证反应一开始就在设定的温度下进行。"},{"ep":"bx1-15","n":"BX1-15","p":6,"a":"p6","id":"te3","src":"assets/audio/BX1-15/te3.mp3","sec":11.112,"t":"易错：不能用斐林试剂检测，因为它要水浴加热，会改变温度；也不能用过氧化氢酶，因为H2O2受热本身会分解。"},{"ep":"bx1-15","n":"BX1-15","p":7,"a":"p7","id":"pe1","src":"assets/audio/BX1-15/pe1.mp3","sec":9.768,"t":"考点七，探究pH对酶活性的影响。常用过氧化氢和过氧化氢酶，观察气泡产生的多少。"},{"ep":"bx1-15","n":"BX1-15","p":7,"a":"p7","id":"pe2","src":"assets/audio/BX1-15/pe2.mp3","sec":4.92,"t":"要先用不同pH的缓冲液处理酶，再与底物混合。"},{"ep":"bx1-15","n":"BX1-15","p":7,"a":"p7","id":"pe3","src":"assets/audio/BX1-15/pe3.mp3","sec":8.184,"t":"易错：一般不用淀粉和淀粉酶，因为淀粉在酸性条件下也会水解，干扰实验结果。"},{"ep":"bx1-15","n":"BX1-15","p":8,"a":"p8","id":"sb1","src":"assets/audio/BX1-15/sb1.mp3","sec":10.464,"t":"考点八，底物浓度和酶浓度的影响。底物浓度增大，反应速率先增大，后来受酶浓度限制，不再增加。"},{"ep":"bx1-15","n":"BX1-15","p":8,"a":"p8","id":"sb2","src":"assets/audio/BX1-15/sb2.mp3","sec":8.088,"t":"在底物充足时，反应速率与酶浓度成正比；酶浓度提高，曲线的平台也随之升高。"},{"ep":"bx1-15","n":"BX1-15","p":8,"a":"p8","id":"sb3","src":"assets/audio/BX1-15/sb3.mp3","sec":10.656,"t":"解题方法：曲线拐点之前，限制因素是横坐标表示的因素；拐点之后，限制因素是其他因素，比如酶的数量。"},{"ep":"bx1-15","n":"BX1-15","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-15/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-15","n":"BX1-15","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-15/rv2.mp3","sec":9.264,"t":"判断一？错，要和无机催化剂对照。判断二？错，碘液检测不了蔗糖是否水解。"},{"ep":"bx1-15","n":"BX1-15","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-15/rv3.mp3","sec":8.352,"t":"判断三？错，低温只是抑制。判断四？错，H2O2受热会分解。"},{"ep":"bx1-15","n":"BX1-15","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-15/rv4.mp3","sec":4.68,"t":"判断五？对。判断六？对。"},{"ep":"bx1-15","n":"BX1-15","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-15/rv5.mp3","sec":8.616,"t":"八个考点串成一条线：高温、过酸、过碱使酶失活，低温只是抑制。我们下期再见！"},{"ep":"bx1-16","n":"BX1-16","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-16/in1.mp3","sec":7.896,"t":"同学们好！这节课梳理人教版必修一第五章第二节——细胞的能量“货币”ATP。"},{"ep":"bx1-16","n":"BX1-16","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-16/in2.mp3","sec":7.8,"t":"高考常考ATP的结构、ATP与ADP的相互转化，以及吸能反应和放能反应。"},{"ep":"bx1-16","n":"BX1-16","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-16/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-16","n":"BX1-16","p":1,"a":"p1","id":"st1","src":"assets/audio/BX1-16/st1.mp3","sec":9.984,"t":"考点一，ATP的结构。ATP是腺苷三磷酸的英文名称缩写，结构简式是A—P~P~P。"},{"ep":"bx1-16","n":"BX1-16","p":1,"a":"p1","id":"st2","src":"assets/audio/BX1-16/st2.mp3","sec":6.432,"t":"其中A代表腺苷，由腺嘌呤和核糖组成；P代表磷酸基团。"},{"ep":"bx1-16","n":"BX1-16","p":1,"a":"p1","id":"st3","src":"assets/audio/BX1-16/st3.mp3","sec":4.968,"t":"ATP由C、H、O、N、P五种元素组成。"},{"ep":"bx1-16","n":"BX1-16","p":1,"a":"p1","id":"st4","src":"assets/audio/BX1-16/st4.mp3","sec":8.088,"t":"易错：ATP中的“A”是腺苷，而DNA和RNA中的“A”是腺嘌呤，两者不同。"},{"ep":"bx1-16","n":"BX1-16","p":2,"a":"p2","id":"bd1","src":"assets/audio/BX1-16/bd1.mp3","sec":11.976,"t":"考点二，特殊的化学键。ATP中相邻磷酸基团之间的化学键是一种特殊的化学键，用“~”表示，一个ATP中有2个。"},{"ep":"bx1-16","n":"BX1-16","p":2,"a":"p2","id":"bd2","src":"assets/audio/BX1-16/bd2.mp3","sec":8.856,"t":"磷酸基团都带负电荷而相互排斥，使这种化学键不稳定，末端磷酸基团有较高的转移势能。"},{"ep":"bx1-16","n":"BX1-16","p":2,"a":"p2","id":"bd3","src":"assets/audio/BX1-16/bd3.mp3","sec":6.144,"t":"ATP水解时，远离A的那个特殊化学键容易断裂，释放能量。"},{"ep":"bx1-16","n":"BX1-16","p":2,"a":"p2","id":"bd4","src":"assets/audio/BX1-16/bd4.mp3","sec":8.688,"t":"易错：一个ATP有2个特殊化学键、3个磷酸基团；水解时一般只断裂末端那一个。"},{"ep":"bx1-16","n":"BX1-16","p":3,"a":"p3","id":"cv1","src":"assets/audio/BX1-16/cv1.mp3","sec":12.528,"t":"考点三，ATP与ADP的相互转化。ATP在酶的作用下水解，远离A的特殊化学键断裂，形成ADP和Pi，释放能量。"},{"ep":"bx1-16","n":"BX1-16","p":3,"a":"p3","id":"cv2","src":"assets/audio/BX1-16/cv2.mp3","sec":6.624,"t":"ADP在酶的作用下接受能量，与Pi结合，重新形成ATP。"},{"ep":"bx1-16","n":"BX1-16","p":3,"a":"p3","id":"cv3","src":"assets/audio/BX1-16/cv3.mp3","sec":5.136,"t":"这种转化时刻不停地发生，并且处于动态平衡之中。"},{"ep":"bx1-16","n":"BX1-16","p":3,"a":"p3","id":"cv4","src":"assets/audio/BX1-16/cv4.mp3","sec":7.488,"t":"易错：这种转化不是可逆反应，因为两个方向的酶不同、能量来源和去路不同。"},{"ep":"bx1-16","n":"BX1-16","p":4,"a":"p4","id":"sr1","src":"assets/audio/BX1-16/sr1.mp3","sec":9.912,"t":"考点四，合成ATP的能量来源。对于动物、人、真菌和大多数细菌来说，能量来自细胞呼吸。"},{"ep":"bx1-16","n":"BX1-16","p":4,"a":"p4","id":"sr2","src":"assets/audio/BX1-16/sr2.mp3","sec":5.328,"t":"对于绿色植物来说，能量来自细胞呼吸和光合作用。"},{"ep":"bx1-16","n":"BX1-16","p":4,"a":"p4","id":"sr3","src":"assets/audio/BX1-16/sr3.mp3","sec":8.28,"t":"所以合成ATP的场所：动物细胞是细胞质基质和线粒体；植物细胞还有叶绿体。"},{"ep":"bx1-16","n":"BX1-16","p":4,"a":"p4","id":"sr4","src":"assets/audio/BX1-16/sr4.mp3","sec":8.04,"t":"易错：叶绿体光反应产生的ATP，主要用于暗反应，一般不用于细胞的其他生命活动。"},{"ep":"bx1-16","n":"BX1-16","p":5,"a":"p5","id":"rx1","src":"assets/audio/BX1-16/rx1.mp3","sec":10.536,"t":"考点五，ATP的利用。许多吸能反应与ATP水解相联系，比如蛋白质的合成、主动运输、肌肉收缩。"},{"ep":"bx1-16","n":"BX1-16","p":5,"a":"p5","id":"rx2","src":"assets/audio/BX1-16/rx2.mp3","sec":8.928,"t":"许多放能反应与ATP的合成相联系，释放的能量储存在ATP中，比如葡萄糖的氧化分解。"},{"ep":"bx1-16","n":"BX1-16","p":5,"a":"p5","id":"rx3","src":"assets/audio/BX1-16/rx3.mp3","sec":9.048,"t":"能量通过ATP分子在吸能反应和放能反应之间流通，所以ATP被称为细胞的能量“货币”。"},{"ep":"bx1-16","n":"BX1-16","p":5,"a":"p5","id":"rx4","src":"assets/audio/BX1-16/rx4.mp3","sec":8.496,"t":"解题方法：看反应耗能还是放能——耗能的伴随ATP水解，放能的伴随ATP合成。"},{"ep":"bx1-16","n":"BX1-16","p":6,"a":"p6","id":"tp1","src":"assets/audio/BX1-16/tp1.mp3","sec":8.136,"t":"考点六，易错辨析。ATP在细胞中含量很少，但与ADP的转化非常迅速。"},{"ep":"bx1-16","n":"BX1-16","p":6,"a":"p6","id":"tp2","src":"assets/audio/BX1-16/tp2.mp3","sec":8.28,"t":"ATP脱去两个磷酸基团后，就是腺嘌呤核糖核苷酸，是组成RNA的基本单位之一。"},{"ep":"bx1-16","n":"BX1-16","p":6,"a":"p6","id":"tp3","src":"assets/audio/BX1-16/tp3.mp3","sec":8.736,"t":"安静和运动时，细胞中ATP的含量都相对稳定，变化的是ATP与ADP的转化速率。"},{"ep":"bx1-16","n":"BX1-16","p":6,"a":"p6","id":"tp4","src":"assets/audio/BX1-16/tp4.mp3","sec":7.368,"t":"解题方法：看到“ATP含量大量增加”“ATP大量储存”这类说法，一般是错的。"},{"ep":"bx1-16","n":"BX1-16","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-16/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-16","n":"BX1-16","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-16/rv2.mp3","sec":6.864,"t":"判断一？错，A代表腺苷。判断二？错，只有2个。"},{"ep":"bx1-16","n":"BX1-16","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-16/rv3.mp3","sec":6.0,"t":"判断三？错，不是可逆反应。判断四？对。"},{"ep":"bx1-16","n":"BX1-16","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-16/rv4.mp3","sec":6.696,"t":"判断五？错，ATP含量相对稳定。判断六？对。"},{"ep":"bx1-16","n":"BX1-16","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-16/rv5.mp3","sec":9.168,"t":"六个考点串成一条线：ATP含量少、转化快，连接吸能反应和放能反应。我们下期再见！"},{"ep":"bx1-17","n":"BX1-17","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-17/in1.mp3","sec":10.008,"t":"同学们好！这节课梳理人教版必修一第五章第三节的上半部分——探究酵母菌细胞呼吸的方式和有氧呼吸。"},{"ep":"bx1-17","n":"BX1-17","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-17/in2.mp3","sec":7.296,"t":"高考常考实验装置和产物检测，以及有氧呼吸三个阶段的场所和物质变化。"},{"ep":"bx1-17","n":"BX1-17","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-17/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-17","n":"BX1-17","p":1,"a":"p1","id":"dv1","src":"assets/audio/BX1-17/dv1.mp3","sec":9.312,"t":"考点一，探究酵母菌细胞呼吸的方式。酵母菌是兼性厌氧菌，有氧和无氧条件下都能生存。"},{"ep":"bx1-17","n":"BX1-17","p":1,"a":"p1","id":"dv2","src":"assets/audio/BX1-17/dv2.mp3","sec":10.68,"t":"有氧装置：空气先通过质量分数为10%的NaOH溶液，再通入酵母菌培养液，最后连接澄清石灰水。"},{"ep":"bx1-17","n":"BX1-17","p":1,"a":"p1","id":"dv3","src":"assets/audio/BX1-17/dv3.mp3","sec":9.768,"t":"无氧装置：酵母菌培养液封口放置一段时间后，再连通澄清石灰水，目的是消耗掉瓶中原有的O2。"},{"ep":"bx1-17","n":"BX1-17","p":1,"a":"p1","id":"dv4","src":"assets/audio/BX1-17/dv4.mp3","sec":12.216,"t":"解题方法：NaOH的作用是吸收空气中的CO2，排除干扰；无氧组先放置，保证进入石灰水的CO2都来自无氧呼吸。"},{"ep":"bx1-17","n":"BX1-17","p":2,"a":"p2","id":"dt1","src":"assets/audio/BX1-17/dt1.mp3","sec":10.368,"t":"考点二，产物的检测。CO2使澄清石灰水变浑浊，也可使溴麝香草酚蓝溶液由蓝变绿再变黄。"},{"ep":"bx1-17","n":"BX1-17","p":2,"a":"p2","id":"dt2","src":"assets/audio/BX1-17/dt2.mp3","sec":9.312,"t":"根据石灰水的浑浊程度，或者溴麝香草酚蓝溶液变黄所需的时间，可以判断CO2产生的多少。"},{"ep":"bx1-17","n":"BX1-17","p":2,"a":"p2","id":"dt3","src":"assets/audio/BX1-17/dt3.mp3","sec":6.264,"t":"酒精在酸性条件下，与橙色的重铬酸钾溶液反应，变成灰绿色。"},{"ep":"bx1-17","n":"BX1-17","p":2,"a":"p2","id":"dt4","src":"assets/audio/BX1-17/dt4.mp3","sec":9.528,"t":"易错：葡萄糖也能与酸性重铬酸钾反应，所以要适当延长培养时间，耗尽葡萄糖后再检测酒精。"},{"ep":"bx1-17","n":"BX1-17","p":3,"a":"p3","id":"ct1","src":"assets/audio/BX1-17/ct1.mp3","sec":11.088,"t":"考点三，科学方法——对比实验。设置两个或两个以上的实验组，通过比较结果，探究某种因素对实验对象的影响。"},{"ep":"bx1-17","n":"BX1-17","p":3,"a":"p3","id":"ct2","src":"assets/audio/BX1-17/ct2.mp3","sec":5.328,"t":"本实验中，有氧组和无氧组都是实验组，相互对比。"},{"ep":"bx1-17","n":"BX1-17","p":3,"a":"p3","id":"ct3","src":"assets/audio/BX1-17/ct3.mp3","sec":8.544,"t":"易错：对比实验没有单独的空白对照组；鲁宾和卡门的同位素标记实验，也是对比实验。"},{"ep":"bx1-17","n":"BX1-17","p":4,"a":"p4","id":"tt1","src":"assets/audio/BX1-17/tt1.mp3","sec":12.936,"t":"考点四，有氧呼吸。细胞在O2的参与下，把葡萄糖等有机物彻底氧化分解，产生CO2和水，释放能量，生成大量ATP。"},{"ep":"bx1-17","n":"BX1-17","p":4,"a":"p4","id":"tt2","src":"assets/audio/BX1-17/tt2.mp3","sec":11.184,"t":"总反应式：葡萄糖、水和O2，在酶的作用下，生成CO2、水和能量。"},{"ep":"bx1-17","n":"BX1-17","p":4,"a":"p4","id":"tt3","src":"assets/audio/BX1-17/tt3.mp3","sec":11.88,"t":"1 mol葡萄糖彻底氧化分解，释放2870 kJ能量，约977.28 kJ储存在ATP中，其余以热能形式散失。"},{"ep":"bx1-17","n":"BX1-17","p":4,"a":"p4","id":"tt4","src":"assets/audio/BX1-17/tt4.mp3","sec":8.112,"t":"解题方法：写反应式时两边都有水，箭头上注明“酶”，最后写“能量”而不是ATP。"},{"ep":"bx1-17","n":"BX1-17","p":5,"a":"p5","id":"sg1","src":"assets/audio/BX1-17/sg1.mp3","sec":12.648,"t":"考点五，有氧呼吸的三个阶段。第一阶段在细胞质基质：1分子葡萄糖分解成2分子丙酮酸，产生少量[H]，释放少量能量。"},{"ep":"bx1-17","n":"BX1-17","p":5,"a":"p5","id":"sg2","src":"assets/audio/BX1-17/sg2.mp3","sec":8.4,"t":"第二阶段在线粒体基质：丙酮酸和水彻底分解成CO2和[H]，释放少量能量。"},{"ep":"bx1-17","n":"BX1-17","p":5,"a":"p5","id":"sg3","src":"assets/audio/BX1-17/sg3.mp3","sec":8.616,"t":"第三阶段在线粒体内膜：前两个阶段产生的[H]与O2结合生成水，释放大量能量。"},{"ep":"bx1-17","n":"BX1-17","p":5,"a":"p5","id":"sg4","src":"assets/audio/BX1-17/sg4.mp3","sec":9.768,"t":"解题方法：水在第二阶段消耗、第三阶段生成；O2只在第三阶段参与；CO2在第二阶段产生。"},{"ep":"bx1-17","n":"BX1-17","p":6,"a":"p6","id":"en1","src":"assets/audio/BX1-17/en1.mp3","sec":7.896,"t":"考点六，能量与元素去向。三个阶段都能产生ATP，第三阶段产生的最多。"},{"ep":"bx1-17","n":"BX1-17","p":6,"a":"p6","id":"en2","src":"assets/audio/BX1-17/en2.mp3","sec":10.584,"t":"用18O追踪：葡萄糖中的O进入CO2；O2中的O进入生成的水；反应物水中的O也进入CO2。"},{"ep":"bx1-17","n":"BX1-17","p":6,"a":"p6","id":"en3","src":"assets/audio/BX1-17/en3.mp3","sec":5.592,"t":"解题方法：追踪元素时记住，O2中的氧只进入水。"},{"ep":"bx1-17","n":"BX1-17","p":7,"a":"p7","id":"tp1","src":"assets/audio/BX1-17/tp1.mp3","sec":9.84,"t":"考点七，易错辨析。线粒体不能直接分解葡萄糖，葡萄糖要先在细胞质基质中分解为丙酮酸。"},{"ep":"bx1-17","n":"BX1-17","p":7,"a":"p7","id":"tp2","src":"assets/audio/BX1-17/tp2.mp3","sec":9.648,"t":"原核生物没有线粒体，但有的也能进行有氧呼吸，比如醋酸菌、蓝细菌，它们含有与有氧呼吸有关的酶。"},{"ep":"bx1-17","n":"BX1-17","p":7,"a":"p7","id":"tp3","src":"assets/audio/BX1-17/tp3.mp3","sec":8.184,"t":"真核细胞也不一定都能有氧呼吸：哺乳动物成熟红细胞没有线粒体，只进行无氧呼吸。"},{"ep":"bx1-17","n":"BX1-17","p":7,"a":"p7","id":"tp4","src":"assets/audio/BX1-17/tp4.mp3","sec":8.664,"t":"解题方法：判断能否进行有氧呼吸，看有没有与有氧呼吸有关的酶，不能只看有没有线粒体。"},{"ep":"bx1-17","n":"BX1-17","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-17/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-17","n":"BX1-17","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-17/rv2.mp3","sec":7.344,"t":"判断一？错，吸收的是空气中的CO2。判断二？对。"},{"ep":"bx1-17","n":"BX1-17","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-17/rv3.mp3","sec":8.28,"t":"判断三？错，水在第二阶段参与。判断四？错，O2中的氧进入水。"},{"ep":"bx1-17","n":"BX1-17","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-17/rv4.mp3","sec":6.936,"t":"判断五？错，进入线粒体的是丙酮酸。判断六？对。"},{"ep":"bx1-17","n":"BX1-17","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-17/rv5.mp3","sec":7.536,"t":"七个考点串成一条线：水二耗三生，O2只在第三阶段。我们下期再见！"},{"ep":"bx1-18","n":"BX1-18","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-18/in1.mp3","sec":9.672,"t":"同学们好！这节课梳理人教版必修一第五章第三节的下半部分——无氧呼吸和细胞呼吸原理的应用。"},{"ep":"bx1-18","n":"BX1-18","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-18/in2.mp3","sec":8.016,"t":"高考常考根据气体变化判断呼吸方式、相关计算，以及影响因素和生产应用。"},{"ep":"bx1-18","n":"BX1-18","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-18/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-18","n":"BX1-18","p":1,"a":"p1","id":"pr1","src":"assets/audio/BX1-18/pr1.mp3","sec":6.72,"t":"考点一，无氧呼吸。无氧呼吸的两个阶段都在细胞质基质中进行。"},{"ep":"bx1-18","n":"BX1-18","p":1,"a":"p1","id":"pr2","src":"assets/audio/BX1-18/pr2.mp3","sec":9.528,"t":"第一阶段与有氧呼吸的第一阶段完全相同：葡萄糖分解为丙酮酸和少量[H]，释放少量能量。"},{"ep":"bx1-18","n":"BX1-18","p":1,"a":"p1","id":"pr3","src":"assets/audio/BX1-18/pr3.mp3","sec":10.08,"t":"第二阶段：丙酮酸在不同酶的催化下，分解成酒精和CO2，或者转化成乳酸；这一阶段不释放能量。"},{"ep":"bx1-18","n":"BX1-18","p":1,"a":"p1","id":"pr4","src":"assets/audio/BX1-18/pr4.mp3","sec":8.328,"t":"易错：无氧呼吸只在第一阶段释放少量能量，大部分能量还储存在酒精或乳酸中。"},{"ep":"bx1-18","n":"BX1-18","p":2,"a":"p2","id":"fm1","src":"assets/audio/BX1-18/fm1.mp3","sec":10.728,"t":"考点二，两种无氧呼吸。产生酒精的无氧呼吸：葡萄糖分解为酒精和CO2，如酵母菌、多数植物细胞。"},{"ep":"bx1-18","n":"BX1-18","p":2,"a":"p2","id":"fm2","src":"assets/audio/BX1-18/fm2.mp3","sec":11.328,"t":"产生乳酸的无氧呼吸：葡萄糖分解为乳酸，如乳酸菌、人和动物的骨骼肌细胞，以及马铃薯块茎、甜菜块根、玉米胚。"},{"ep":"bx1-18","n":"BX1-18","p":2,"a":"p2","id":"fm3","src":"assets/audio/BX1-18/fm3.mp3","sec":8.232,"t":"无氧呼吸释放的能量少，1 mol葡萄糖只有约61.08 kJ的能量储存在ATP中。"},{"ep":"bx1-18","n":"BX1-18","p":2,"a":"p2","id":"fm4","src":"assets/audio/BX1-18/fm4.mp3","sec":10.128,"t":"易错：人体骨骼肌无氧呼吸产生乳酸，不产生CO2，所以人体产生的CO2只来自有氧呼吸。"},{"ep":"bx1-18","n":"BX1-18","p":3,"a":"p3","id":"cm1","src":"assets/audio/BX1-18/cm1.mp3","sec":9.024,"t":"考点三，有氧呼吸与无氧呼吸的比较。条件：有氧呼吸需要O2，无氧呼吸不需要O2。"},{"ep":"bx1-18","n":"BX1-18","p":3,"a":"p3","id":"cm2","src":"assets/audio/BX1-18/cm2.mp3","sec":7.32,"t":"场所：有氧呼吸在细胞质基质和线粒体；无氧呼吸只在细胞质基质。"},{"ep":"bx1-18","n":"BX1-18","p":3,"a":"p3","id":"cm3","src":"assets/audio/BX1-18/cm3.mp3","sec":11.208,"t":"产物：有氧呼吸是CO2和水；无氧呼吸是酒精和CO2，或者乳酸。能量：有氧大量，无氧少量。"},{"ep":"bx1-18","n":"BX1-18","p":3,"a":"p3","id":"cm4","src":"assets/audio/BX1-18/cm4.mp3","sec":7.032,"t":"解题方法：两者第一阶段完全相同，实质都是分解有机物、释放能量。"},{"ep":"bx1-18","n":"BX1-18","p":4,"a":"p4","id":"jd1","src":"assets/audio/BX1-18/jd1.mp3","sec":11.688,"t":"考点四，根据气体变化判断呼吸方式，以葡萄糖为底物。只释放CO2、不吸收O2：只进行产酒精的无氧呼吸。"},{"ep":"bx1-18","n":"BX1-18","p":4,"a":"p4","id":"jd2","src":"assets/audio/BX1-18/jd2.mp3","sec":9.432,"t":"CO2释放量等于O2吸收量：只进行有氧呼吸，或有氧呼吸和产乳酸的无氧呼吸同时进行。"},{"ep":"bx1-18","n":"BX1-18","p":4,"a":"p4","id":"jd3","src":"assets/audio/BX1-18/jd3.mp3","sec":7.68,"t":"CO2释放量大于O2吸收量：有氧呼吸和产酒精的无氧呼吸同时进行。"},{"ep":"bx1-18","n":"BX1-18","p":4,"a":"p4","id":"jd4","src":"assets/audio/BX1-18/jd4.mp3","sec":8.04,"t":"既不吸收O2，也不释放CO2：只进行产乳酸的无氧呼吸，或者细胞已经死亡。"},{"ep":"bx1-18","n":"BX1-18","p":4,"a":"p4","id":"jd5","src":"assets/audio/BX1-18/jd5.mp3","sec":7.968,"t":"易错：以脂肪为底物时，O2消耗量大于CO2释放量，不能套用上面的结论。"},{"ep":"bx1-18","n":"BX1-18","p":5,"a":"p5","id":"ca1","src":"assets/audio/BX1-18/ca1.mp3","sec":9.216,"t":"考点五，相关计算。有氧呼吸：1分子葡萄糖消耗6分子O2，产生6分子CO2。"},{"ep":"bx1-18","n":"BX1-18","p":5,"a":"p5","id":"ca2","src":"assets/audio/BX1-18/ca2.mp3","sec":7.104,"t":"产酒精的无氧呼吸：1分子葡萄糖产生2分子CO2，不消耗O2。"},{"ep":"bx1-18","n":"BX1-18","p":5,"a":"p5","id":"ca3","src":"assets/audio/BX1-18/ca3.mp3","sec":12.84,"t":"例：酵母菌吸收O2 6 mol，释放CO2 10 mol：有氧呼吸消耗葡萄糖1 mol；无氧呼吸产生CO2 4 mol，消耗葡萄糖2 mol。"},{"ep":"bx1-18","n":"BX1-18","p":5,"a":"p5","id":"ca4","src":"assets/audio/BX1-18/ca4.mp3","sec":7.872,"t":"解题方法：先用O2吸收量算出有氧呼吸，再用剩下的CO2算无氧呼吸。"},{"ep":"bx1-18","n":"BX1-18","p":6,"a":"p6","id":"fc1","src":"assets/audio/BX1-18/fc1.mp3","sec":7.08,"t":"考点六，影响细胞呼吸的因素。温度主要通过影响呼吸酶的活性起作用。"},{"ep":"bx1-18","n":"BX1-18","p":6,"a":"p6","id":"fc2","src":"assets/audio/BX1-18/fc2.mp3","sec":13.152,"t":"O2浓度：为0时只进行无氧呼吸；随O2浓度增大，无氧呼吸受抑制，有氧呼吸增强；CO2释放总量最少时，有机物消耗最少。"},{"ep":"bx1-18","n":"BX1-18","p":6,"a":"p6","id":"fc3","src":"assets/audio/BX1-18/fc3.mp3","sec":9.384,"t":"水：一定范围内，自由水含量越高，细胞呼吸越旺盛；CO2浓度升高，会抑制细胞呼吸。"},{"ep":"bx1-18","n":"BX1-18","p":6,"a":"p6","id":"fc4","src":"assets/audio/BX1-18/fc4.mp3","sec":7.776,"t":"考法：储存果蔬选低温、低氧、适宜湿度；储存种子选低温、低氧、干燥。"},{"ep":"bx1-18","n":"BX1-18","p":7,"a":"p7","id":"ap1","src":"assets/audio/BX1-18/ap1.mp3","sec":10.176,"t":"考点七，细胞呼吸原理的应用。包扎伤口选用透气的消毒纱布，抑制破伤风芽孢杆菌等厌氧菌的繁殖。"},{"ep":"bx1-18","n":"BX1-18","p":7,"a":"p7","id":"ap2","src":"assets/audio/BX1-18/ap2.mp3","sec":8.28,"t":"酿酒先通气、后密封：先让酵母菌有氧呼吸、大量繁殖，再无氧呼吸、产生酒精。"},{"ep":"bx1-18","n":"BX1-18","p":7,"a":"p7","id":"ap3","src":"assets/audio/BX1-18/ap3.mp3","sec":11.28,"t":"土壤板结要及时松土透气，促进根的有氧呼吸，利于吸收无机盐；提倡慢跑等有氧运动，避免肌细胞产生大量乳酸。"},{"ep":"bx1-18","n":"BX1-18","p":7,"a":"p7","id":"ap4","src":"assets/audio/BX1-18/ap4.mp3","sec":7.152,"t":"易错：稻田要定期排水，防止根进行无氧呼吸产生酒精，导致烂根。"},{"ep":"bx1-18","n":"BX1-18","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-18/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-18","n":"BX1-18","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-18/rv2.mp3","sec":9.0,"t":"判断一？错，只有第一阶段释放能量。判断二？错，人无氧呼吸只产生乳酸。"},{"ep":"bx1-18","n":"BX1-18","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-18/rv3.mp3","sec":7.944,"t":"判断三？对。判断四？错，也可能同时进行产乳酸的无氧呼吸。"},{"ep":"bx1-18","n":"BX1-18","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-18/rv4.mp3","sec":6.288,"t":"判断五？对。判断六？错，是为了抑制厌氧菌。"},{"ep":"bx1-18","n":"BX1-18","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-18/rv5.mp3","sec":8.28,"t":"七个考点串成一条线：先用O2算有氧，剩下的CO2算无氧。我们下期再见！"},{"ep":"bx1-19","n":"BX1-19","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-19/in1.mp3","sec":8.52,"t":"同学们好！这节课梳理人教版必修一第五章第四节的第一部分——捕获光能的色素和结构。"},{"ep":"bx1-19","n":"BX1-19","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-19/in2.mp3","sec":8.112,"t":"高考常考色素提取和分离实验、色素带和异常结果分析，以及色素的吸收光谱。"},{"ep":"bx1-19","n":"BX1-19","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-19/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-19","n":"BX1-19","p":1,"a":"p1","id":"pc1","src":"assets/audio/BX1-19/pc1.mp3","sec":8.856,"t":"考点一，绿叶中色素的提取和分离。提取的原理：色素能够溶解在有机溶剂无水乙醇中。"},{"ep":"bx1-19","n":"BX1-19","p":1,"a":"p1","id":"pc2","src":"assets/audio/BX1-19/pc2.mp3","sec":9.648,"t":"分离的原理：不同色素在层析液中的溶解度不同，溶解度高的随层析液在滤纸上扩散得快，反之则慢。"},{"ep":"bx1-19","n":"BX1-19","p":1,"a":"p1","id":"pc3","src":"assets/audio/BX1-19/pc3.mp3","sec":7.488,"t":"易错：提取用无水乙醇，分离用层析液，别混；分离的方法叫纸层析法。"},{"ep":"bx1-19","n":"BX1-19","p":2,"a":"p2","id":"sp1","src":"assets/audio/BX1-19/sp1.mp3","sec":10.656,"t":"考点二，实验步骤。研磨时加入SiO2，有助于研磨充分；加入CaCO3，防止研磨中色素被破坏。"},{"ep":"bx1-19","n":"BX1-19","p":2,"a":"p2","id":"sp2","src":"assets/audio/BX1-19/sp2.mp3","sec":4.224,"t":"研磨后用单层尼龙布过滤，收集滤液。"},{"ep":"bx1-19","n":"BX1-19","p":2,"a":"p2","id":"sp3","src":"assets/audio/BX1-19/sp3.mp3","sec":7.224,"t":"画滤液细线要细、直、齐，待滤液干后再画一两次，使色素多而集中。"},{"ep":"bx1-19","n":"BX1-19","p":2,"a":"p2","id":"sp4","src":"assets/audio/BX1-19/sp4.mp3","sec":6.6,"t":"层析时，层析液不能没及滤液细线，否则色素会溶解到层析液中。"},{"ep":"bx1-19","n":"BX1-19","p":2,"a":"p2","id":"sp5","src":"assets/audio/BX1-19/sp5.mp3","sec":9.792,"t":"解题方法：一种试剂一个作用——SiO2助研磨，CaCO3护色素，无水乙醇溶色素，层析液分色素。"},{"ep":"bx1-19","n":"BX1-19","p":3,"a":"p3","id":"rs1","src":"assets/audio/BX1-19/rs1.mp3","sec":9.216,"t":"考点三，实验结果。滤纸条上从上到下依次是：胡萝卜素，橙黄色；叶黄素，黄色；"},{"ep":"bx1-19","n":"BX1-19","p":3,"a":"p3","id":"rs2","src":"assets/audio/BX1-19/rs2.mp3","sec":4.488,"t":"叶绿素a，蓝绿色；叶绿素b，黄绿色。"},{"ep":"bx1-19","n":"BX1-19","p":3,"a":"p3","id":"rs3","src":"assets/audio/BX1-19/rs3.mp3","sec":9.48,"t":"最宽的是叶绿素a，含量最多；最窄的是胡萝卜素；胡萝卜素在层析液中溶解度最高，扩散最快。"},{"ep":"bx1-19","n":"BX1-19","p":3,"a":"p3","id":"rs4","src":"assets/audio/BX1-19/rs4.mp3","sec":10.848,"t":"解题方法：顺序记“胡、黄、a、b”；宽度看含量：叶绿素a、叶绿素b、叶黄素、胡萝卜素依次减少。"},{"ep":"bx1-19","n":"BX1-19","p":4,"a":"p4","id":"ab1","src":"assets/audio/BX1-19/ab1.mp3","sec":12.12,"t":"考点四，异常结果分析。色素带颜色都很浅：可能是研磨不充分、未加SiO2、无水乙醇加得过多，或画线次数太少。"},{"ep":"bx1-19","n":"BX1-19","p":4,"a":"p4","id":"ab2","src":"assets/audio/BX1-19/ab2.mp3","sec":8.256,"t":"叶绿素带很窄甚至没有：可能是未加CaCO3，叶绿素被破坏；或者选用了发黄的叶片。"},{"ep":"bx1-19","n":"BX1-19","p":4,"a":"p4","id":"ab3","src":"assets/audio/BX1-19/ab3.mp3","sec":6.84,"t":"没有色素带：可能是层析液没及了滤液细线，或者用水代替了无水乙醇。"},{"ep":"bx1-19","n":"BX1-19","p":4,"a":"p4","id":"ab4","src":"assets/audio/BX1-19/ab4.mp3","sec":5.88,"t":"解题方法：对照每一步的作用，缺了哪一步，就出现哪种异常。"},{"ep":"bx1-19","n":"BX1-19","p":5,"a":"p5","id":"sc1","src":"assets/audio/BX1-19/sc1.mp3","sec":7.608,"t":"考点五，色素的吸收光谱。叶绿素a和叶绿素b主要吸收蓝紫光和红光。"},{"ep":"bx1-19","n":"BX1-19","p":5,"a":"p5","id":"sc2","src":"assets/audio/BX1-19/sc2.mp3","sec":5.736,"t":"胡萝卜素和叶黄素，也就是类胡萝卜素，主要吸收蓝紫光。"},{"ep":"bx1-19","n":"BX1-19","p":5,"a":"p5","id":"sc3","src":"assets/audio/BX1-19/sc3.mp3","sec":6.408,"t":"色素对绿光吸收最少，绿光被反射出来，所以叶片呈绿色。"},{"ep":"bx1-19","n":"BX1-19","p":5,"a":"p5","id":"sc4","src":"assets/audio/BX1-19/sc4.mp3","sec":8.256,"t":"考法：温室补光选红光或蓝紫光，不用绿光。易错：类胡萝卜素不吸收红光。"},{"ep":"bx1-19","n":"BX1-19","p":6,"a":"p6","id":"cl1","src":"assets/audio/BX1-19/cl1.mp3","sec":10.776,"t":"考点六，叶绿体的结构适于进行光合作用。叶绿体有双层膜，内部有许多基粒，每个基粒由类囊体堆叠而成。"},{"ep":"bx1-19","n":"BX1-19","p":6,"a":"p6","id":"cl2","src":"assets/audio/BX1-19/cl2.mp3","sec":4.848,"t":"吸收光能的四种色素，都分布在类囊体的薄膜上。"},{"ep":"bx1-19","n":"BX1-19","p":6,"a":"p6","id":"cl3","src":"assets/audio/BX1-19/cl3.mp3","sec":6.672,"t":"类囊体薄膜上和叶绿体基质中，含有许多进行光合作用所必需的酶。"},{"ep":"bx1-19","n":"BX1-19","p":6,"a":"p6","id":"cl4","src":"assets/audio/BX1-19/cl4.mp3","sec":7.464,"t":"解题方法：基粒和类囊体极大地扩展了受光面积，体现了结构与功能相适应。"},{"ep":"bx1-19","n":"BX1-19","p":7,"a":"p7","id":"eg1","src":"assets/audio/BX1-19/eg1.mp3","sec":10.704,"t":"考点七，恩格尔曼的实验。把载有水绵和需氧细菌的临时装片，放在没有空气的黑暗环境里，用极细的光束照射。"},{"ep":"bx1-19","n":"BX1-19","p":7,"a":"p7","id":"eg2","src":"assets/audio/BX1-19/eg2.mp3","sec":10.248,"t":"需氧细菌只向叶绿体被光束照射到的部位集中；如果完全暴露在光下，细菌就分布在叶绿体所有受光的部位。"},{"ep":"bx1-19","n":"BX1-19","p":7,"a":"p7","id":"eg3","src":"assets/audio/BX1-19/eg3.mp3","sec":9.24,"t":"结论：叶绿体能吸收光能用于光合作用放氧；结合其他证据，得出叶绿体是光合作用的场所。"},{"ep":"bx1-19","n":"BX1-19","p":7,"a":"p7","id":"eg4","src":"assets/audio/BX1-19/eg4.mp3","sec":7.2,"t":"他还用透过三棱镜的光照射水绵，发现细菌主要聚集在红光和蓝紫光区域。"},{"ep":"bx1-19","n":"BX1-19","p":7,"a":"p7","id":"eg5","src":"assets/audio/BX1-19/eg5.mp3","sec":10.32,"t":"解题方法：选水绵是因为它的叶绿体呈螺旋带状，便于观察；黑暗、无空气是为了排除光和氧气的干扰。"},{"ep":"bx1-19","n":"BX1-19","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-19/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-19","n":"BX1-19","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-19/rv2.mp3","sec":9.648,"t":"判断一？错，提取用无水乙醇，分离用层析液。判断二？错，助研磨的是SiO2。"},{"ep":"bx1-19","n":"BX1-19","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-19/rv3.mp3","sec":7.368,"t":"判断三？对。判断四？错，类胡萝卜素主要吸收蓝紫光。"},{"ep":"bx1-19","n":"BX1-19","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-19/rv4.mp3","sec":6.84,"t":"判断五？错，色素在类囊体薄膜上。判断六？对。"},{"ep":"bx1-19","n":"BX1-19","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-19/rv5.mp3","sec":7.368,"t":"七个考点串成一条线：从上到下，胡、黄、a、b。我们下期再见！"},{"ep":"bx1-20","n":"BX1-20","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-20/in1.mp3","sec":7.968,"t":"同学们好！这节课梳理人教版必修一第五章第四节的第二部分——光合作用的原理。"},{"ep":"bx1-20","n":"BX1-20","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-20/in2.mp3","sec":8.472,"t":"高考常考探索历程中的经典实验、光反应和暗反应，以及条件骤变时物质含量的变化。"},{"ep":"bx1-20","n":"BX1-20","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-20/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-20","n":"BX1-20","p":1,"a":"p1","id":"hs1","src":"assets/audio/BX1-20/hs1.mp3","sec":12.432,"t":"考点一，探索光合作用原理的实验。希尔发现，离体叶绿体悬浮液中加入铁盐等氧化剂，光照下能释放氧气，这叫希尔反应。"},{"ep":"bx1-20","n":"BX1-20","p":1,"a":"p1","id":"hs2","src":"assets/audio/BX1-20/hs2.mp3","sec":8.448,"t":"鲁宾和卡门用18O分别标记H2O和CO2，证明光合作用释放的氧气全部来自水。"},{"ep":"bx1-20","n":"BX1-20","p":1,"a":"p1","id":"hs3","src":"assets/audio/BX1-20/hs3.mp3","sec":8.088,"t":"阿尔农发现，光照下叶绿体可以合成ATP，并且这一过程总是与水的光解相伴随。"},{"ep":"bx1-20","n":"BX1-20","p":1,"a":"p1","id":"hs4","src":"assets/audio/BX1-20/hs4.mp3","sec":9.552,"t":"卡尔文用14C标记的CO2，探明了CO2中的碳转化为有机物中碳的途径，叫卡尔文循环。"},{"ep":"bx1-20","n":"BX1-20","p":1,"a":"p1","id":"hs5","src":"assets/audio/BX1-20/hs5.mp3","sec":6.264,"t":"易错：18O是稳定同位素，没有放射性；14C有放射性。"},{"ep":"bx1-20","n":"BX1-20","p":2,"a":"p2","id":"tt1","src":"assets/audio/BX1-20/tt1.mp3","sec":9.288,"t":"考点二，光合作用的总反应式：CO2和H2O，在光能和叶绿体的作用下，生成糖类和O2。"},{"ep":"bx1-20","n":"BX1-20","p":2,"a":"p2","id":"tt2","src":"assets/audio/BX1-20/tt2.mp3","sec":10.08,"t":"也就是绿色植物通过叶绿体，利用光能，把CO2和水转化成储存着能量的有机物，并且释放出O2。"},{"ep":"bx1-20","n":"BX1-20","p":2,"a":"p2","id":"tt3","src":"assets/audio/BX1-20/tt3.mp3","sec":7.056,"t":"解题方法：箭头上注明光能和叶绿体；产物O2中的氧全部来自水。"},{"ep":"bx1-20","n":"BX1-20","p":3,"a":"p3","id":"lt1","src":"assets/audio/BX1-20/lt1.mp3","sec":7.248,"t":"考点三，光反应。场所：类囊体薄膜；条件：光、色素和酶。"},{"ep":"bx1-20","n":"BX1-20","p":3,"a":"p3","id":"lt2","src":"assets/audio/BX1-20/lt2.mp3","sec":10.776,"t":"物质变化：水的光解，产生O2和H+；NADP+与H+结合形成NADPH；ADP和Pi形成ATP。"},{"ep":"bx1-20","n":"BX1-20","p":3,"a":"p3","id":"lt3","src":"assets/audio/BX1-20/lt3.mp3","sec":5.232,"t":"能量变化：光能转化为ATP和NADPH中的化学能。"},{"ep":"bx1-20","n":"BX1-20","p":3,"a":"p3","id":"lt4","src":"assets/audio/BX1-20/lt4.mp3","sec":8.112,"t":"易错：光反应产生的O2释放到外界或用于呼吸；ATP和NADPH则用于暗反应。"},{"ep":"bx1-20","n":"BX1-20","p":4,"a":"p4","id":"dk1","src":"assets/audio/BX1-20/dk1.mp3","sec":9.72,"t":"考点四，暗反应。场所：叶绿体基质；有光无光都能进行，但需要光反应提供的ATP和NADPH。"},{"ep":"bx1-20","n":"BX1-20","p":4,"a":"p4","id":"dk2","src":"assets/audio/BX1-20/dk2.mp3","sec":6.12,"t":"CO2的固定：CO2与C5结合，形成两个C3分子。"},{"ep":"bx1-20","n":"BX1-20","p":4,"a":"p4","id":"dk3","src":"assets/audio/BX1-20/dk3.mp3","sec":7.968,"t":"C3的还原：在ATP和NADPH的作用下，C3被还原为糖类，同时再生出C5。"},{"ep":"bx1-20","n":"BX1-20","p":4,"a":"p4","id":"dk4","src":"assets/audio/BX1-20/dk4.mp3","sec":7.728,"t":"能量变化：ATP和NADPH中的化学能，转化为储存在糖类等有机物中的化学能。"},{"ep":"bx1-20","n":"BX1-20","p":4,"a":"p4","id":"dk5","src":"assets/audio/BX1-20/dk5.mp3","sec":8.136,"t":"易错：暗反应不是只在黑暗中进行；没有光，光反应停止，暗反应也会很快停止。"},{"ep":"bx1-20","n":"BX1-20","p":5,"a":"p5","id":"lk1","src":"assets/audio/BX1-20/lk1.mp3","sec":12.264,"t":"考点五，光反应与暗反应的联系。光反应为暗反应提供ATP和NADPH；暗反应为光反应提供ADP、Pi和NADP+。"},{"ep":"bx1-20","n":"BX1-20","p":5,"a":"p5","id":"lk2","src":"assets/audio/BX1-20/lk2.mp3","sec":4.776,"t":"两者相互依存、紧密联系，是一个统一的整体。"},{"ep":"bx1-20","n":"BX1-20","p":5,"a":"p5","id":"lk3","src":"assets/audio/BX1-20/lk3.mp3","sec":10.992,"t":"解题方法：记住物质流向——ATP、NADPH从类囊体流向基质；ADP、Pi、NADP+从基质流回类囊体。"},{"ep":"bx1-20","n":"BX1-20","p":6,"a":"p6","id":"sd1","src":"assets/audio/BX1-20/sd1.mp3","sec":12.264,"t":"考点六，条件骤变时物质含量的变化。光照减弱：ATP和NADPH减少，C3的还原变慢，所以C3增加、C5减少。"},{"ep":"bx1-20","n":"BX1-20","p":6,"a":"p6","id":"sd2","src":"assets/audio/BX1-20/sd2.mp3","sec":10.104,"t":"CO2供应减少：CO2的固定变慢，C3减少、C5增加；ATP和NADPH消耗减少，含量增加。"},{"ep":"bx1-20","n":"BX1-20","p":6,"a":"p6","id":"sd3","src":"assets/audio/BX1-20/sd3.mp3","sec":10.248,"t":"解题方法：抓住C3和C5的来路和去路——条件改变只影响其中一条路，另一条暂时不变，就能推出增减。"},{"ep":"bx1-20","n":"BX1-20","p":7,"a":"p7","id":"ch1","src":"assets/audio/BX1-20/ch1.mp3","sec":11.496,"t":"考点七，化能合成作用。少数细菌利用体外环境中某些无机物氧化时释放的能量来制造有机物，叫化能合成作用。"},{"ep":"bx1-20","n":"BX1-20","p":7,"a":"p7","id":"ch2","src":"assets/audio/BX1-20/ch2.mp3","sec":10.992,"t":"例如硝化细菌，能将土壤中的氨氧化成亚硝酸，进而氧化成硝酸，利用释放的化学能，把CO2和水合成糖类。"},{"ep":"bx1-20","n":"BX1-20","p":7,"a":"p7","id":"ch3","src":"assets/audio/BX1-20/ch3.mp3","sec":11.592,"t":"能用无机物合成有机物的是自养生物，如绿色植物、硝化细菌；只能利用现成有机物的是异养生物，如人、动物、真菌。"},{"ep":"bx1-20","n":"BX1-20","p":7,"a":"p7","id":"ch4","src":"assets/audio/BX1-20/ch4.mp3","sec":8.952,"t":"易错：硝化细菌是自养生物，但利用的是化学能，不是光能；它是原核生物，没有叶绿体。"},{"ep":"bx1-20","n":"BX1-20","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-20/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-20","n":"BX1-20","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-20/rv2.mp3","sec":9.312,"t":"判断一？错，O2中的氧全部来自水。判断二？错，光反应在类囊体薄膜上。"},{"ep":"bx1-20","n":"BX1-20","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-20/rv3.mp3","sec":7.032,"t":"判断三？错，暗反应有光无光都能进行。判断四？对。"},{"ep":"bx1-20","n":"BX1-20","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-20/rv4.mp3","sec":6.192,"t":"判断五？对。判断六？错，利用的是化学能。"},{"ep":"bx1-20","n":"BX1-20","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-20/rv5.mp3","sec":7.8,"t":"七个考点串成一条线：看来路和去路，推C3、C5的增减。我们下期再见！"},{"ep":"bx1-21","n":"BX1-21","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-21/in1.mp3","sec":8.952,"t":"同学们好！这节课梳理人教版必修一第五章第四节的第三部分——影响光合作用的因素及应用。"},{"ep":"bx1-21","n":"BX1-21","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-21/in2.mp3","sec":8.184,"t":"高考常考光照强度、CO2浓度等因素的曲线分析，以及总光合与净光合的计算。"},{"ep":"bx1-21","n":"BX1-21","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-21/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-21","n":"BX1-21","p":1,"a":"p1","id":"it1","src":"assets/audio/BX1-21/it1.mp3","sec":8.088,"t":"考点一，光合作用强度。指植物在单位时间内通过光合作用制造糖类的数量。"},{"ep":"bx1-21","n":"BX1-21","p":1,"a":"p1","id":"it2","src":"assets/audio/BX1-21/it2.mp3","sec":10.488,"t":"可以用单位时间内原料的消耗量，如CO2的吸收量，或产物的生成量，如O2的释放量、有机物的积累量来表示。"},{"ep":"bx1-21","n":"BX1-21","p":1,"a":"p1","id":"it3","src":"assets/audio/BX1-21/it3.mp3","sec":9.384,"t":"易错：实际测得的CO2吸收量或O2释放量是净光合速率，因为同时还在进行呼吸作用。"},{"ep":"bx1-21","n":"BX1-21","p":2,"a":"p2","id":"dk1","src":"assets/audio/BX1-21/dk1.mp3","sec":12.264,"t":"考点二，探究光照强度对光合作用强度的影响。用打孔器打出圆形小叶片，用注射器抽出叶片内的气体，叶片沉到水底。"},{"ep":"bx1-21","n":"BX1-21","p":2,"a":"p2","id":"dk2","src":"assets/audio/BX1-21/dk2.mp3","sec":8.64,"t":"把小叶片放入富含CO2的清水中，用不同强度的光照射，比如调节光源与烧杯的距离。"},{"ep":"bx1-21","n":"BX1-21","p":2,"a":"p2","id":"dk3","src":"assets/audio/BX1-21/dk3.mp3","sec":7.992,"t":"光合作用产生O2，叶片会浮起；单位时间内浮起的叶片越多，光合作用越强。"},{"ep":"bx1-21","n":"BX1-21","p":2,"a":"p2","id":"dk4","src":"assets/audio/BX1-21/dk4.mp3","sec":10.344,"t":"解题方法：自变量是光照强度，因变量是叶片上浮的数量或时间；抽气是为了排除叶片内原有气体的干扰。"},{"ep":"bx1-21","n":"BX1-21","p":3,"a":"p3","id":"lc1","src":"assets/audio/BX1-21/lc1.mp3","sec":10.8,"t":"考点三，光照强度的影响曲线。纵轴是CO2吸收量，光照为0时只进行呼吸作用，曲线在横轴以下。"},{"ep":"bx1-21","n":"BX1-21","p":3,"a":"p3","id":"lc2","src":"assets/audio/BX1-21/lc2.mp3","sec":5.232,"t":"光合速率等于呼吸速率时的光照强度，叫光补偿点。"},{"ep":"bx1-21","n":"BX1-21","p":3,"a":"p3","id":"lc3","src":"assets/audio/BX1-21/lc3.mp3","sec":7.368,"t":"光照增强到一定程度后，光合速率不再增加，这时的光照强度叫光饱和点。"},{"ep":"bx1-21","n":"BX1-21","p":3,"a":"p3","id":"lc4","src":"assets/audio/BX1-21/lc4.mp3","sec":12.168,"t":"考法：阴生植物的光补偿点和光饱和点都比阳生植物低。易错：光补偿点时，叶肉细胞的光合速率大于它自身的呼吸速率。"},{"ep":"bx1-21","n":"BX1-21","p":4,"a":"p4","id":"gn1","src":"assets/audio/BX1-21/gn1.mp3","sec":8.424,"t":"考点四，总光合速率与净光合速率。总光合速率 = 净光合速率 + 呼吸速率。"},{"ep":"bx1-21","n":"BX1-21","p":4,"a":"p4","id":"gn2","src":"assets/audio/BX1-21/gn2.mp3","sec":12.048,"t":"表示总光合的词：产生、制造O2或有机物，固定CO2；表示净光合的词：释放O2、吸收CO2、积累有机物。"},{"ep":"bx1-21","n":"BX1-21","p":4,"a":"p4","id":"gn3","src":"assets/audio/BX1-21/gn3.mp3","sec":4.68,"t":"黑暗中测得的CO2释放量，就是呼吸速率。"},{"ep":"bx1-21","n":"BX1-21","p":4,"a":"p4","id":"gn4","src":"assets/audio/BX1-21/gn4.mp3","sec":8.712,"t":"解题方法：先看关键词判断是总还是净；植物能否生长，看净光合速率是否大于0。"},{"ep":"bx1-21","n":"BX1-21","p":5,"a":"p5","id":"cc1","src":"assets/audio/BX1-21/cc1.mp3","sec":11.976,"t":"考点五，CO2浓度的影响。一定范围内，光合作用强度随CO2浓度增大而增大，达到CO2饱和点后不再增加。"},{"ep":"bx1-21","n":"BX1-21","p":5,"a":"p5","id":"cc2","src":"assets/audio/BX1-21/cc2.mp3","sec":9.6,"t":"CO2浓度过低时，光合速率小于呼吸速率；两者相等时的CO2浓度，叫CO2补偿点。"},{"ep":"bx1-21","n":"BX1-21","p":5,"a":"p5","id":"cc3","src":"assets/audio/BX1-21/cc3.mp3","sec":8.952,"t":"考法：温室中增施有机肥，微生物分解有机物产生CO2；也可以通风补充CO2。"},{"ep":"bx1-21","n":"BX1-21","p":6,"a":"p6","id":"ot1","src":"assets/audio/BX1-21/ot1.mp3","sec":9.288,"t":"考点六，温度、水和矿质元素。温度通过影响酶的活性影响光合作用，曲线先升后降。"},{"ep":"bx1-21","n":"BX1-21","p":6,"a":"p6","id":"ot2","src":"assets/audio/BX1-21/ot2.mp3","sec":6.384,"t":"缺水时叶片气孔关闭，CO2吸收减少，光合作用减弱。"},{"ep":"bx1-21","n":"BX1-21","p":6,"a":"p6","id":"ot3","src":"assets/audio/BX1-21/ot3.mp3","sec":7.464,"t":"矿质元素：如Mg是叶绿素的组成成分，N是酶、ATP、NADPH的组成元素。"},{"ep":"bx1-21","n":"BX1-21","p":6,"a":"p6","id":"ot4","src":"assets/audio/BX1-21/ot4.mp3","sec":10.152,"t":"解题方法：多因素曲线中，上升段的限制因素是横坐标所示因素；到达平台后，限制因素是其他因素。"},{"ep":"bx1-21","n":"BX1-21","p":7,"a":"p7","id":"cv1","src":"assets/audio/BX1-21/cv1.mp3","sec":13.608,"t":"考点七，两类典型曲线。夏季晴天中午，温度高、蒸腾作用强，气孔部分关闭，CO2吸收减少，光合速率下降，出现“午休”现象。"},{"ep":"bx1-21","n":"BX1-21","p":7,"a":"p7","id":"cv2","src":"assets/audio/BX1-21/cv2.mp3","sec":9.312,"t":"密闭容器中一昼夜的CO2浓度：曲线的最高点和最低点，对应光合速率等于呼吸速率的时刻。"},{"ep":"bx1-21","n":"BX1-21","p":7,"a":"p7","id":"cv3","src":"assets/audio/BX1-21/cv3.mp3","sec":10.464,"t":"最高点之前，呼吸大于光合，CO2浓度上升；之后光合大于呼吸，CO2浓度下降，直到最低点。"},{"ep":"bx1-21","n":"BX1-21","p":7,"a":"p7","id":"cv4","src":"assets/audio/BX1-21/cv4.mp3","sec":9.168,"t":"解题方法：比较一昼夜首尾的CO2浓度，终点低于起点，说明有机物有积累，植物能生长。"},{"ep":"bx1-21","n":"BX1-21","p":8,"a":"p8","id":"ap1","src":"assets/audio/BX1-21/ap1.mp3","sec":8.376,"t":"考点八，光合作用原理的应用。合理密植：充分利用光能，又避免叶片相互遮挡。"},{"ep":"bx1-21","n":"BX1-21","p":8,"a":"p8","id":"ap2","src":"assets/audio/BX1-21/ap2.mp3","sec":6.768,"t":"间作套种，充分利用光能；温室中适当增加光照、补充CO2。"},{"ep":"bx1-21","n":"BX1-21","p":8,"a":"p8","id":"ap3","src":"assets/audio/BX1-21/ap3.mp3","sec":9.192,"t":"适当提高昼夜温差：白天温度适宜，光合作用强；夜晚温度低，呼吸作用弱，有机物积累多。"},{"ep":"bx1-21","n":"BX1-21","p":8,"a":"p8","id":"ap4","src":"assets/audio/BX1-21/ap4.mp3","sec":9.144,"t":"易错：温室补光用红光或蓝紫光；阴天光照弱时，温室应适当降低温度，减少呼吸消耗。"},{"ep":"bx1-21","n":"BX1-21","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-21/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-21","n":"BX1-21","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-21/rv2.mp3","sec":8.64,"t":"判断一？错，代表净光合速率。判断二？错，阴生植物的光补偿点较低。"},{"ep":"bx1-21","n":"BX1-21","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-21/rv3.mp3","sec":6.192,"t":"判断三？对。判断四？错，是气孔部分关闭。"},{"ep":"bx1-21","n":"BX1-21","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-21/rv4.mp3","sec":6.36,"t":"判断五？对。判断六？错，夜间应适当降温。"},{"ep":"bx1-21","n":"BX1-21","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-21/rv5.mp3","sec":7.632,"t":"八个考点串成一条线：能不能生长，看净光合是否大于零。我们下期再见！"},{"ep":"bx1-22","n":"BX1-22","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-22/in1.mp3","sec":8.616,"t":"同学们好！这节课梳理人教版必修一第六章第一节的上半部分——细胞周期与有丝分裂。"},{"ep":"bx1-22","n":"BX1-22","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-22/in2.mp3","sec":8.352,"t":"高考常考细胞周期的判断、有丝分裂各时期的特点，以及染色体和核DNA数目的变化。"},{"ep":"bx1-22","n":"BX1-22","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-22/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-22","n":"BX1-22","p":1,"a":"p1","id":"sz1","src":"assets/audio/BX1-22/sz1.mp3","sec":11.904,"t":"考点一，细胞增殖。细胞通过细胞分裂增加细胞数量，叫细胞增殖，它是生物体生长、发育、繁殖和遗传的基础。"},{"ep":"bx1-22","n":"BX1-22","p":1,"a":"p1","id":"sz2","src":"assets/audio/BX1-22/sz2.mp3","sec":7.68,"t":"细胞不能无限长大：细胞体积越大，相对表面积越小，物质运输的效率就越低。"},{"ep":"bx1-22","n":"BX1-22","p":1,"a":"p1","id":"sz3","src":"assets/audio/BX1-22/sz3.mp3","sec":10.848,"t":"细胞增殖包括物质准备和细胞分裂两个连续的过程；真核细胞的分裂方式有有丝分裂、无丝分裂和减数分裂。"},{"ep":"bx1-22","n":"BX1-22","p":1,"a":"p1","id":"sz4","src":"assets/audio/BX1-22/sz4.mp3","sec":7.08,"t":"易错：细胞也不是越小越好，细胞内还要容纳酶、核糖体等物质和结构。"},{"ep":"bx1-22","n":"BX1-22","p":2,"a":"p2","id":"cy1","src":"assets/audio/BX1-22/cy1.mp3","sec":10.728,"t":"考点二，细胞周期。连续分裂的细胞，从一次分裂完成时开始，到下一次分裂完成时为止，为一个细胞周期。"},{"ep":"bx1-22","n":"BX1-22","p":2,"a":"p2","id":"cy2","src":"assets/audio/BX1-22/cy2.mp3","sec":9.096,"t":"一个细胞周期包括分裂间期和分裂期，间期在前，大约占细胞周期的90%～95%。"},{"ep":"bx1-22","n":"BX1-22","p":2,"a":"p2","id":"cy3","src":"assets/audio/BX1-22/cy3.mp3","sec":11.256,"t":"易错：只有连续分裂的细胞才有细胞周期，如分生区细胞；高度分化的神经细胞、进行减数分裂的细胞没有细胞周期。"},{"ep":"bx1-22","n":"BX1-22","p":3,"a":"p3","id":"rp1","src":"assets/audio/BX1-22/rp1.mp3","sec":10.68,"t":"考点三，细胞周期的表示方法。线段图：间期长、分裂期短，一个周期要从间期开始，到分裂期结束。"},{"ep":"bx1-22","n":"BX1-22","p":3,"a":"p3","id":"rp2","src":"assets/audio/BX1-22/rp2.mp3","sec":7.152,"t":"扇形图：按顺时针方向，从间期到分裂期，回到起点为一个细胞周期。"},{"ep":"bx1-22","n":"BX1-22","p":3,"a":"p3","id":"rp3","src":"assets/audio/BX1-22/rp3.mp3","sec":8.544,"t":"解题方法：判断哪段是一个细胞周期，看先间期、后分裂期，而且两段首尾相接。"},{"ep":"bx1-22","n":"BX1-22","p":4,"a":"p4","id":"ip1","src":"assets/audio/BX1-22/ip1.mp3","sec":12.624,"t":"考点四，分裂间期。为分裂期进行活跃的物质准备，完成DNA分子的复制和有关蛋白质的合成，同时细胞有适度的生长。"},{"ep":"bx1-22","n":"BX1-22","p":4,"a":"p4","id":"ip2","src":"assets/audio/BX1-22/ip2.mp3","sec":9.072,"t":"DNA复制后，每条染色体含有两条姐妹染色单体，核DNA数目加倍，但染色体数目不变。"},{"ep":"bx1-22","n":"BX1-22","p":4,"a":"p4","id":"ip3","src":"assets/audio/BX1-22/ip3.mp3","sec":9.096,"t":"易错：间期遗传物质呈染色质状态，显微镜下看不到染色体；间期不属于分裂期的前期。"},{"ep":"bx1-22","n":"BX1-22","p":5,"a":"p5","id":"ea1","src":"assets/audio/BX1-22/ea1.mp3","sec":14.832,"t":"考点五，前期和中期，以高等植物细胞为例。前期：染色质丝螺旋化成为染色体；核仁解体、核膜消失；细胞两极发出纺锤丝，形成纺锤体。"},{"ep":"bx1-22","n":"BX1-22","p":5,"a":"p5","id":"ea2","src":"assets/audio/BX1-22/ea2.mp3","sec":11.616,"t":"中期：纺锤丝附着在着丝粒两侧，着丝粒排列在赤道板上；染色体形态稳定、数目清晰，是观察染色体的最佳时期。"},{"ep":"bx1-22","n":"BX1-22","p":5,"a":"p5","id":"ea3","src":"assets/audio/BX1-22/ea3.mp3","sec":8.136,"t":"易错：赤道板是一个假想的平面，不是真实结构；末期出现的细胞板才是真实结构。"},{"ep":"bx1-22","n":"BX1-22","p":6,"a":"p6","id":"lt1","src":"assets/audio/BX1-22/lt1.mp3","sec":11.856,"t":"考点六，后期和末期。后期：着丝粒分裂，姐妹染色单体分开成为两条染色体，移向细胞两极，染色体数目加倍。"},{"ep":"bx1-22","n":"BX1-22","p":6,"a":"p6","id":"lt2","src":"assets/audio/BX1-22/lt2.mp3","sec":12.408,"t":"末期：染色体变成染色质丝，纺锤丝消失，出现新的核膜和核仁；植物细胞在赤道板位置出现细胞板，扩展形成新的细胞壁。"},{"ep":"bx1-22","n":"BX1-22","p":6,"a":"p6","id":"lt3","src":"assets/audio/BX1-22/lt3.mp3","sec":9.6,"t":"解题方法：记口诀——膜仁消失显两体，形定数晰赤道齐，点裂数增均两极，两消两现重开始。"},{"ep":"bx1-22","n":"BX1-22","p":7,"a":"p7","id":"ct1","src":"assets/audio/BX1-22/ct1.mp3","sec":12.432,"t":"考点七，数目的变化，设体细胞染色体数为2N。核DNA：间期复制，由2N变为4N；末期细胞一分为二，恢复为2N。"},{"ep":"bx1-22","n":"BX1-22","p":7,"a":"p7","id":"ct2","src":"assets/audio/BX1-22/ct2.mp3","sec":6.576,"t":"染色体：后期着丝粒分裂，由2N变为4N；末期恢复为2N。"},{"ep":"bx1-22","n":"BX1-22","p":7,"a":"p7","id":"ct3","src":"assets/audio/BX1-22/ct3.mp3","sec":7.44,"t":"染色单体：间期复制后出现，为4N；后期着丝粒分裂后消失，变为0。"},{"ep":"bx1-22","n":"BX1-22","p":7,"a":"p7","id":"ct4","src":"assets/audio/BX1-22/ct4.mp3","sec":11.904,"t":"解题方法：有染色单体时，染色单体数 = 核DNA数 = 染色体数的2倍；没有染色单体时，核DNA数等于染色体数。"},{"ep":"bx1-22","n":"BX1-22","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-22/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-22","n":"BX1-22","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-22/rv2.mp3","sec":8.88,"t":"判断一？错，细胞越大，运输效率越低。判断二？错，神经细胞不再分裂。"},{"ep":"bx1-22","n":"BX1-22","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-22/rv3.mp3","sec":6.24,"t":"判断三？对。判断四？错，染色体数目不变。"},{"ep":"bx1-22","n":"BX1-22","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-22/rv4.mp3","sec":5.736,"t":"判断五？错，是赤道板。判断六？对。"},{"ep":"bx1-22","n":"BX1-22","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-22/rv5.mp3","sec":8.424,"t":"七个考点串成一条线：间期复制，前中后末，数目跟着着丝粒走。我们下期再见！"},{"ep":"bx1-23","n":"BX1-23","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-23/in1.mp3","sec":11.616,"t":"同学们好！这节课梳理人教版必修一第六章第一节的下半部分——动植物细胞有丝分裂的比较和观察根尖细胞有丝分裂的实验。"},{"ep":"bx1-23","n":"BX1-23","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-23/in2.mp3","sec":7.344,"t":"高考常考动植物细胞分裂的区别、实验步骤，以及柱形图和曲线图的识别。"},{"ep":"bx1-23","n":"BX1-23","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-23/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-23","n":"BX1-23","p":1,"a":"p1","id":"cm1","src":"assets/audio/BX1-23/cm1.mp3","sec":5.52,"t":"考点一，动植物细胞有丝分裂的区别，在前期和末期。"},{"ep":"bx1-23","n":"BX1-23","p":1,"a":"p1","id":"cm2","src":"assets/audio/BX1-23/cm2.mp3","sec":10.584,"t":"前期纺锤体的形成：植物细胞从细胞两极发出纺锤丝；动物细胞由中心体发出星射线，中心粒在间期倍增。"},{"ep":"bx1-23","n":"BX1-23","p":1,"a":"p1","id":"cm3","src":"assets/audio/BX1-23/cm3.mp3","sec":12.384,"t":"末期细胞质的分裂：植物细胞在赤道板位置形成细胞板，扩展成细胞壁；动物细胞的细胞膜从中部向内凹陷，缢裂成两个子细胞。"},{"ep":"bx1-23","n":"BX1-23","p":1,"a":"p1","id":"cm4","src":"assets/audio/BX1-23/cm4.mp3","sec":9.864,"t":"易错：低等植物细胞也有中心体；判断动物还是植物，最可靠的是看有无细胞壁和末期的分裂方式。"},{"ep":"bx1-23","n":"BX1-23","p":2,"a":"p2","id":"mn1","src":"assets/audio/BX1-23/mn1.mp3","sec":9.36,"t":"考点二，有丝分裂的意义。将亲代细胞的染色体经过复制后，精确地平均分配到两个子细胞中。"},{"ep":"bx1-23","n":"BX1-23","p":2,"a":"p2","id":"mn2","src":"assets/audio/BX1-23/mn2.mp3","sec":3.744,"t":"保持了亲子代细胞之间遗传的稳定性。"},{"ep":"bx1-23","n":"BX1-23","p":2,"a":"p2","id":"mn3","src":"assets/audio/BX1-23/mn3.mp3","sec":10.464,"t":"易错：平均分配的是细胞核中的DNA；细胞质中的DNA，如线粒体DNA，是随机、不均等分配的。"},{"ep":"bx1-23","n":"BX1-23","p":3,"a":"p3","id":"am1","src":"assets/audio/BX1-23/am1.mp3","sec":8.52,"t":"考点三，无丝分裂。分裂过程中没有出现纺锤丝和染色体的变化，所以叫无丝分裂。"},{"ep":"bx1-23","n":"BX1-23","p":3,"a":"p3","id":"am2","src":"assets/audio/BX1-23/am2.mp3","sec":10.032,"t":"过程：细胞核先延长，核的中部向内凹进，缢裂成两个细胞核；接着整个细胞从中部缢裂成两个子细胞。"},{"ep":"bx1-23","n":"BX1-23","p":3,"a":"p3","id":"am3","src":"assets/audio/BX1-23/am3.mp3","sec":2.976,"t":"实例：蛙的红细胞的分裂。"},{"ep":"bx1-23","n":"BX1-23","p":3,"a":"p3","id":"am4","src":"assets/audio/BX1-23/am4.mp3","sec":10.752,"t":"易错：无丝分裂也有DNA的复制；它是真核细胞的分裂方式，原核细胞进行的是二分裂；人的成熟红细胞不分裂。"},{"ep":"bx1-23","n":"BX1-23","p":4,"a":"p4","id":"st1","src":"assets/audio/BX1-23/st1.mp3","sec":11.736,"t":"考点四，观察根尖分生区组织细胞的有丝分裂。解离：用盐酸和酒精1∶1混合的解离液，使组织中的细胞相互分离。"},{"ep":"bx1-23","n":"BX1-23","p":4,"a":"p4","id":"st2","src":"assets/audio/BX1-23/st2.mp3","sec":6.648,"t":"漂洗：用清水漂洗，洗去解离液，防止解离过度，也便于染色。"},{"ep":"bx1-23","n":"BX1-23","p":4,"a":"p4","id":"st3","src":"assets/audio/BX1-23/st3.mp3","sec":6.504,"t":"染色：用甲紫溶液或醋酸洋红液等碱性染料，使染色体着色。"},{"ep":"bx1-23","n":"BX1-23","p":4,"a":"p4","id":"st4","src":"assets/audio/BX1-23/st4.mp3","sec":7.2,"t":"制片：压片使细胞分散开，再用低倍镜找到分生区，换高倍镜观察。"},{"ep":"bx1-23","n":"BX1-23","p":4,"a":"p4","id":"st5","src":"assets/audio/BX1-23/st5.mp3","sec":10.416,"t":"易错：顺序是解离、漂洗、染色、制片，漂洗一定在染色之前；分生区细胞呈正方形、排列紧密。"},{"ep":"bx1-23","n":"BX1-23","p":5,"a":"p5","id":"rs1","src":"assets/audio/BX1-23/rs1.mp3","sec":10.2,"t":"考点五，实验结果分析。视野中大多数细胞处于分裂间期，因为间期在细胞周期中占的时间最长。"},{"ep":"bx1-23","n":"BX1-23","p":5,"a":"p5","id":"rs2","src":"assets/audio/BX1-23/rs2.mp3","sec":8.28,"t":"解离后细胞已经死亡，所以不能看到一个细胞连续分裂的过程，要寻找处于不同时期的细胞。"},{"ep":"bx1-23","n":"BX1-23","p":5,"a":"p5","id":"rs3","src":"assets/audio/BX1-23/rs3.mp3","sec":9.888,"t":"解题方法：某时期细胞数占总数的比例，等于这一时期占细胞周期时间的比例，可以用来估算各时期的时长。"},{"ep":"bx1-23","n":"BX1-23","p":6,"a":"p6","id":"gr1","src":"assets/audio/BX1-23/gr1.mp3","sec":6.888,"t":"考点六，柱形图和曲线图。柱形图中，会变成0的是染色单体。"},{"ep":"bx1-23","n":"BX1-23","p":6,"a":"p6","id":"gr2","src":"assets/audio/BX1-23/gr2.mp3","sec":7.8,"t":"染色单体为0时，染色体数等于核DNA数，对应间期复制前、后期和末期。"},{"ep":"bx1-23","n":"BX1-23","p":6,"a":"p6","id":"gr3","src":"assets/audio/BX1-23/gr3.mp3","sec":8.688,"t":"染色单体不为0时，染色体∶核DNA∶染色单体 = 1∶2∶2，对应前期和中期。"},{"ep":"bx1-23","n":"BX1-23","p":6,"a":"p6","id":"gr4","src":"assets/audio/BX1-23/gr4.mp3","sec":10.992,"t":"曲线图中，核DNA是斜线上升，因为DNA复制需要时间；染色体是垂直上升，因为着丝粒是一下子分裂的。"},{"ep":"bx1-23","n":"BX1-23","p":6,"a":"p6","id":"gr5","src":"assets/audio/BX1-23/gr5.mp3","sec":8.376,"t":"解题方法：先找能变成0的是染色单体，再看有没有斜线区分核DNA和染色体。"},{"ep":"bx1-23","n":"BX1-23","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-23/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-23","n":"BX1-23","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-23/rv2.mp3","sec":6.48,"t":"判断一？错，区别在前期和末期。判断二？对。"},{"ep":"bx1-23","n":"BX1-23","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-23/rv3.mp3","sec":8.832,"t":"判断三？错，无丝分裂也有DNA复制。判断四？错，要先漂洗再染色。"},{"ep":"bx1-23","n":"BX1-23","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-23/rv4.mp3","sec":6.888,"t":"判断五？错，解离后细胞已经死亡。判断六？对。"},{"ep":"bx1-23","n":"BX1-23","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-23/rv5.mp3","sec":8.064,"t":"六个考点串成一条线：前期末期看区别，解离漂洗染色制片。我们下期再见！"},{"ep":"bx1-24","n":"BX1-24","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-24/in1.mp3","sec":6.744,"t":"同学们好！这节课梳理人教版必修一第六章第二节——细胞的分化。"},{"ep":"bx1-24","n":"BX1-24","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-24/in2.mp3","sec":6.744,"t":"高考常考细胞分化的实质、全能性的判断，以及干细胞的类型和应用。"},{"ep":"bx1-24","n":"BX1-24","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-24/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-24","n":"BX1-24","p":1,"a":"p1","id":"cn1","src":"assets/audio/BX1-24/cn1.mp3","sec":12.816,"t":"考点一，细胞分化的概念。在个体发育中，由一个或一种细胞增殖产生的后代，在形态、结构和生理功能上发生稳定性差异的过程。"},{"ep":"bx1-24","n":"BX1-24","p":1,"a":"p1","id":"cn2","src":"assets/audio/BX1-24/cn2.mp3","sec":10.512,"t":"特点一，持久性：细胞分化是一种持久性的变化。特点二，普遍性：它是生物界普遍存在的生命现象。"},{"ep":"bx1-24","n":"BX1-24","p":1,"a":"p1","id":"cn3","src":"assets/audio/BX1-24/cn3.mp3","sec":7.992,"t":"特点三，稳定性：一般来说，分化了的细胞将一直保持分化后的状态，直到死亡。"},{"ep":"bx1-24","n":"BX1-24","p":1,"a":"p1","id":"cn4","src":"assets/audio/BX1-24/cn4.mp3","sec":7.344,"t":"易错：细胞分化使细胞的种类增加，细胞分裂使细胞的数目增加，别混。"},{"ep":"bx1-24","n":"BX1-24","p":2,"a":"p2","id":"es1","src":"assets/audio/BX1-24/es1.mp3","sec":4.752,"t":"考点二，细胞分化的实质：基因的选择性表达。"},{"ep":"bx1-24","n":"BX1-24","p":2,"a":"p2","id":"es2","src":"assets/audio/BX1-24/es2.mp3","sec":8.952,"t":"同一个体的不同细胞，遗传物质相同，但表达的基因不同，所以mRNA和蛋白质不完全相同。"},{"ep":"bx1-24","n":"BX1-24","p":2,"a":"p2","id":"es3","src":"assets/audio/BX1-24/es3.mp3","sec":12.6,"t":"比如，红细胞中表达血红蛋白基因，胰岛B细胞中表达胰岛素基因；而呼吸酶基因、ATP合成酶基因在几乎所有细胞中都表达。"},{"ep":"bx1-24","n":"BX1-24","p":2,"a":"p2","id":"es4","src":"assets/audio/BX1-24/es4.mp3","sec":11.064,"t":"解题方法：判断细胞是否分化，看是否合成了特定的蛋白质，比如血红蛋白、胰岛素、抗体；呼吸酶不能作为依据。"},{"ep":"bx1-24","n":"BX1-24","p":3,"a":"p3","id":"mn1","src":"assets/audio/BX1-24/mn1.mp3","sec":6.576,"t":"考点三，细胞分化的意义。细胞分化是生物个体发育的基础。"},{"ep":"bx1-24","n":"BX1-24","p":3,"a":"p3","id":"mn2","src":"assets/audio/BX1-24/mn2.mp3","sec":6.648,"t":"它使多细胞生物体中的细胞趋向专门化，有利于提高生理功能的效率。"},{"ep":"bx1-24","n":"BX1-24","p":3,"a":"p3","id":"mn3","src":"assets/audio/BX1-24/mn3.mp3","sec":10.008,"t":"考法：分化形成不同的组织和器官。易错：分化后细胞的核遗传物质不变，分化不会改变细胞数目。"},{"ep":"bx1-24","n":"BX1-24","p":4,"a":"p4","id":"tp1","src":"assets/audio/BX1-24/tp1.mp3","sec":11.016,"t":"考点四，细胞的全能性。细胞经分裂和分化后，仍具有产生完整有机体或分化成其他各种细胞的潜能和特性。"},{"ep":"bx1-24","n":"BX1-24","p":4,"a":"p4","id":"tp2","src":"assets/audio/BX1-24/tp2.mp3","sec":7.536,"t":"植物细胞具有全能性：比如胡萝卜韧皮部细胞经组织培养，发育成完整的植株。"},{"ep":"bx1-24","n":"BX1-24","p":4,"a":"p4","id":"tp3","src":"assets/audio/BX1-24/tp3.mp3","sec":9.552,"t":"动物细胞的细胞核具有全能性：比如克隆羊多莉，是把体细胞的细胞核移植到去核卵细胞中培育而成的。"},{"ep":"bx1-24","n":"BX1-24","p":4,"a":"p4","id":"tp4","src":"assets/audio/BX1-24/tp4.mp3","sec":9.456,"t":"全能性大小：受精卵 > 生殖细胞 > 体细胞；一般细胞分化程度越高，全能性越难以实现。"},{"ep":"bx1-24","n":"BX1-24","p":4,"a":"p4","id":"tp5","src":"assets/audio/BX1-24/tp5.mp3","sec":7.2,"t":"易错：多莉说明的是动物细胞的细胞核具有全能性，不是整个动物细胞。"},{"ep":"bx1-24","n":"BX1-24","p":5,"a":"p5","id":"st1","src":"assets/audio/BX1-24/st1.mp3","sec":7.752,"t":"考点五，干细胞。动物和人体内少数具有分裂和分化能力的细胞，叫干细胞。"},{"ep":"bx1-24","n":"BX1-24","p":5,"a":"p5","id":"st2","src":"assets/audio/BX1-24/st2.mp3","sec":5.352,"t":"胚胎干细胞：可以分化成各种组织和器官，全能性高。"},{"ep":"bx1-24","n":"BX1-24","p":5,"a":"p5","id":"st3","src":"assets/audio/BX1-24/st3.mp3","sec":9.648,"t":"造血干细胞：存在于骨髓中，能分化成红细胞、白细胞和血小板等各种血细胞，可用于治疗白血病。"},{"ep":"bx1-24","n":"BX1-24","p":5,"a":"p5","id":"st4","src":"assets/audio/BX1-24/st4.mp3","sec":7.584,"t":"易错：造血干细胞分化出各种血细胞，没有发育成完整个体，不体现全能性。"},{"ep":"bx1-24","n":"BX1-24","p":6,"a":"p6","id":"tr1","src":"assets/audio/BX1-24/tr1.mp3","sec":9.912,"t":"考点六，怎样才算体现了全能性。起点必须是单个细胞或细胞核，终点必须是完整个体或各种细胞。"},{"ep":"bx1-24","n":"BX1-24","p":6,"a":"p6","id":"tr2","src":"assets/audio/BX1-24/tr2.mp3","sec":7.032,"t":"种子萌发长成植株：种子是器官，属于正常的个体发育，不体现全能性。"},{"ep":"bx1-24","n":"BX1-24","p":6,"a":"p6","id":"tr3","src":"assets/audio/BX1-24/tr3.mp3","sec":6.456,"t":"造血干细胞形成血细胞：没有发育成完整个体，也不体现全能性。"},{"ep":"bx1-24","n":"BX1-24","p":6,"a":"p6","id":"tr4","src":"assets/audio/BX1-24/tr4.mp3","sec":8.904,"t":"解题方法：看“起点是不是细胞，终点是不是个体”；植物组织培养、克隆动物才体现全能性。"},{"ep":"bx1-24","n":"BX1-24","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-24/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-24","n":"BX1-24","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-24/rv2.mp3","sec":8.304,"t":"判断一？错，遗传物质不变。判断二？错，细胞分化是持久性的变化。"},{"ep":"bx1-24","n":"BX1-24","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-24/rv3.mp3","sec":7.392,"t":"判断三？对。判断四？错，种子是器官，不体现全能性。"},{"ep":"bx1-24","n":"BX1-24","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-24/rv4.mp3","sec":6.648,"t":"判断五？对。判断六？错，受精卵的全能性最高。"},{"ep":"bx1-24","n":"BX1-24","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-24/rv5.mp3","sec":7.296,"t":"六个考点串成一条线：遗传物质不变，基因选择性表达。我们下期再见！"},{"ep":"bx1-25","n":"BX1-25","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-25/in1.mp3","sec":9.408,"t":"同学们好！这节课梳理人教版必修一第六章第三节——细胞的衰老和死亡，也是必修一的最后一节。"},{"ep":"bx1-25","n":"BX1-25","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-25/in2.mp3","sec":7.272,"t":"高考常考衰老细胞的特征、细胞凋亡与细胞坏死的区别，以及细胞自噬。"},{"ep":"bx1-25","n":"BX1-25","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-25/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-25","n":"BX1-25","p":1,"a":"p1","id":"ag1","src":"assets/audio/BX1-25/ag1.mp3","sec":9.696,"t":"考点一，个体衰老与细胞衰老的关系。单细胞生物：细胞的衰老或死亡就是个体的衰老或死亡。"},{"ep":"bx1-25","n":"BX1-25","p":1,"a":"p1","id":"ag2","src":"assets/audio/BX1-25/ag2.mp3","sec":10.128,"t":"多细胞生物：个体衰老与细胞衰老不是一回事；但个体衰老的过程，也是组成个体的细胞普遍衰老的过程。"},{"ep":"bx1-25","n":"BX1-25","p":1,"a":"p1","id":"ag3","src":"assets/audio/BX1-25/ag3.mp3","sec":9.12,"t":"易错：幼年个体中也有衰老的细胞，老年个体中也有新生的细胞，比如造血干细胞仍在分裂。"},{"ep":"bx1-25","n":"BX1-25","p":2,"a":"p2","id":"ft1","src":"assets/audio/BX1-25/ft1.mp3","sec":9.528,"t":"考点二，衰老细胞的主要特征。细胞内水分减少，细胞萎缩，体积变小，新陈代谢速率减慢。"},{"ep":"bx1-25","n":"BX1-25","p":2,"a":"p2","id":"ft2","src":"assets/audio/BX1-25/ft2.mp3","sec":9.288,"t":"细胞内多种酶的活性降低，比如酪氨酸酶活性降低，黑色素合成减少，所以老年人头发变白。"},{"ep":"bx1-25","n":"BX1-25","p":2,"a":"p2","id":"ft3","src":"assets/audio/BX1-25/ft3.mp3","sec":5.784,"t":"细胞内的色素逐渐积累，比如老年斑；细胞呼吸速率减慢。"},{"ep":"bx1-25","n":"BX1-25","p":2,"a":"p2","id":"ft4","src":"assets/audio/BX1-25/ft4.mp3","sec":9.792,"t":"细胞核的体积增大，核膜内折，染色质收缩、染色加深；细胞膜通透性改变，物质运输功能降低。"},{"ep":"bx1-25","n":"BX1-25","p":2,"a":"p2","id":"ft5","src":"assets/audio/BX1-25/ft5.mp3","sec":12.288,"t":"易错：衰老细胞的细胞体积变小，但细胞核体积变大；“白头发”是酶活性降低，“白化病”是基因异常、不能合成酪氨酸酶，别混。"},{"ep":"bx1-25","n":"BX1-25","p":3,"a":"p3","id":"th1","src":"assets/audio/BX1-25/th1.mp3","sec":11.64,"t":"考点三，细胞衰老的原因。自由基学说：细胞代谢产生的自由基，会攻击和破坏细胞内各种执行正常功能的生物分子。"},{"ep":"bx1-25","n":"BX1-25","p":3,"a":"p3","id":"th2","src":"assets/audio/BX1-25/th2.mp3","sec":9.264,"t":"比如攻击磷脂产生更多自由基，攻击DNA可能引起基因突变，攻击蛋白质使其活性下降。"},{"ep":"bx1-25","n":"BX1-25","p":3,"a":"p3","id":"th3","src":"assets/audio/BX1-25/th3.mp3","sec":10.32,"t":"端粒学说：端粒是每条染色体两端的一段特殊序列的DNA—蛋白质复合体，每次细胞分裂后会缩短一截。"},{"ep":"bx1-25","n":"BX1-25","p":3,"a":"p3","id":"th4","src":"assets/audio/BX1-25/th4.mp3","sec":9.912,"t":"解题方法：端粒内侧的正常基因受到损伤后，细胞活动逐渐异常；原核细胞没有染色体，也就没有端粒。"},{"ep":"bx1-25","n":"BX1-25","p":4,"a":"p4","id":"ap1","src":"assets/audio/BX1-25/ap1.mp3","sec":9.48,"t":"考点四，细胞凋亡。由基因所决定的细胞自动结束生命的过程，也常被称为细胞编程性死亡。"},{"ep":"bx1-25","n":"BX1-25","p":4,"a":"p4","id":"ap2","src":"assets/audio/BX1-25/ap2.mp3","sec":8.352,"t":"实例：蝌蚪尾的消失、人胚胎发育中手指间细胞的凋亡、被病原体感染的细胞的清除。"},{"ep":"bx1-25","n":"BX1-25","p":4,"a":"p4","id":"ap3","src":"assets/audio/BX1-25/ap3.mp3","sec":8.856,"t":"意义：保证多细胞生物体完成正常发育，维持内部环境的稳定，抵御外界各种因素的干扰。"},{"ep":"bx1-25","n":"BX1-25","p":4,"a":"p4","id":"ap4","src":"assets/audio/BX1-25/ap4.mp3","sec":8.4,"t":"易错：细胞凋亡对生物体是有利的；被病原体感染的细胞的清除属于凋亡，不是坏死。"},{"ep":"bx1-25","n":"BX1-25","p":5,"a":"p5","id":"nc1","src":"assets/audio/BX1-25/nc1.mp3","sec":8.904,"t":"考点五，细胞凋亡与细胞坏死的比较。细胞凋亡是基因控制的主动死亡，对机体有利。"},{"ep":"bx1-25","n":"BX1-25","p":5,"a":"p5","id":"nc2","src":"assets/audio/BX1-25/nc2.mp3","sec":11.592,"t":"细胞坏死是在种种不利因素的影响下，由于细胞正常代谢活动受损或中断引起的细胞损伤和死亡，是被动的，对机体有害。"},{"ep":"bx1-25","n":"BX1-25","p":5,"a":"p5","id":"nc3","src":"assets/audio/BX1-25/nc3.mp3","sec":11.856,"t":"解题方法：看原因——自然的、程序性的是凋亡；由极端物理、化学因素或严重病理刺激引起的是坏死，比如烫伤、缺氧。"},{"ep":"bx1-25","n":"BX1-25","p":6,"a":"p6","id":"au1","src":"assets/audio/BX1-25/au1.mp3","sec":10.512,"t":"考点六，细胞自噬。在一定条件下，细胞会将受损或功能退化的细胞结构等，通过溶酶体降解后再利用。"},{"ep":"bx1-25","n":"BX1-25","p":6,"a":"p6","id":"au2","src":"assets/audio/BX1-25/au2.mp3","sec":13.416,"t":"营养缺乏时，细胞通过自噬获得维持生存所需的物质和能量；自噬还能清除受损的细胞器和感染的微生物、毒素，维持细胞内部环境的稳定。"},{"ep":"bx1-25","n":"BX1-25","p":6,"a":"p6","id":"au3","src":"assets/audio/BX1-25/au3.mp3","sec":4.2,"t":"有些激烈的细胞自噬，可能诱导细胞凋亡。"},{"ep":"bx1-25","n":"BX1-25","p":6,"a":"p6","id":"au4","src":"assets/audio/BX1-25/au4.mp3","sec":7.32,"t":"易错：细胞自噬不一定导致细胞死亡；参与自噬的主要细胞器是溶酶体。"},{"ep":"bx1-25","n":"BX1-25","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-25/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-25","n":"BX1-25","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-25/rv2.mp3","sec":10.296,"t":"判断一？错，个体衰老与细胞衰老不同步。判断二？错，是多种酶活性降低，并非所有酶。"},{"ep":"bx1-25","n":"BX1-25","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-25/rv3.mp3","sec":6.456,"t":"判断三？对。判断四？错，凋亡对生物体有利。"},{"ep":"bx1-25","n":"BX1-25","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-25/rv4.mp3","sec":6.504,"t":"判断五？对。判断六？错，自噬不一定导致死亡。"},{"ep":"bx1-25","n":"BX1-25","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-25/rv5.mp3","sec":10.44,"t":"六个考点串成一条线：凋亡由基因决定，坏死是被动的损伤。必修一到这里就全部梳理完了，我们下期再见！"}];
